const OrthogonalTensorKind = enum {
    scalar,
    vector_young,
    exterior_form,
    spinor,
    tensor_spinor,
    mixed_tensor_form,
    unsupported,
};

const OrthogonalTensorDescriptor = struct {
    kind: OrthogonalTensorKind = .unsupported,
    family: symmetry.LieFamily = .b,
    rank: u8 = 0,
    dimension: u16 = 0,
    label_count: u8 = 0,
    young_row_count: usize = 0,
    young_rows: [max_young_rows]u8 = [_]u8{0} ** max_young_rows,
    young_wide_rows: [max_young_rows]usize = [_]usize{0} ** max_young_rows,
    young_row_span: []u8 = &.{},
    young_row_wide_span: []usize = &.{},
    young_box_count: usize = 0,
    column_count: usize = 0,
    column_heights: [max_young_rows]u8 = [_]u8{0} ** max_young_rows,
    column_span: []u8 = &.{},
    form_rank: usize = 0,
    form_profile: u128 = 0,
    form_mask: u64 = 0,
    form_duality: rendering.DualityTag = .none,
    has_spinor: bool = false,
    chirality: u8 = 0,
    tower_power: u16 = 0,

    fn deinit(self: *OrthogonalTensorDescriptor) void {
        const allocator = std.heap.page_allocator;
        allocator.free(self.young_row_span);
        allocator.free(self.young_row_wide_span);
        allocator.free(self.column_span);
        self.* = .{};
    }
};

fn cloneOrthogonalTensorDescriptor(descriptor: OrthogonalTensorDescriptor) !OrthogonalTensorDescriptor {
    const allocator = std.heap.page_allocator;
    var out = descriptor;
    out.young_row_span = &.{};
    out.young_row_wide_span = &.{};
    out.column_span = &.{};
    errdefer out.deinit();
    if (descriptor.young_row_span.len != 0) out.young_row_span = try allocator.dupe(u8, descriptor.young_row_span);
    if (descriptor.young_row_wide_span.len != 0) out.young_row_wide_span = try allocator.dupe(usize, descriptor.young_row_wide_span);
    if (descriptor.column_span.len != 0) out.column_span = try allocator.dupe(u8, descriptor.column_span);
    return out;
}

