const TensorContractionPairing = struct {
    count: u8 = 0,
    left_slots: []u8 = &.{},
    right_slots: []u8 = &.{},

    fn init(capacity: u8) !TensorContractionPairing {
        const allocator = std.heap.page_allocator;
        var pairing: TensorContractionPairing = .{};
        if (capacity != 0) {
            pairing.left_slots = try allocator.alloc(u8, capacity);
            errdefer allocator.free(pairing.left_slots);
            pairing.right_slots = try allocator.alloc(u8, capacity);
        }
        return pairing;
    }

    fn deinit(self: *TensorContractionPairing) void {
        const allocator = std.heap.page_allocator;
        allocator.free(self.left_slots);
        allocator.free(self.right_slots);
        self.* = .{};
    }

    fn append(self: *TensorContractionPairing, left_slot: u8, right_slot: u8) !void {
        const count: usize = self.count;
        if (count == self.left_slots.len or count == self.right_slots.len) return error.UnsupportedTensorPrimitiveTermCap;
        self.left_slots[self.count] = left_slot;
        self.right_slots[self.count] = right_slot;
        self.count += 1;
    }

    fn pop(self: *TensorContractionPairing) void {
        self.count -= 1;
    }

    fn containsLeft(self: TensorContractionPairing, left_slot: u8) bool {
        var index: u8 = 0;
        while (index < self.count) : (index += 1) {
            if (self.left_slots[index] == left_slot) return true;
        }
        return false;
    }

    fn containsRight(self: TensorContractionPairing, right_slot: u8) bool {
        var index: u8 = 0;
        while (index < self.count) : (index += 1) {
            if (self.right_slots[index] == right_slot) return true;
        }
        return false;
    }

    fn containsInput(self: TensorContractionPairing, left_slot_count: u8, input_slot: u8) bool {
        var index: u8 = 0;
        while (index < self.count) : (index += 1) {
            if (input_slot == self.left_slots[index]) return true;
            if (input_slot == left_slot_count + self.right_slots[index]) return true;
        }
        return false;
    }
};

const TensorEndpointSide = enum {
    left,
    right,
    output,
};

const ExplicitEndpoint = struct {
    side: TensorEndpointSide,
    block: rendering.IndexRef,
    descriptor: OrthogonalTensorDescriptor,
    vector_slot_count: usize = 0,
    has_spinor: bool = false,
    factor_count: usize = 0,
    factors: []ExplicitEndpointFactor = &.{},

    fn deinit(self: *ExplicitEndpoint) void {
        const allocator = std.heap.page_allocator;
        const side = self.side;
        const block = self.block;
        self.descriptor.deinit();
        var factor_index: usize = 0;
        while (factor_index < self.factor_count) : (factor_index += 1) {
            self.factors[factor_index].descriptor.deinit();
        }
        allocator.free(self.factors);
        self.* = .{
            .side = side,
            .block = block,
            .descriptor = .{},
        };
    }
};

const ExplicitEndpointFactor = struct {
    block: rendering.IndexRef = 0,
    descriptor: OrthogonalTensorDescriptor = .{},
    vector_slot_count: usize = 0,
    has_spinor: bool = false,
};

const TensorCompilerChannel = struct {
    operator_id: u32,
    dimension: u16,
    left: ExplicitEndpoint,
    right: ExplicitEndpoint,
    output: ExplicitEndpoint,

    fn deinit(self: *TensorCompilerChannel) void {
        const operator_id = self.operator_id;
        const dimension = self.dimension;
        self.left.deinit();
        self.right.deinit();
        self.output.deinit();
        self.* = .{
            .operator_id = operator_id,
            .dimension = dimension,
            .left = .{ .side = .left, .block = 0, .descriptor = .{} },
            .right = .{ .side = .right, .block = 0, .descriptor = .{} },
            .output = .{ .side = .output, .block = 0, .descriptor = .{} },
        };
    }
};

