    fn deinit(self: *BrauerWord) void {
        const allocator = std.heap.page_allocator;
        allocator.free(self.edges);
        self.* = .{};
    }
};

const BrauerCandidate = struct {
    word_count: usize = 0,
    word_capacity: usize = 0,
    words: []BrauerWord = &.{},

    fn deinit(self: *BrauerCandidate) void {
        const allocator = std.heap.page_allocator;
        var word_index: usize = 0;
        while (word_index < self.word_count) : (word_index += 1) {
            self.words[word_index].deinit();
        }
        allocator.free(self.words);
        self.* = .{};
    }

    fn append(self: *BrauerCandidate, word: BrauerWord) !void {
        try ensureBrauerCandidateWordCapacity(self, self.word_count + 1);
        self.words[self.word_count] = word;
        self.word_count += 1;
    }

    fn appendClone(self: *BrauerCandidate, word: BrauerWord) !void {
        var owned = try cloneBrauerWord(word);
        errdefer owned.deinit();
        try self.append(moveBrauerWord(&owned));
    }
};

fn moveBrauerWord(word: *BrauerWord) BrauerWord {
    const out = word.*;
    word.* = .{};
    return out;
}

fn cloneBrauerWord(word: BrauerWord) !BrauerWord {
    const allocator = std.heap.page_allocator;
    var out = BrauerWord{ .coefficient = word.coefficient };
    if (word.edge_count != 0) {
        out.edges = try allocator.alloc(BrauerEdge, word.edge_count);
        @memcpy(out.edges[0..word.edge_count], word.edges[0..word.edge_count]);
        out.edge_count = word.edge_count;
        out.edge_capacity = word.edge_count;
    }
    return out;
}

fn moveBrauerCandidate(candidate: *BrauerCandidate) BrauerCandidate {
    const out = candidate.*;
    candidate.* = .{};
    return out;
}

