    atom_count: usize = 0,
    atom_capacity: usize = 0,
    atoms: []VectorBrauerAtom = &.{},

    fn deinit(self: *TensorOnlyActionTermFragment) void {
        const allocator = std.heap.page_allocator;
        allocator.free(self.atoms);
        self.* = .{};
    }
};

const TensorOnlyActionFragmentSpan = struct {
    first_fragment: usize = 0,
    fragment_count: usize = 0,
    available: bool = false,
};

fn moveVectorBrauerTerm(term: *VectorBrauerTerm) VectorBrauerTerm {
    const out = term.*;
    term.* = .{};
    return out;
}

fn cloneVectorBrauerTerm(term: VectorBrauerTerm) !VectorBrauerTerm {
    const allocator = std.heap.page_allocator;
    var out = VectorBrauerTerm{ .coefficient = term.coefficient };
    if (term.atom_count != 0) {
        out.atoms = try allocator.alloc(VectorBrauerAtom, term.atom_count);
        @memcpy(out.atoms[0..term.atom_count], term.atoms[0..term.atom_count]);
        out.atom_count = term.atom_count;
        out.atom_capacity = term.atom_count;
    }
    return out;
}

fn moveTensorOnlyActionTermFragment(fragment: *TensorOnlyActionTermFragment) TensorOnlyActionTermFragment {
    const out = fragment.*;
    fragment.* = .{};
    return out;
}

fn cloneTensorOnlyActionTermFragment(fragment: TensorOnlyActionTermFragment) !TensorOnlyActionTermFragment {
    const allocator = std.heap.page_allocator;
    var out = TensorOnlyActionTermFragment{ .coefficient = fragment.coefficient };
    if (fragment.atom_count != 0) {
        out.atoms = try allocator.alloc(VectorBrauerAtom, fragment.atom_count);
        @memcpy(out.atoms[0..fragment.atom_count], fragment.atoms[0..fragment.atom_count]);
        out.atom_count = fragment.atom_count;
        out.atom_capacity = fragment.atom_count;
    }
    return out;
}

const VectorBrauerProgram = struct {
    candidate_count: usize = 0,
    pivot_count: usize = 0,
    term_count: usize = 0,
    candidate_capacity: usize = 0,
    candidates: []BrauerCandidate = &.{},
    pivots: []usize = &.{},
    inverse_gram: []Rational = &.{},
    term_capacity: usize = 0,
    terms: []VectorBrauerTerm = &.{},

    fn deinit(self: *VectorBrauerProgram) void {
        const allocator = std.heap.page_allocator;
        var candidate_index: usize = 0;
        while (candidate_index < self.candidate_count) : (candidate_index += 1) {
            self.candidates[candidate_index].deinit();
        }
        var term_index: usize = 0;
        while (term_index < self.term_count) : (term_index += 1) {
            self.terms[term_index].deinit();
        }
        allocator.free(self.candidates);
        allocator.free(self.pivots);
        allocator.free(self.inverse_gram);
        allocator.free(self.terms);
        self.* = .{};
    }
};

