const TraceRemovalPathBuffer = struct {
    count: usize = 0,
    capacity: usize = 0,
    paths: []TraceRemovalPath = &.{},

    fn deinit(self: *TraceRemovalPathBuffer) void {
        const allocator = std.heap.page_allocator;
        var path_index: usize = 0;
        while (path_index < self.count) : (path_index += 1) {
            self.paths[path_index].deinit();
        }
        allocator.free(self.paths);
        self.* = .{};
    }

    fn append(self: *TraceRemovalPathBuffer, path: TraceRemovalPath) !void {
        try ensureTraceRemovalPathBufferCapacity(self, self.count + 1);
        self.paths[self.count] = try cloneTraceRemovalPath(path);
        self.count += 1;
    }
};

