    trace_branches: []TensorTraceRemovalBranch = &.{},
    hodge_duality: rendering.DualityTag = .none,

    fn deinit(self: *EndpointProjector) void {
        const allocator = std.heap.page_allocator;
        var operator_index: usize = 0;
        while (operator_index < self.operator_count) : (operator_index += 1) {
            allocator.free(self.operators[operator_index].slots);
