    candidate_count_limit: usize = std.math.maxInt(usize),
    gram_action_pair_work_limit: u64 = max_tensor_gram_action_pair_work,
    term_pair_work_limit: u64 = max_tensor_term_pair_work,
    sparse_pivot_row_term_limit: usize = std.math.maxInt(usize),
    pair_merge_entry_limit: usize = std.math.maxInt(usize),
    output_term_count_limit: usize = std.math.maxInt(usize),
    output_term_page_limit: usize = std.math.maxInt(usize),
    coefficient_bit_limit: u16 = 127,
    trace_generator_count_limit: usize = max_tensor_trace_closure_basis,
    trace_closure_basis_limit: usize = max_tensor_trace_closure_basis,
};

/// TensorOnlyCapBoundary names one fixed boundary relevant to production tensor-only routing.
pub const TensorOnlyCapBoundary = enum {
    young_rows,
    endpoint_factors,
    legacy_vector_slot_u8,
    trace_removal_rank_u8,
    vector_young_boxes,
    vector_brauer_edges,
    trace_closure_basis,
    hodge_epsilon_components,
    coefficient_bits,
    term_count_u16_adapters,
};

/// TensorOnlyCapDisposition classifies whether a boundary is policy, compatibility, or unfinished work.
pub const TensorOnlyCapDisposition = enum {
    resource_policy,
    span_backed_compact_public_cap,
    public_span_ownership_audit,
    legacy_bypass_required,
    algorithmic_cleanup,
    hard_default_needs_policy,
    wide_api_with_compact_adapter,
};

/// TensorOnlyCapAuditEntry reports one fixed tensor-only boundary without allocating.
pub const TensorOnlyCapAuditEntry = struct {
    boundary: TensorOnlyCapBoundary = .young_rows,
    disposition: TensorOnlyCapDisposition = .resource_policy,
    hard_limit: usize = 0,
    policy_limit: usize = 0,
    can_stop_supported_route: bool = false,
};

const tensor_only_cap_audit_entry_count = 10;

/// TensorOnlyCapAudit lists the fixed boundaries that still matter to production tensor-only routing.
pub const TensorOnlyCapAudit = struct {
    entry_count: usize = 0,
    entries: [tensor_only_cap_audit_entry_count]TensorOnlyCapAuditEntry = [_]TensorOnlyCapAuditEntry{.{}} ** tensor_only_cap_audit_entry_count,

    /// items returns the populated cap entries.
    pub fn items(self: *const TensorOnlyCapAudit) []const TensorOnlyCapAuditEntry {
        return self.entries[0..self.entry_count];
    }

    fn append(self: *TensorOnlyCapAudit, entry: TensorOnlyCapAuditEntry) void {
        self.entries[self.entry_count] = entry;
        self.entry_count += 1;
    }
};

/// tensorOnlyCapAudit reports fixed tensor-only caps and which are production blockers.
pub fn tensorOnlyCapAudit(policy: TensorOnlyResourcePolicy) TensorOnlyCapAudit {
    var audit: TensorOnlyCapAudit = .{};
    audit.append(.{
        .boundary = .young_rows,
        .disposition = .span_backed_compact_public_cap,
        .hard_limit = max_young_rows,
        .can_stop_supported_route = true,
    });
    audit.append(.{
        .boundary = .endpoint_factors,
        .disposition = .public_span_ownership_audit,
        .hard_limit = max_tensor_endpoint_factors,
        .can_stop_supported_route = true,
    });
    audit.append(.{
        .boundary = .legacy_vector_slot_u8,
        .disposition = .legacy_bypass_required,
        .hard_limit = std.math.maxInt(u8),
    });
    audit.append(.{
        .boundary = .trace_removal_rank_u8,
        .disposition = .algorithmic_cleanup,
        .hard_limit = std.math.maxInt(u8),
        .can_stop_supported_route = true,
    });
    audit.append(.{
        .boundary = .vector_young_boxes,
        .disposition = .legacy_bypass_required,
        .hard_limit = max_vector_young_boxes,
    });
    audit.append(.{
        .boundary = .vector_brauer_edges,
        .disposition = .legacy_bypass_required,
        .hard_limit = max_vector_brauer_edges,
    });
    audit.append(.{
        .boundary = .trace_closure_basis,
        .disposition = .resource_policy,
        .hard_limit = max_tensor_trace_closure_basis,
        .policy_limit = @min(policy.trace_generator_count_limit, policy.trace_closure_basis_limit),
        .can_stop_supported_route = true,
    });
    audit.append(.{
        .boundary = .hodge_epsilon_components,
        .disposition = .hard_default_needs_policy,
        .hard_limit = max_tensor_hodge_epsilon_components,
        .can_stop_supported_route = true,
    });
    audit.append(.{
        .boundary = .coefficient_bits,
        .disposition = .resource_policy,
        .hard_limit = policy.coefficient_bit_limit,
        .policy_limit = policy.coefficient_bit_limit,
        .can_stop_supported_route = true,
    });
    audit.append(.{
        .boundary = .term_count_u16_adapters,
        .disposition = .wide_api_with_compact_adapter,
        .hard_limit = std.math.maxInt(u16),
    });
    return audit;
}

