const TensorSparsePivotAudit = struct {
    candidate_count: usize = 0,
    row_count: usize = 0,
    dense_candidate_pair_count: usize = 0,
    dense_gram_entry_count: usize = 0,
    dense_inverse_entry_count: usize = 0,
    support_candidate_pair_probe_count: usize = 0,
    support_pruned_candidate_pair_count: usize = 0,
    min_support_width: usize = 0,
    max_support_width: usize = 0,
    rank: usize = 0,
    basis_count: usize = 0,
    max_row_width: usize = 0,
    total_row_width: usize = 0,
    rejected_dense_rows: usize = 0,
    max_coefficient_bits: u16 = 0,
    total_pair_action_terms: u64 = 0,
    max_pair_action_terms: usize = 0,
    active_pair_count: usize = 0,
    max_pair_merged_terms: usize = 0,
    output_term_count: usize = 0,

    fn recordAcceptedRow(self: *TensorSparsePivotAudit, row: TensorSparsePivotRow) void {
        self.rank += 1;
        self.basis_count = self.rank;
        const terms = tensorSparsePivotRowTerms(&row);
        const transform_terms = tensorSparsePivotRowTransformTerms(&row);
        self.total_row_width += terms.len;
        if (terms.len > self.max_row_width) self.max_row_width = terms.len;
        for (terms) |term| {
            const bits = rationalCoefficientBits(term.coefficient);
            if (bits > self.max_coefficient_bits) self.max_coefficient_bits = bits;
        }
        for (transform_terms) |term| {
            const bits = rationalCoefficientBits(term.coefficient);
            if (bits > self.max_coefficient_bits) self.max_coefficient_bits = bits;
        }
    }
};

