const TensorSparseSupportIndex = struct {
    buckets: []TensorSparseSupportBucket = &.{},
    bucket_by_signature: std.AutoHashMap(u64, usize),
    seen_candidates: []u32 = &.{},
    seen_generation: u32 = 0,

    fn init(allocator: std.mem.Allocator) TensorSparseSupportIndex {
        return .{ .bucket_by_signature = std.AutoHashMap(u64, usize).init(allocator) };
    }

    fn deinit(self: *TensorSparseSupportIndex) void {
        const allocator = std.heap.page_allocator;
        var bucket_index: usize = 0;
        while (bucket_index < self.buckets.len) : (bucket_index += 1) {
            self.buckets[bucket_index].deinit();
        }
        allocator.free(self.buckets);
        allocator.free(self.seen_candidates);
        self.bucket_by_signature.deinit();
        self.* = TensorSparseSupportIndex.init(allocator);
    }
};

