fn moveTensorEndpointActionWord(word: *TensorEndpointActionWord) TensorEndpointActionWord {
    const out = word.*;
    word.* = .{};
    return out;
}

fn cloneTensorEndpointActionWord(word: TensorEndpointActionWord) !TensorEndpointActionWord {
    var out = TensorEndpointActionWord{
        .word = try cloneBrauerWord(word.word),
    };
    errdefer out.deinit();
    try copyTensorEndpointActionWordHodgeActions(&out, word);
    return out;
}

const TensorEndpointActionBuffer = struct {
    key: TensorEndpointActionKey = .{},
    word_first: usize = 0,
    word_count: usize = 0,
    words: []TensorEndpointActionWord = &.{},
