const TensorOnlyProgram = struct {
    channel: TensorOnlyChannel,
    resource_policy: TensorOnlyResourcePolicy = .{},
    raw_diagram_count: usize = 0,
    raw_stream_kind: TensorOnlyRawDiagramStreamKind = .trace_surviving,
    raw_diagrams: []TensorBrauerDiagram = &.{},
    projector_count: usize = 0,
    projector_capacity: usize = 0,
    projector_keys: []TensorOnlyEndpointProjectorKey = &.{},
    projectors: []EndpointProjector = &.{},
    left_projector_index: usize = 0,
    right_projector_index: usize = 0,
    output_projector_index: usize = 0,
    endpoint_action_count: usize = 0,
    endpoint_action_word_count: usize = 0,
    endpoint_action_capacity: usize = 0,
    endpoint_actions: []TensorEndpointActionBuffer = &.{},
    endpoint_action_word_capacity: usize = 0,
    endpoint_action_words: []TensorEndpointActionWord = &.{},
    endpoint_action_bucket_count: usize = 0,
    endpoint_action_buckets: []usize = &.{},
    endpoint_action_next: []usize = &.{},
    endpoint_action_compaction_audit: TensorEndpointActionCompactionAudit = .{},
    action_fragment_spans: []TensorOnlyActionFragmentSpan = &.{},
    action_fragments: []TensorOnlyActionTermFragment = &.{},
    adjoint_action_fragment_spans: []TensorOnlyActionFragmentSpan = &.{},
    adjoint_action_fragments: []TensorOnlyActionTermFragment = &.{},
    projected_raw_action_indices: []usize = &.{},
    projected_raw_action_span_count: usize = 0,
    projected_raw_action_span_capacity: usize = 0,
    projected_raw_action_spans: []TensorOnlyProjectedRawActionSpan = &.{},
    candidate_count: usize = 0,
    candidate_capacity: usize = 0,
    candidates: []TensorOnlyCandidateWord = &.{},
    candidate_canonicalization_audit: TensorCandidateCanonicalizationAudit = .{},
    pivot_count: usize = 0,
    pivots: []usize = &.{},
    sparse_pivot_rows: []TensorSparsePivotRow = &.{},
    sparse_pivot_audit: TensorSparsePivotAudit = .{},
    inverse_gram: []Rational = &.{},
    pair_term_indices: []TensorOnlyPairTermIndex = &.{},
    pair_column_count: usize = 0,
    compact_pair_term_indices: bool = false,
    active_pair_term_count: usize = 0,
    active_pair_term_indices: []usize = &.{},
    sparse_projector_rows: []TensorSparseProjectorRow = &.{},
    term_count: usize = 0,

    fn deinit(self: *TensorOnlyProgram) void {
        const allocator = std.heap.page_allocator;
        var projector_index: usize = 0;
        while (projector_index < self.projector_count) : (projector_index += 1) {
            self.projectors[projector_index].deinit();
            self.projector_keys[projector_index].deinit();
        }
        var action_index: usize = 0;
        while (action_index < self.endpoint_action_count) : (action_index += 1) {
            self.endpoint_actions[action_index].deinit();
        }
        var candidate_index: usize = 0;
        while (candidate_index < self.candidate_count) : (candidate_index += 1) {
            self.candidates[candidate_index].deinit();
        }
        var raw_index: usize = 0;
        while (raw_index < self.raw_diagrams.len) : (raw_index += 1) {
            self.raw_diagrams[raw_index].deinit();
        }
        var action_word_index: usize = 0;
        const owned_action_word_count = @min(self.endpoint_action_word_count, self.endpoint_action_words.len);
        while (action_word_index < owned_action_word_count) : (action_word_index += 1) {
            self.endpoint_action_words[action_word_index].deinit();
        }
        const resource_policy = self.resource_policy;
        self.channel.deinit();
        allocator.free(self.raw_diagrams);
        allocator.free(self.projector_keys);
        allocator.free(self.projectors);
        allocator.free(self.endpoint_actions);
        allocator.free(self.endpoint_action_words);
        allocator.free(self.endpoint_action_buckets);
        allocator.free(self.endpoint_action_next);
        for (self.action_fragments) |*fragment| fragment.deinit();
        allocator.free(self.action_fragment_spans);
        allocator.free(self.action_fragments);
        for (self.adjoint_action_fragments) |*fragment| fragment.deinit();
        allocator.free(self.adjoint_action_fragment_spans);
        allocator.free(self.adjoint_action_fragments);
        allocator.free(self.projected_raw_action_indices);
        allocator.free(self.projected_raw_action_spans);
        allocator.free(self.candidates);
        allocator.free(self.pivots);
        allocator.free(self.inverse_gram);
        allocator.free(self.pair_term_indices);
        allocator.free(self.active_pair_term_indices);
        var sparse_row: usize = 0;
        while (sparse_row < self.sparse_pivot_rows.len) : (sparse_row += 1) {
            self.sparse_pivot_rows[sparse_row].deinit();
        }
        allocator.free(self.sparse_pivot_rows);
        var projector_row: usize = 0;
        while (projector_row < self.sparse_projector_rows.len) : (projector_row += 1) {
            self.sparse_projector_rows[projector_row].deinit();
        }
        allocator.free(self.sparse_projector_rows);
        self.* = .{ .channel = .{}, .resource_policy = resource_policy };
    }
};

const VectorBrauerProgramTerm = struct {
    left_candidate: usize,
    right_candidate: usize,
