fn nextTensorAppendCapacity(current_capacity: usize, required_capacity: usize) !usize {
    var capacity = if (current_capacity == 0) @as(usize, 4) else current_capacity;
    while (capacity < required_capacity) {
        capacity = std.math.mul(usize, capacity, 2) catch return error.ProjectorProgramTooLarge;
    }
    return capacity;
}

fn ensureBrauerCandidateWordCapacity(candidate: *BrauerCandidate, required_capacity: usize) !void {
    var current_capacity = candidate.word_capacity;
    if (current_capacity == 0) current_capacity = candidate.words.len;
    if (required_capacity <= current_capacity) {
        candidate.word_capacity = current_capacity;
        return;
    }
    const allocator = std.heap.page_allocator;
    const next_capacity = try nextTensorAppendCapacity(current_capacity, required_capacity);
    candidate.words = try allocator.realloc(candidate.words, next_capacity);
    candidate.word_capacity = next_capacity;
}

fn ensureBrauerWordEdgeCapacity(word: *BrauerWord, required_capacity: usize) !void {
    var current_capacity = word.edge_capacity;
    if (current_capacity == 0) current_capacity = word.edges.len;
