    }
    const allocator = std.heap.page_allocator;
    const next_capacity = try nextTensorAppendCapacity(current_capacity, required_capacity);
    word.edges = try allocator.realloc(word.edges, next_capacity);
    word.edge_capacity = next_capacity;
}

fn ensureVectorBrauerProgramCandidateCapacity(program: *VectorBrauerProgram, required_capacity: usize) !void {
    if (program.candidate_capacity >= required_capacity) return;
    const allocator = std.heap.page_allocator;
    const capacity = try nextTensorAppendCapacity(program.candidate_capacity, required_capacity);
    const candidates = try allocator.alloc(BrauerCandidate, capacity);
    @memcpy(candidates[0..program.candidate_count], program.candidates[0..program.candidate_count]);
    allocator.free(program.candidates);
    program.candidates = candidates;
    program.candidate_capacity = capacity;
}

fn ensureVectorBrauerProgramTermCapacity(program: *VectorBrauerProgram, required_capacity: usize) !void {
