    try setTensorTraceRemovalBranchStep(branch, branch.trace_count, slot_a, slot_b);
}

fn cloneTensorTraceRemovalBranch(branch: TensorTraceRemovalBranch) !TensorTraceRemovalBranch {
    var out = TensorTraceRemovalBranch{ .coefficient = branch.coefficient };
    errdefer out.deinit();
    try ensureTensorTraceRemovalBranchStepCapacity(&out, branch.trace_count);
    @memcpy(out.trace_slot_a[0..branch.trace_count], branch.trace_slot_a[0..branch.trace_count]);
    @memcpy(out.trace_slot_b[0..branch.trace_count], branch.trace_slot_b[0..branch.trace_count]);
    out.trace_count = branch.trace_count;
    return out;
}

fn ensureTensorOnlyProgramEndpointProjectorCapacity(program: *TensorOnlyProgram, required_capacity: usize) !void {
    var current_capacity = program.projector_capacity;
    if (current_capacity == 0) current_capacity = program.projectors.len;
    if (required_capacity <= current_capacity) {
        program.projector_capacity = current_capacity;
        return;
    }
    const allocator = std.heap.page_allocator;
    const next_capacity = try nextTensorAppendCapacity(current_capacity, required_capacity);
    program.projector_keys = try allocator.realloc(program.projector_keys, next_capacity);
    program.projectors = try allocator.realloc(program.projectors, next_capacity);
    var projector_index = current_capacity;
    while (projector_index < next_capacity) : (projector_index += 1) {
        program.projector_keys[projector_index] = .{};
        program.projectors[projector_index] = .{};
    }
    program.projector_capacity = next_capacity;
}

