fn copyTensorEndpointActionWordHodgeActions(out: *TensorEndpointActionWord, source: TensorEndpointActionWord) !void {
    try ensureTensorEndpointActionWordHodgeCapacity(out, source.hodge_count);
    @memcpy(out.hodge_actions[0..source.hodge_count], source.hodge_actions[0..source.hodge_count]);
    out.hodge_count = source.hodge_count;
}

fn tensorEndpointActionWordWithBrauerWord(template: TensorEndpointActionWord, word: BrauerWord) !TensorEndpointActionWord {
    var owned_word = word;
    errdefer owned_word.deinit();
    var out = TensorEndpointActionWord{ .word = moveBrauerWord(&owned_word) };
    errdefer out.deinit();
    try copyTensorEndpointActionWordHodgeActions(&out, template);
    return out;
}

