    if (current_capacity == 0) current_capacity = buffer.words.len;
    if (required_capacity <= current_capacity) {
        buffer.word_capacity = current_capacity;
        return;
    }
    const allocator = std.heap.page_allocator;
    const next_capacity = try nextTensorAppendCapacity(current_capacity, required_capacity);
    buffer.words = try allocator.realloc(buffer.words, next_capacity);
    buffer.next = try allocator.realloc(buffer.next, next_capacity);
    buffer.word_capacity = next_capacity;
}

fn ensureTensorOnlyProgramEndpointActionCapacity(program: *TensorOnlyProgram, required_capacity: usize) !void {
    var current_capacity = program.endpoint_action_capacity;
    if (current_capacity == 0) current_capacity = program.endpoint_actions.len;
    if (required_capacity <= current_capacity) {
        program.endpoint_action_capacity = current_capacity;
        return;
    }
    const allocator = std.heap.page_allocator;
    const next_capacity = try nextTensorAppendCapacity(current_capacity, required_capacity);
    program.endpoint_actions = try allocator.realloc(program.endpoint_actions, next_capacity);
    const old_next_len = program.endpoint_action_next.len;
    program.endpoint_action_next = try allocator.realloc(program.endpoint_action_next, next_capacity);
    var next_index = old_next_len;
    while (next_index < next_capacity) : (next_index += 1) {
        program.endpoint_action_next[next_index] = tensor_endpoint_action_empty_bucket;
    }
    program.endpoint_action_capacity = next_capacity;
}

fn ensureTensorOnlyProgramEndpointActionWordCapacity(program: *TensorOnlyProgram, required_capacity: usize) !void {
    var current_capacity = program.endpoint_action_word_capacity;
    if (current_capacity == 0) current_capacity = program.endpoint_action_words.len;
    if (required_capacity <= current_capacity) {
        program.endpoint_action_word_capacity = current_capacity;
        return;
    }
    const allocator = std.heap.page_allocator;
    const next_capacity = try nextTensorAppendCapacity(current_capacity, required_capacity);
    program.endpoint_action_words = try allocator.realloc(program.endpoint_action_words, next_capacity);
    var action_index: usize = 0;
    while (action_index < program.endpoint_action_count) : (action_index += 1) {
        if (program.endpoint_actions[action_index].owns_words) continue;
        const word_first = program.endpoint_actions[action_index].word_first;
        const word_count = program.endpoint_actions[action_index].word_count;
        program.endpoint_actions[action_index].words = program.endpoint_action_words[word_first .. word_first + word_count];
    }
    program.endpoint_action_word_capacity = next_capacity;
}

fn ensureTensorOnlyProjectedRawActionSpanCapacity(program: *TensorOnlyProgram, required_capacity: usize) !void {
    var current_capacity = program.projected_raw_action_span_capacity;
    if (current_capacity == 0) current_capacity = program.projected_raw_action_spans.len;
    if (required_capacity <= current_capacity) {
        program.projected_raw_action_span_capacity = current_capacity;
        return;
    }
    const allocator = std.heap.page_allocator;
    const next_capacity = try nextTensorAppendCapacity(current_capacity, required_capacity);
    program.projected_raw_action_spans = try allocator.realloc(program.projected_raw_action_spans, next_capacity);
    program.projected_raw_action_span_capacity = next_capacity;
}

fn ensureTensorEndpointActionBuckets(program: *TensorOnlyProgram, required_action_count: usize) !void {
    const required_bucket_count = std.math.mul(usize, required_action_count, 2) catch return error.ProjectorProgramTooLarge;
    if (program.endpoint_action_bucket_count >= required_bucket_count and program.endpoint_action_bucket_count != 0) return;
    const allocator = std.heap.page_allocator;
    var bucket_count = if (program.endpoint_action_bucket_count == 0) @as(usize, 8) else program.endpoint_action_bucket_count;
    while (bucket_count < required_bucket_count) {
        bucket_count = std.math.mul(usize, bucket_count, 2) catch return error.ProjectorProgramTooLarge;
    }
    const buckets = try allocator.alloc(usize, bucket_count);
    errdefer allocator.free(buckets);
    @memset(buckets, tensor_endpoint_action_empty_bucket);

    var action_index: usize = 0;
    while (action_index < program.endpoint_action_count) : (action_index += 1) {
        const bucket = tensorEndpointActionKeyHash(program.endpoint_actions[action_index].key) % bucket_count;
        program.endpoint_action_next[action_index] = buckets[bucket];
        buckets[bucket] = action_index;
    }

    allocator.free(program.endpoint_action_buckets);
    program.endpoint_action_buckets = buckets;
    program.endpoint_action_bucket_count = bucket_count;
}

fn ensureTensorOnlyProgramCandidateCapacity(program: *TensorOnlyProgram, required_capacity: usize) !void {
    var current_capacity = program.candidate_capacity;
    if (current_capacity == 0) current_capacity = program.candidates.len;
    if (required_capacity <= current_capacity) {
        program.candidate_capacity = current_capacity;
        return;
    }
    const allocator = std.heap.page_allocator;
    const next_capacity = try nextTensorAppendCapacity(current_capacity, required_capacity);
    program.candidates = try allocator.realloc(program.candidates, next_capacity);
    program.candidate_capacity = next_capacity;
}

fn ensureTensorSparseSupportBucketCapacity(bucket: *TensorSparseSupportBucket, required_capacity: usize) !void {
    var current_capacity = bucket.candidate_capacity;
    if (current_capacity == 0) current_capacity = bucket.candidates.len;
    if (required_capacity <= current_capacity) {
        bucket.candidate_capacity = current_capacity;
        return;
    }
    const allocator = std.heap.page_allocator;
    const next_capacity = try nextTensorAppendCapacity(current_capacity, required_capacity);
    bucket.candidates = try allocator.realloc(bucket.candidates, next_capacity);
    bucket.candidate_capacity = next_capacity;
}

fn tensorSparsePivotRowTerms(row: *const TensorSparsePivotRow) []const TensorSparsePivotTerm {
    return row.terms[0..row.term_count];
}

fn tensorSparsePivotRowTermsMut(row: *TensorSparsePivotRow) []TensorSparsePivotTerm {
    return row.terms[0..row.term_count];
}

fn tensorSparsePivotRowTransformTerms(row: *const TensorSparsePivotRow) []const TensorSparsePivotTerm {
    return row.transform_terms[0..row.transform_term_count];
}

fn tensorSparsePivotRowTransformTermsMut(row: *TensorSparsePivotRow) []TensorSparsePivotTerm {
    return row.transform_terms[0..row.transform_term_count];
}

fn tensorSparseProjectorRowTerms(row: *const TensorSparseProjectorRow) []const TensorSparsePivotTerm {
    return row.terms[0..row.term_count];
}

fn tensorSparseProjectorRowTermsMut(row: *TensorSparseProjectorRow) []TensorSparsePivotTerm {
    return row.terms[0..row.term_count];
}

fn ensureTensorSparseTermCapacity(terms: *[]TensorSparsePivotTerm, capacity: *usize, required_capacity: usize) !void {
    var current_capacity = capacity.*;
    if (current_capacity == 0) current_capacity = terms.*.len;
    if (required_capacity <= current_capacity) {
        capacity.* = current_capacity;
        return;
    }
    const allocator = std.heap.page_allocator;
    const next_capacity = try nextTensorAppendCapacity(current_capacity, required_capacity);
    terms.* = try allocator.realloc(terms.*, next_capacity);
    capacity.* = next_capacity;
}

fn ensureTensorOnlyMergedTermCountEntryCapacity(set: *TensorOnlyMergedTermCountSet, required_capacity: usize) !void {
    var current_capacity = set.entry_capacity;
    if (current_capacity == 0) current_capacity = set.entries.len;
    if (required_capacity <= current_capacity) {
        set.entry_capacity = current_capacity;
        return;
    }
    const allocator = std.heap.page_allocator;
    const next_capacity = try nextTensorAppendCapacity(current_capacity, required_capacity);
    set.entries = try allocator.realloc(set.entries, next_capacity);
    const old_next_len = set.next.len;
    set.next = try allocator.realloc(set.next, next_capacity);
    var next_index = old_next_len;
    while (next_index < next_capacity) : (next_index += 1) {
        set.next[next_index] = tensor_endpoint_action_empty_bucket;
    }
    set.entry_capacity = next_capacity;
}

fn ensureTensorOnlyMergedTermCountBuckets(set: *TensorOnlyMergedTermCountSet, required_entry_count: usize) !void {
    const required_bucket_count = std.math.mul(usize, required_entry_count, 2) catch return error.ProjectorProgramTooLarge;
    if (set.bucket_count >= required_bucket_count and set.bucket_count != 0) return;
    const allocator = std.heap.page_allocator;
    var bucket_count = if (set.bucket_count == 0) @as(usize, 8) else set.bucket_count;
    while (bucket_count < required_bucket_count) {
        bucket_count = std.math.mul(usize, bucket_count, 2) catch return error.ProjectorProgramTooLarge;
    }
    const buckets = try allocator.alloc(usize, bucket_count);
    errdefer allocator.free(buckets);
    @memset(buckets, tensor_endpoint_action_empty_bucket);

    var entry_index: usize = 0;
    while (entry_index < set.entry_count) : (entry_index += 1) {
        const bucket = set.entries[entry_index].hash % bucket_count;
        set.next[entry_index] = buckets[bucket];
        buckets[bucket] = entry_index;
    }

    allocator.free(set.buckets);
    set.buckets = buckets;
    set.bucket_count = bucket_count;
}

fn ensureBrauerCandidateBufferCapacity(buffer: *BrauerCandidateBuffer, required_capacity: usize) !void {
    var current_capacity = buffer.capacity;
    if (current_capacity == 0) current_capacity = buffer.candidates.len;
    if (required_capacity <= current_capacity) {
        buffer.capacity = current_capacity;
        return;
    }
    const allocator = std.heap.page_allocator;
    const next_capacity = try nextTensorAppendCapacity(current_capacity, required_capacity);
    buffer.candidates = try allocator.realloc(buffer.candidates, next_capacity);
    buffer.capacity = next_capacity;
}

fn ensureTraceRemovalPathBufferCapacity(buffer: *TraceRemovalPathBuffer, required_capacity: usize) !void {
    var current_capacity = buffer.capacity;
    if (current_capacity == 0) current_capacity = buffer.paths.len;
    if (required_capacity <= current_capacity) {
        buffer.capacity = current_capacity;
        return;
    }
    const allocator = std.heap.page_allocator;
    const next_capacity = try nextTensorAppendCapacity(current_capacity, required_capacity);
    buffer.paths = try allocator.realloc(buffer.paths, next_capacity);
    buffer.capacity = next_capacity;
}

fn ensureTraceRemovalPathStepCapacity(path: *TraceRemovalPath, required_capacity: usize) !void {
    var current_capacity = path.trace_capacity;
    if (current_capacity == 0) current_capacity = path.trace_indices.len;
    if (required_capacity <= current_capacity) {
        path.trace_capacity = current_capacity;
        return;
    }
    const allocator = std.heap.page_allocator;
    const next_capacity = try nextTensorAppendCapacity(current_capacity, required_capacity);
    path.trace_indices = try allocator.realloc(path.trace_indices, next_capacity);
    path.trace_capacity = next_capacity;
}

fn cloneTraceRemovalPath(path: TraceRemovalPath) !TraceRemovalPath {
    var out: TraceRemovalPath = .{};
    errdefer out.deinit();
    try ensureTraceRemovalPathStepCapacity(&out, path.trace_count);
    @memcpy(out.trace_indices[0..path.trace_count], path.trace_indices[0..path.trace_count]);
    out.trace_count = path.trace_count;
    return out;
}

fn ensureYoungPermutationTermCapacity(sum: *YoungPermutationSum, required_capacity: usize) !void {
    var current_capacity = sum.capacity;
    if (current_capacity == 0) current_capacity = sum.terms.len;
    if (required_capacity <= current_capacity) {
        sum.capacity = current_capacity;
        return;
    }
    const allocator = std.heap.page_allocator;
    const next_capacity = try nextTensorAppendCapacity(current_capacity, required_capacity);
    sum.terms = try allocator.realloc(sum.terms, next_capacity);
    sum.capacity = next_capacity;
}

fn ensureBrauerEquationRowCapacity(system: *BrauerEquationSystem, required_row_count: usize) !void {
    var current_capacity = system.row_capacity;
    if (current_capacity == 0) current_capacity = system.keys.len;
    if (required_row_count <= current_capacity) {
        system.row_capacity = current_capacity;
        return;
    }
    const allocator = std.heap.page_allocator;
    const next_capacity = try nextTensorAppendCapacity(current_capacity, required_row_count);
    const stride = @as(usize, system.column_count) + 1;
    const old_entry_len = std.math.mul(usize, current_capacity, stride) catch return error.ProjectorProgramTooLarge;
    const next_entry_len = std.math.mul(usize, next_capacity, stride) catch return error.ProjectorProgramTooLarge;
    system.keys = try allocator.realloc(system.keys, next_capacity);
    system.row_hashes = try allocator.realloc(system.row_hashes, next_capacity);
    const old_next_len = system.row_next.len;
    system.row_next = try allocator.realloc(system.row_next, next_capacity);
    var next_index = old_next_len;
    while (next_index < next_capacity) : (next_index += 1) {
        system.row_next[next_index] = tensor_endpoint_action_empty_bucket;
    }
    system.entries = try allocator.realloc(system.entries, next_entry_len);
    @memset(system.entries[old_entry_len..next_entry_len], Rational.zero());
    system.row_capacity = next_capacity;
}

fn ensureBrauerEquationRowBuckets(system: *BrauerEquationSystem, required_row_count: usize) !void {
    const required_bucket_count = std.math.mul(usize, required_row_count, 2) catch return error.ProjectorProgramTooLarge;
    if (system.bucket_count >= required_bucket_count and system.bucket_count != 0) return;
    const allocator = std.heap.page_allocator;
    var bucket_count = if (system.bucket_count == 0) @as(usize, 8) else system.bucket_count;
    while (bucket_count < required_bucket_count) {
        bucket_count = std.math.mul(usize, bucket_count, 2) catch return error.ProjectorProgramTooLarge;
    }
    const buckets = try allocator.alloc(usize, bucket_count);
    errdefer allocator.free(buckets);
    @memset(buckets, tensor_endpoint_action_empty_bucket);

    var row: usize = 0;
    while (row < system.row_count) : (row += 1) {
        const bucket = system.row_hashes[row] % bucket_count;
        system.row_next[row] = buckets[bucket];
        buckets[bucket] = row;
    }

    allocator.free(system.buckets);
    system.buckets = buckets;
    system.bucket_count = bucket_count;
}

const BrauerEquationKey = struct {
    trace_index: usize = 0,
    word: BrauerWord = .{},
};

const BrauerEquationSystem = struct {
    row_count: usize = 0,
    row_capacity: usize = 0,
    column_count: usize = 0,
    keys: []BrauerEquationKey = &.{},
    row_hashes: []u64 = &.{},
    row_next: []usize = &.{},
    bucket_count: usize = 0,
    buckets: []usize = &.{},
    entries: []Rational = &.{},

    fn deinit(self: *BrauerEquationSystem) void {
        const allocator = std.heap.page_allocator;
        var row: usize = 0;
        while (row < self.row_count) : (row += 1) {
            self.keys[row].word.deinit();
        }
        allocator.free(self.keys);
        allocator.free(self.row_hashes);
        allocator.free(self.row_next);
        allocator.free(self.buckets);
        allocator.free(self.entries);
        self.* = .{};
    }
};

const VectorBrauerPivotSelection = struct {
    count: usize = 0,
    capacity: usize = 0,
    pivots: []usize = &.{},

    fn deinit(self: *VectorBrauerPivotSelection) void {
        const allocator = std.heap.page_allocator;
        allocator.free(self.pivots);
        self.* = .{};
    }

    fn append(self: *VectorBrauerPivotSelection, pivot: usize) !void {
        if (self.capacity < self.count + 1) {
            const allocator = std.heap.page_allocator;
            const capacity = try nextTensorAppendCapacity(self.capacity, self.count + 1);
            self.pivots = try allocator.realloc(self.pivots, capacity);
            self.capacity = capacity;
        }
        self.pivots[self.count] = pivot;
        self.count += 1;
    }
};

/// StructuralProjectorSpec describes a representation-channel projector independently of formula family names.
pub const StructuralProjectorSpec = struct {
    operator_id: u32,
    orthogonal_dimension: u16,
    multiplicity_copy: u16 = 0,
    left: StructuralEndpoint,
    right: StructuralEndpoint,
    output: StructuralEndpoint,
};

/// TensorFormProjectionTransition names the profile-level projector class.
pub const TensorFormProjectionTransition = enum {
    gamma_delta,
    rank_split,
    middle_dual,
    unsupported,
};

/// StructuralProjectorKeySummary describes one structural audit key without operator or index ids.
pub const StructuralProjectorKeySummary = struct {
    dimension: u16 = 0,
    source_form_profile: u128 = 0,
    target_form_profile: u128 = 0,
    source_tower_power: u16 = 0,
    target_tower_power: u16 = 0,
    source_has_spinor: bool = false,
    right_has_spinor: bool = false,
    target_has_spinor: bool = false,
    source_chirality: u8 = 0,
    right_chirality: u8 = 0,
    target_chirality: u8 = 0,
    duality: rendering.DualityTag = .none,
};

const max_structural_audit_keys = 64;
const max_structural_unsupported_groups = 4;

/// StructuralProjectorCoverageAudit counts profile classes and solver coverage.
pub const StructuralProjectorCoverageAudit = struct {
    tensor_spinor_projection_count: u64 = 0,
    tensor_spinor_structural_count: u64 = 0,
    tensor_form_projection_count: u64 = 0,
    tensor_form_structural_count: u64 = 0,
    preserve_count: u64 = 0,
    add_rank_count: u64 = 0,
    shift_all_up_count: u64 = 0,
    move_rank_up_count: u64 = 0,
    split_rank_count: u64 = 0,
    remove_rank_count: u64 = 0,
    unsupported_transform_count: u64 = 0,
    structural_projection_count: u64 = 0,
    structural_projection_solved_count: u64 = 0,
    structural_projection_unsupported_count: u64 = 0,
    distinct_structural_key_count: u64 = 0,
    distinct_structural_solved_key_count: u64 = 0,
    distinct_structural_unsupported_key_count: u64 = 0,
    structural_key_overflow_count: u64 = 0,
    structural_key_hashes: [max_structural_audit_keys]u64 = [_]u64{0} ** max_structural_audit_keys,
    structural_key_solved: [max_structural_audit_keys]bool = [_]bool{false} ** max_structural_audit_keys,
    structural_key_occurrences: [max_structural_audit_keys]u64 = [_]u64{0} ** max_structural_audit_keys,
    largest_unsupported_key_hashes: [max_structural_unsupported_groups]u64 = [_]u64{0} ** max_structural_unsupported_groups,
    largest_unsupported_key_counts: [max_structural_unsupported_groups]u64 = [_]u64{0} ** max_structural_unsupported_groups,
    largest_unsupported_key_summaries: [max_structural_unsupported_groups]StructuralProjectorKeySummary = [_]StructuralProjectorKeySummary{.{}} ** max_structural_unsupported_groups,

    /// recordTensorSpinorProjection classifies one tensor-spinor local channel.
    pub fn recordTensorSpinorProjection(self: *StructuralProjectorCoverageAudit, spec: TensorSpinorProjectionSpec) void {
        self.tensor_spinor_projection_count += 1;
        self.recordProfileTransform(classifyProfileTransform(spec.input_form_profile, spec.form_profile));
        if (self.recordStructuralProjection(structuralProjectorSpecFromTensorSpinor(spec))) {
            self.tensor_spinor_structural_count += 1;
        }
    }

    /// recordTensorSpinorAtom classifies one rendered compact tensor-spinor atom.
    pub fn recordTensorSpinorAtom(self: *StructuralProjectorCoverageAudit, atom: rendering.TensorSpinorProjection) void {
        self.recordTensorSpinorProjection(.{
            .operator_id = atom.operator_id,
            .left = atom.left,
            .right = atom.right,
            .output = atom.output,
            .orthogonal_dimension = atom.orthogonal_dimension,
            .input_form_profile = atom.input_form_profile,
            .input_form_count = atom.input_form_count,
            .form_rank = atom.form_rank,
            .form_count = atom.form_count,
            .form_mask = atom.form_mask,
            .form_profile = atom.form_profile,
            .tower_power = atom.tower_power,
            .chirality = atom.chirality,
            .duality = atom.duality,
        });
    }

    /// recordTensorFormProjection classifies one tensor-form local channel.
    pub fn recordTensorFormProjection(self: *StructuralProjectorCoverageAudit, spec: TensorFormProjectionSpec) void {
        self.tensor_form_projection_count += 1;
        self.recordProfileTransform(classifyProfileTransform(spec.input_form_profile, spec.output_form_profile));
        if (self.recordStructuralProjection(structuralProjectorSpecFromTensorForm(spec))) {
            self.tensor_form_structural_count += 1;
        }
    }

    /// recordTensorFormAtom classifies one rendered compact tensor-form atom.
    pub fn recordTensorFormAtom(self: *StructuralProjectorCoverageAudit, atom: rendering.TensorFormProjection, chirality: u8) void {
        self.recordTensorFormProjection(.{
            .operator_id = atom.operator_id,
            .left = atom.left,
            .right = atom.right,
            .output = atom.output,
            .orthogonal_dimension = atom.orthogonal_dimension,
            .input_form_profile = formProfileFromMask(atom.input_form_mask),
            .input_form_mask = atom.input_form_mask,
            .output_form_profile = atom.output_form_profile,
            .output_form_count = atom.output_form_count,
            .output_form_rank = atom.output_form_rank,
            .output_duality = atom.output_duality,
            .right_chirality = atom.right_chirality,
            .chirality = chirality,
        });
    }

    fn recordProfileTransform(self: *StructuralProjectorCoverageAudit, transform: ProfileTransform) void {
        switch (transform.kind) {
            .preserve => self.preserve_count += 1,
            .add_rank => self.add_rank_count += 1,
            .shift_all_up => self.shift_all_up_count += 1,
            .move_rank_up => self.move_rank_up_count += 1,
            .split_rank => self.split_rank_count += 1,
            .remove_rank => self.remove_rank_count += 1,
            .unsupported => self.unsupported_transform_count += 1,
        }
    }

    fn recordStructuralProjection(self: *StructuralProjectorCoverageAudit, spec: StructuralProjectorSpec) bool {
        self.structural_projection_count += 1;
        const key = structuralProgramKey(spec);
        const key_hash = structuralProgramKeyHash(key);
        var slot_index: usize = 0;
        while (slot_index < max_structural_audit_keys) : (slot_index += 1) {
            if (self.structural_key_hashes[slot_index] != key_hash) continue;
            const solved = self.structural_key_solved[slot_index];
            self.structural_key_occurrences[slot_index] += 1;
            if (!solved) self.recordUnsupportedStructuralKeyGroup(key_hash, self.structural_key_occurrences[slot_index], key);
            self.recordStructuralProjectionStatus(solved);
            return solved;
        }

        const solved = structuralProjectorTermCount(spec) != 0;
        self.recordStructuralProjectionStatus(solved);
        self.distinct_structural_key_count += 1;
        if (solved) {
            self.distinct_structural_solved_key_count += 1;
        } else {
            self.distinct_structural_unsupported_key_count += 1;
        }

        slot_index = 0;
        while (slot_index < max_structural_audit_keys) : (slot_index += 1) {
            if (self.structural_key_hashes[slot_index] != 0) continue;
            self.structural_key_hashes[slot_index] = key_hash;
            self.structural_key_solved[slot_index] = solved;
            self.structural_key_occurrences[slot_index] = 1;
            if (!solved) self.recordUnsupportedStructuralKeyGroup(key_hash, 1, key);
            return solved;
        }
        self.structural_key_overflow_count += 1;
        return solved;
    }

    fn recordStructuralProjectionStatus(self: *StructuralProjectorCoverageAudit, solved: bool) void {
        if (solved) {
            self.structural_projection_solved_count += 1;
        } else {
            self.structural_projection_unsupported_count += 1;
        }
    }

    fn recordUnsupportedStructuralKeyGroup(self: *StructuralProjectorCoverageAudit, key_hash: u64, count: u64, key: StructuralProgramKey) void {
        var group_index: usize = 0;
        while (group_index < max_structural_unsupported_groups) : (group_index += 1) {
            if (self.largest_unsupported_key_hashes[group_index] != key_hash) continue;
            self.largest_unsupported_key_counts[group_index] = count;
            self.sortUnsupportedStructuralKeyGroups();
            return;
        }

        group_index = 0;
        while (group_index < max_structural_unsupported_groups) : (group_index += 1) {
            if (self.largest_unsupported_key_hashes[group_index] != 0) continue;
            self.largest_unsupported_key_hashes[group_index] = key_hash;
            self.largest_unsupported_key_counts[group_index] = count;
            self.largest_unsupported_key_summaries[group_index] = structuralProjectorKeySummary(key);
            self.sortUnsupportedStructuralKeyGroups();
            return;
        }

        if (count <= self.largest_unsupported_key_counts[max_structural_unsupported_groups - 1]) return;
        self.largest_unsupported_key_hashes[max_structural_unsupported_groups - 1] = key_hash;
        self.largest_unsupported_key_counts[max_structural_unsupported_groups - 1] = count;
        self.largest_unsupported_key_summaries[max_structural_unsupported_groups - 1] = structuralProjectorKeySummary(key);
        self.sortUnsupportedStructuralKeyGroups();
    }

    fn sortUnsupportedStructuralKeyGroups(self: *StructuralProjectorCoverageAudit) void {
        var outer: usize = 0;
        while (outer < max_structural_unsupported_groups) : (outer += 1) {
            var inner = outer + 1;
            while (inner < max_structural_unsupported_groups) : (inner += 1) {
                if (self.largest_unsupported_key_counts[inner] <= self.largest_unsupported_key_counts[outer]) continue;
                const hash = self.largest_unsupported_key_hashes[outer];
                const count = self.largest_unsupported_key_counts[outer];
                const summary = self.largest_unsupported_key_summaries[outer];
                self.largest_unsupported_key_hashes[outer] = self.largest_unsupported_key_hashes[inner];
                self.largest_unsupported_key_counts[outer] = self.largest_unsupported_key_counts[inner];
                self.largest_unsupported_key_summaries[outer] = self.largest_unsupported_key_summaries[inner];
                self.largest_unsupported_key_hashes[inner] = hash;
                self.largest_unsupported_key_counts[inner] = count;
                self.largest_unsupported_key_summaries[inner] = summary;
            }
        }
    }
};

const TensorSpinorProjectionTransition = enum {
    spinor_tower_contract,
    unsupported,
};

const ProfileTransformKind = enum {
    preserve,
    add_rank,
    shift_all_up,
    move_rank_up,
    split_rank,
    remove_rank,
    unsupported,
};

const ProfileTransform = struct {
    kind: ProfileTransformKind,
    rank: u8 = 0,
    source_rank: u8 = 0,
    target_rank: u8 = 0,
    lower_rank: u8 = 0,
    upper_rank: u8 = 0,
    carried_profile: u128 = 0,
};

const StructuralSearchState = struct {
    form_profile: u128 = 0,
    tower_power: u16 = 0,
    chirality: u8 = 0,
    has_spinor: bool = false,
};

const StructuralPrimitiveEffectKind = enum {
    spinor_tower_contract,
    spinor_tower_contract_adjoint,
    form_spinor_contract_adjoint,
    gamma_insert,
    gamma_wedge_shift,
    gamma_rank_split,
    hodge_project,
};

const StructuralPrimitiveEffect = struct {
    kind: StructuralPrimitiveEffectKind,
    next: StructuralSearchState = .{},
    signature: PrimitiveSignature = .{},
};

const max_structural_generated_effects = 16;
const max_structural_search_depth = max_program_primitives;

const StructuralPrimitiveEffectBuffer = struct {
    count: u8 = 0,
    slots: [max_structural_generated_effects]StructuralPrimitiveEffect = [_]StructuralPrimitiveEffect{.{ .kind = .spinor_tower_contract }} ** max_structural_generated_effects,

    fn append(self: *StructuralPrimitiveEffectBuffer, effect: StructuralPrimitiveEffect) !void {
        if (self.count == max_structural_generated_effects) return error.ProjectorProgramTooLarge;
        self.slots[self.count] = effect;
        self.count += 1;
    }
};

const max_program_primitives = 6;
const max_program_candidates = 128;
const max_program_pivots = 32;
const max_program_candidate_gram_entries = max_program_candidates * max_program_candidates;
const max_program_gram_entries = max_program_pivots * max_program_pivots;

const ProjectorPrimitiveKind = enum {
    form_delta,
    gamma_insert,
    gamma_action,
    gamma_wedge_shift,
    gamma_trace,
    gamma_rank_split,
    hodge_project,
    spinor_tower_contract,
    spinor_tower_contract_adjoint,
    vector_spinor_identity,
};

const ExteriorGammaAction = struct {
    dimension: u8 = 0,
    input_rank: u8 = 0,
    gamma_rank: u8 = 0,
    contraction_count: u8 = 0,
    output_rank: u8 = 0,
    chirality_parity: u1 = 0,
    duality: rendering.DualityTag = .none,
};

const PrimitiveSignature = struct {
    kind: ProjectorPrimitiveKind = .form_delta,
    input_block: rendering.IndexRef = 0,
    output_block: rendering.IndexRef = 0,
    auxiliary_block: rendering.IndexRef = 0,
    action: ExteriorGammaAction = .{},
    tower_input_power: u8 = 0,
    tower_output_power: u8 = 0,
    tower_form_rank: u8 = 0,
    normalization_tag: u8 = 0,
};

const ProjectorPrimitive = struct {
    kind: ProjectorPrimitiveKind,
    input_block: rendering.IndexBlockId = 0,
    output_block: rendering.IndexBlockId = 0,
    auxiliary_block: rendering.IndexBlockId = 0,
    rank: u8 = 0,
    output_rank: u8 = 0,
    auxiliary_rank: u8 = 0,
    action_gamma_rank: u8 = 0,
    action_contraction_count: u8 = 0,
    orthogonal_dimension: u16 = 0,
    chirality: u8 = 0,
    duality: rendering.DualityTag = .none,
};

const ProjectorCandidateWord = struct {
    count: u8 = 0,
    slots: [max_program_primitives]ProjectorPrimitive = [_]ProjectorPrimitive{.{ .kind = .form_delta }} ** max_program_primitives,

    fn append(self: *ProjectorCandidateWord, slot: ProjectorPrimitive) !void {
        if (self.count == max_program_primitives) return error.ProjectorWordTooLarge;
        self.slots[self.count] = slot;
        self.count += 1;
    }
};

const ProjectorCandidateBuffer = struct {
    count: usize = 0,
    capacity: usize = 0,
    words: []ProjectorCandidateWord = &.{},

    fn deinit(self: *ProjectorCandidateBuffer) void {
        const allocator = std.heap.page_allocator;
        allocator.free(self.words);
        self.* = .{};
    }

    fn append(self: *ProjectorCandidateBuffer, word: ProjectorCandidateWord) !void {
        try ensureProjectorCandidateBufferCapacity(self, self.count + 1);
        self.words[self.count] = word;
        self.count += 1;
    }
};

const ProjectorProgram = struct {
    candidate_count: u8 = 0,
    pivot_count: u8 = 0,
    candidates: [max_program_candidates]ProjectorCandidateWord = [_]ProjectorCandidateWord{.{}} ** max_program_candidates,
    pivots: [max_program_pivots]u8 = [_]u8{0} ** max_program_pivots,
    inverse_gram: [max_program_gram_entries]Rational = [_]Rational{.{ .numerator = 0, .denominator = 1 }} ** max_program_gram_entries,
};

const TensorChannelProgram = struct {
    kind: CachedVectorProgramKind = .projector,
    dimension: u16 = 0,
    rank: u8 = 0,
    candidate_count: usize = 0,
    pivot_count: usize = 0,
    term_count: usize = 0,
    word_capacity: usize = 0,
    pivots: []usize = &.{},
    inverse_gram: []Rational = &.{},
    words: []TensorCandidateWord = &.{},
    vector_program: VectorBrauerProgram = .{},
    vector_spec: VectorSlotProjectorSpec = .{
        .operator_id = 0,
        .dimension = 0,
        .left = 0,
        .right = 0,
        .output = 0,
        .shape = .{},
    },
    structural_spec: StructuralProjectorSpec = .{
        .operator_id = 0,
        .orthogonal_dimension = 0,
        .left = .{ .index = 0 },
        .right = .{ .index = 0 },
        .output = .{ .index = 0 },
    },
    structural_candidates: []ProjectorCandidateWord = &.{},

    fn deinit(self: *TensorChannelProgram) void {
        const allocator = std.heap.page_allocator;
        var word_index: usize = 0;
        const word_count = @min(self.candidate_count, self.words.len);
        while (word_index < word_count) : (word_index += 1) {
            self.words[word_index].deinit();
        }
        allocator.free(self.words);
        allocator.free(self.pivots);
        allocator.free(self.inverse_gram);
        allocator.free(self.structural_candidates);
        self.vector_program.deinit();
        self.* = .{};
    }
};

const CachedVectorProgramEntry = struct {
    key: CachedVectorProgramKey,
    program: TensorChannelProgram,
};

const YoungScalarPairingProjectorEntry = struct {
    key: CachedVectorProgramKey,
    projector: TraceFreeBrauerProjector,
    term_count: usize,
};

const ProjectorCandidateGram = struct {
    context: ?*const anyopaque = null,
    inner_product: *const fn (?*const anyopaque, ProjectorCandidateWord, ProjectorCandidateWord) anyerror!Rational,
};

const ProjectorChannel = union(enum) {
    structural_projection: StructuralProjectorSpec,
    tensor_form_projection: TensorFormProjectionSpec,
    tensor_spinor_projection: TensorSpinorProjectionSpec,
    vector_spinor_traceless: VectorSpinorTracelessSpec,
};

const ProjectorBackend = struct {
    context: ?*const anyopaque = null,
    enumerate_candidates: *const fn (?*const anyopaque, ProjectorChannel, *ProjectorCandidateBuffer) anyerror!void,
    inner_product: *const fn (?*const anyopaque, ProjectorChannel, ProjectorCandidateWord, ProjectorCandidateWord) anyerror!Rational,
};

const ProjectorChannelGramContext = struct {
    channel: ProjectorChannel,
    backend: ProjectorBackend,
};

const ProjectorProgramTerm = struct {
    left_candidate: u8,
    right_candidate: u8,
    coefficient: Rational,
};

const StructuralProjectorProgramCacheEntry = struct {
    key: StructuralProgramKey,
    program: ProjectorProgram,
};

const StructuralTensorProgramCacheEntry = struct {
    key: StructuralProgramKey,
    program: TensorChannelProgram,
};

const TensorOnlyProgramCacheEntry = struct {
    key_hash: u64,
    program: TensorOnlyProgram,
};

/// StructuralProjectorProgramCache reuses exact Gram programs for orthogonal structural projectors.
pub const StructuralProjectorProgramCache = struct {
    allocator: std.mem.Allocator,
    tensor_only_resource_policy: TensorOnlyResourcePolicy = .{},
    entries: std.ArrayList(StructuralProjectorProgramCacheEntry) = .empty,
    index_by_hash: std.AutoHashMap(u64, u32),
    vector_entries: std.ArrayList(CachedVectorProgramEntry) = .empty,
    vector_index_by_hash: std.AutoHashMap(u64, u32),
    young_scalar_pairing_entries: std.ArrayList(YoungScalarPairingProjectorEntry) = .empty,
    young_scalar_pairing_index_by_hash: std.AutoHashMap(u64, u32),
    tensor_entries: std.ArrayList(StructuralTensorProgramCacheEntry) = .empty,
    tensor_index_by_hash: std.AutoHashMap(u64, u32),
    tensor_only_entries: std.ArrayList(TensorOnlyProgramCacheEntry) = .empty,
    tensor_only_index_by_hash: std.AutoHashMap(u64, u32),
    hits: u64 = 0,
    misses: u64 = 0,

    /// init constructs an empty structural projector-program cache.
    pub fn init(allocator: std.mem.Allocator) StructuralProjectorProgramCache {
        return .{
            .allocator = allocator,
            .index_by_hash = std.AutoHashMap(u64, u32).init(allocator),
            .vector_index_by_hash = std.AutoHashMap(u64, u32).init(allocator),
            .young_scalar_pairing_index_by_hash = std.AutoHashMap(u64, u32).init(allocator),
            .tensor_index_by_hash = std.AutoHashMap(u64, u32).init(allocator),
            .tensor_only_index_by_hash = std.AutoHashMap(u64, u32).init(allocator),
        };
    }

    /// initWithTensorOnlyResourcePolicy constructs a cache whose tensor-only programs obey policy.
    pub fn initWithTensorOnlyResourcePolicy(allocator: std.mem.Allocator, policy: TensorOnlyResourcePolicy) StructuralProjectorProgramCache {
        var cache = StructuralProjectorProgramCache.init(allocator);
        cache.tensor_only_resource_policy = policy;
        return cache;
    }

    /// deinit releases cached program storage.
    pub fn deinit(self: *StructuralProjectorProgramCache) void {
        const policy = self.tensor_only_resource_policy;
        for (self.tensor_only_entries.items) |*entry| {
            entry.program.deinit();
        }
        self.tensor_only_index_by_hash.deinit();
        self.tensor_only_entries.deinit(self.allocator);
        for (self.tensor_entries.items) |*entry| {
            entry.program.deinit();
        }
        self.tensor_index_by_hash.deinit();
        self.tensor_entries.deinit(self.allocator);
        for (self.young_scalar_pairing_entries.items) |*entry| {
            entry.projector.deinit();
        }
        self.young_scalar_pairing_index_by_hash.deinit();
        self.young_scalar_pairing_entries.deinit(self.allocator);
        for (self.vector_entries.items) |*entry| {
            entry.program.deinit();
        }
        self.vector_index_by_hash.deinit();
        self.vector_entries.deinit(self.allocator);
        self.index_by_hash.deinit();
        self.entries.deinit(self.allocator);
        self.* = StructuralProjectorProgramCache.initWithTensorOnlyResourcePolicy(self.allocator, policy);
    }

    /// termCount returns the streamed term count for a structural projector.
    pub fn termCount(self: *StructuralProjectorProgramCache, spec: StructuralProjectorSpec) !u16 {
        if (try tensorCompilerChannelFromStructuralOrNull(spec)) |owned_channel| {
            var channel = owned_channel;
            defer channel.deinit();
            if (tensorChannelUsesDirectStructuralProgram(channel)) {
                return projectorProgramTermCount(self.programFor(spec) catch |err| switch (err) {
                    error.UnsupportedStructuralProjectorTerm, error.ProjectorProgramTooLarge => return 0,
                    error.TensorResourceBudgetExceeded => return err,
                    else => return err,
                });
            }
            const count: ?u16 = self.tensorChannelTermCount(channel) catch |err| switch (err) {
                error.UnsupportedTensorBridge => if (tensorChannelStructuralFallbackAllowed(channel)) null else return err,
                else => return err,
            };
            if (count) |value| {
                if (value != 0 or !tensorChannelStructuralFallbackAllowed(channel)) return value;
            }
            if (!tensorChannelStructuralFallbackAllowed(channel)) return 0;
        }
        return projectorProgramTermCount(self.programFor(spec) catch |err| switch (err) {
            error.UnsupportedStructuralProjectorTerm, error.ProjectorProgramTooLarge => return 0,
            error.TensorResourceBudgetExceeded => return err,
            else => return err,
        });
    }

    /// termCountWide returns the streamed term count without truncating tensor-only programs to u16.
    pub fn termCountWide(self: *StructuralProjectorProgramCache, spec: StructuralProjectorSpec) !usize {
        if (try tensorCompilerChannelFromStructuralOrNull(spec)) |owned_channel| {
            var channel = owned_channel;
            defer channel.deinit();
            if (tensorChannelUsesDirectStructuralProgram(channel)) {
                return projectorProgramTermCount(self.programFor(spec) catch |err| switch (err) {
                    error.UnsupportedStructuralProjectorTerm, error.ProjectorProgramTooLarge => return 0,
                    error.TensorResourceBudgetExceeded => return err,
                    else => return err,
                });
            }
            const count: ?usize = self.tensorChannelWideTermCount(channel) catch |err| switch (err) {
                error.UnsupportedTensorBridge => if (tensorChannelStructuralFallbackAllowed(channel)) null else return err,
                else => return err,
            };
            if (count) |value| {
                if (value != 0 or !tensorChannelStructuralFallbackAllowed(channel)) return value;
            }
            if (!tensorChannelStructuralFallbackAllowed(channel)) return 0;
        }
        return projectorProgramTermCount(self.programFor(spec) catch |err| switch (err) {
            error.UnsupportedStructuralProjectorTerm, error.ProjectorProgramTooLarge => return 0,
            error.TensorResourceBudgetExceeded => return err,
            else => return err,
        });
    }

    /// appendTerm emits one cached structural projector program term.
    pub fn appendTerm(self: *StructuralProjectorProgramCache, atoms: *std.ArrayList(rendering.SymbolicAtom), spec: StructuralProjectorSpec, term_index: u16) !rendering.RationalId {
        return self.appendTermAt(atoms, spec, term_index);
    }

    /// appendTermAt emits one cached structural projector term with a wide streamed index.
    pub fn appendTermAt(self: *StructuralProjectorProgramCache, atoms: *std.ArrayList(rendering.SymbolicAtom), spec: StructuralProjectorSpec, term_index: usize) !rendering.RationalId {
        if (try tensorCompilerChannelFromStructuralOrNull(spec)) |owned_channel| {
            var channel = owned_channel;
            defer channel.deinit();
            if (tensorChannelUsesDirectStructuralProgram(channel)) {
                return appendStructuralProjectorProgramTermAt(self.allocator, atoms, spec, try self.programFor(spec), term_index);
            }
            const coefficient: ?rendering.RationalId = self.appendTensorChannelTermAt(atoms, channel, term_index) catch |err| switch (err) {
                error.UnsupportedTensorBridge => if (tensorChannelStructuralFallbackAllowed(channel)) null else return err,
                else => return err,
            };
            if (coefficient) |value| return value;
            if (!tensorChannelStructuralFallbackAllowed(channel)) return error.UnsupportedTensorBridge;
        }
        return appendStructuralProjectorProgramTermAt(self.allocator, atoms, spec, try self.programFor(spec), term_index);
    }

    /// appendTermPage emits a contiguous page of structural terms and records coefficient and atom-end spans.
    pub fn appendTermPage(
        self: *StructuralProjectorProgramCache,
        atoms: *std.ArrayList(rendering.SymbolicAtom),
        coefficients: *std.ArrayList(rendering.RationalId),
        atom_ends: *std.ArrayList(usize),
        spec: StructuralProjectorSpec,
        first_term: usize,
        max_terms: usize,
    ) !usize {
        if (try tensorCompilerChannelFromStructuralOrNull(spec)) |owned_channel| {
            var channel = owned_channel;
            defer channel.deinit();
            if (tensorChannelUsesDirectStructuralProgram(channel)) {
                return appendStructuralProgramTermPage(self.allocator, atoms, coefficients, atom_ends, spec, try self.programFor(spec), first_term, max_terms);
            }
            const emitted: ?usize = self.appendTensorChannelTermPage(atoms, coefficients, atom_ends, channel, first_term, max_terms) catch |err| switch (err) {
                error.UnsupportedTensorBridge => if (tensorChannelStructuralFallbackAllowed(channel)) null else return err,
                else => return err,
            };
            if (emitted) |value| return value;
            if (!tensorChannelStructuralFallbackAllowed(channel)) return error.UnsupportedTensorBridge;
        }
        return appendStructuralProgramTermPage(self.allocator, atoms, coefficients, atom_ends, spec, try self.programFor(spec), first_term, max_terms);
    }

    /// tensorFormTermCount returns the streamed term count for a tensor-form projection.
    pub fn tensorFormTermCount(self: *StructuralProjectorProgramCache, spec: TensorFormProjectionSpec) !u16 {
        return switch (tensorFormProjectionTransition(spec)) {
            .gamma_delta, .rank_split, .middle_dual => self.termCount(structuralProjectorSpecFromTensorForm(spec)) catch |err| switch (err) {
                error.UnsupportedTensorFormProjectionTerm, error.UnsupportedStructuralProjectorTerm, error.ProjectorProgramTooLarge, error.TensorResourceBudgetExceeded => return 0,
                else => return err,
            },
            .unsupported => 0,
        };
    }

    /// appendTensorFormTerm emits one cached tensor-form projection term.
    pub fn appendTensorFormTerm(self: *StructuralProjectorProgramCache, atoms: *std.ArrayList(rendering.SymbolicAtom), spec: TensorFormProjectionSpec, term_index: u16) !rendering.RationalId {
        return switch (tensorFormProjectionTransition(spec)) {
            .gamma_delta, .rank_split, .middle_dual => self.appendTerm(atoms, structuralProjectorSpecFromTensorForm(spec), term_index),
            .unsupported => error.UnsupportedTensorFormProjectionTerm,
        };
    }

    /// appendTensorFormExpression emits a tensor-form projection expression for non-expanded rendering.
    pub fn appendTensorFormExpression(self: *StructuralProjectorProgramCache, atoms: *std.ArrayList(rendering.SymbolicAtom), spec: TensorFormProjectionSpec) !bool {
        if (try self.tensorFormTermCount(spec) == 1) {
            _ = try self.appendTensorFormTerm(atoms, spec, 0);
            return true;
        }
        try appendCompactTensorFormProjection(self.allocator, atoms, spec);
        return false;
    }

    /// tensorSpinorTermCount returns the streamed term count for a tensor-spinor projection.
    pub fn tensorSpinorTermCount(self: *StructuralProjectorProgramCache, spec: TensorSpinorProjectionSpec) !u16 {
        return self.termCount(structuralProjectorSpecFromTensorSpinor(spec)) catch |err| switch (err) {
            error.UnsupportedStructuralProjectorTerm, error.UnsupportedTensorSpinorProjectionTerm, error.ProjectorProgramTooLarge, error.TensorResourceBudgetExceeded => return 0,
            else => return err,
        };
    }

    /// appendTensorSpinorTerm emits one cached tensor-spinor projection term.
    pub fn appendTensorSpinorTerm(self: *StructuralProjectorProgramCache, atoms: *std.ArrayList(rendering.SymbolicAtom), spec: TensorSpinorProjectionSpec, term_index: u16) !rendering.RationalId {
        return self.appendTerm(atoms, structuralProjectorSpecFromTensorSpinor(spec), term_index);
    }

    /// appendTensorSpinorExpression emits a tensor-spinor projection expression for non-expanded rendering.
    pub fn appendTensorSpinorExpression(self: *StructuralProjectorProgramCache, atoms: *std.ArrayList(rendering.SymbolicAtom), spec: TensorSpinorProjectionSpec) !bool {
        if (try self.tensorSpinorTermCount(spec) == 1) {
            _ = try self.appendTensorSpinorTerm(atoms, spec, 0);
            return true;
        }
        try appendCompactTensorSpinorProjection(self.allocator, atoms, spec);
        return false;
    }

    /// entryCount returns the number of compiled structural programs.
    pub fn entryCount(self: StructuralProjectorProgramCache) usize {
        return self.entries.items.len;
    }

    fn programFor(self: *StructuralProjectorProgramCache, spec: StructuralProjectorSpec) !ProjectorProgram {
        if (!structuralProgramKeyFits(spec)) return try compileStructuralProjectorProgram(spec);
        const key = structuralProgramKey(spec);
        const key_hash = structuralProgramKeyHash(key);
        if (self.index_by_hash.get(key_hash)) |entry_index| {
            if (entry_index < self.entries.items.len) {
                const entry = self.entries.items[entry_index];
                if (structuralProgramKeyEql(entry.key, key)) {
                    self.hits += 1;
                    return entry.program;
                }
            }
        }
        for (self.entries.items) |entry| {
            if (structuralProgramKeyEql(entry.key, key)) {
                self.hits += 1;
                return entry.program;
            }
        }
        self.misses += 1;
        const program = try compileStructuralProjectorProgram(spec);
        const entry_index: u32 = @intCast(self.entries.items.len);
        try self.entries.append(self.allocator, .{ .key = key, .program = program });
        if (!self.index_by_hash.contains(key_hash)) try self.index_by_hash.put(key_hash, entry_index);
        return program;
    }

    fn tensorProgramFor(self: *StructuralProjectorProgramCache, kind: CachedVectorProgramKind, spec: VectorSlotProjectorSpec) !?*TensorChannelProgram {
        const key = cachedVectorProgramKey(kind, spec);
        const key_hash = cachedVectorProgramKeyHash(key);
        if (self.vector_index_by_hash.get(key_hash)) |entry_index| {
            if (entry_index < self.vector_entries.items.len) {
                const entry = self.vector_entries.items[entry_index];
                if (cachedVectorProgramKeyEql(entry.key, key)) {
                    self.hits += 1;
                    return &self.vector_entries.items[entry_index].program;
                }
            }
        }
        for (self.vector_entries.items, 0..) |entry, entry_index| {
            if (cachedVectorProgramKeyEql(entry.key, key)) {
                self.hits += 1;
                return &self.vector_entries.items[entry_index].program;
            }
        }
        const program = switch (kind) {
            .projector, .pairing => compileVectorBackedTensorChannelProgram(kind, spec),
            .contraction => compileVectorBackedTensorContractionProgram(tensorContractionSpecFromVectorSpec(spec)),
            .structural => error.UnsupportedTensorBridge,
        } catch |err| switch (err) {
            error.UnsupportedTensorPrimitiveTermCap => return null,
            else => return err,
        };
        self.misses += 1;
        const entry_index: u32 = @intCast(self.vector_entries.items.len);
        try self.vector_entries.append(self.allocator, .{ .key = key, .program = program });
        if (!self.vector_index_by_hash.contains(key_hash)) try self.vector_index_by_hash.put(key_hash, entry_index);
        return &self.vector_entries.items[entry_index].program;
    }

    fn tensorChannelTermCount(self: *StructuralProjectorProgramCache, channel: TensorCompilerChannel) !?u16 {
        if (try tensorChannelLongSymmetricDeltaOrbitTermCount(channel)) |count| {
            try budgetTensorOnlyLongSymmetricDeltaOrbitCursorPolicy(self.tensor_only_resource_policy);
            _ = try tensorOnlyFastCursorCountWithinPolicy(count, self.tensor_only_resource_policy);
            if (count > std.math.maxInt(u16)) return error.UnsupportedTensorPrimitiveTermCap;
            return @intCast(count);
        }
        if (try self.tensorOnlyProgramForBudgetFallback(channel)) |program| return try tensorOnlyProgramPublicTermCount(program);
        if (try tensorChannelTensorOnlyProductFullColumnScalarPairingWideTermCount(channel)) |count| {
            _ = try tensorOnlyFastCursorCountWithinPolicy(count, self.tensor_only_resource_policy);
            if (count > std.math.maxInt(u16)) return error.UnsupportedTensorPrimitiveTermCap;
            return @intCast(count);
        }
        if (try tensorChannelTensorOnlyProductYoungScalarPairingWideTermCount(channel)) |count| {
            _ = try tensorOnlyFastCursorCountWithinPolicy(count, self.tensor_only_resource_policy);
            if (count > std.math.maxInt(u16)) return error.UnsupportedTensorPrimitiveTermCap;
            return @intCast(count);
        }
        if (try tensorChannelTensorOnlyOneSidedVectorProductScalarInvariantWideTermCount(channel)) |count| {
            _ = try tensorOnlyFastCursorCountWithinPolicy(count, self.tensor_only_resource_policy);
            if (count > std.math.maxInt(u16)) return error.UnsupportedTensorPrimitiveTermCap;
            return @intCast(count);
        }
        if (try tensorChannelTensorOnlyYoungScalarPairingWideTermCount(channel)) |count| {
            _ = try tensorOnlyFastCursorCountWithinPolicy(count, self.tensor_only_resource_policy);
            if (count > std.math.maxInt(u16)) return error.UnsupportedTensorPrimitiveTermCap;
            return @intCast(count);
        }
        if (try self.tensorChannelYoungScalarPairingTermCount(channel)) |count| return count;

        return switch (tensorChannelKind(channel) catch |err| switch (err) {
            error.UnsupportedTensorBridge => return null,
        }) {
            .young_output => blk: {
                const vector_spec = vectorSlotProjectorSpecFromChannel(channel).?;
                if (try self.tensorProgramFor(.projector, vector_spec)) |program| {
                    _ = try tensorOnlyFastCursorCountWithinPolicy(program.term_count, self.tensor_only_resource_policy);
                    if (program.term_count > std.math.maxInt(u16)) return error.ProjectorProgramTooLarge;
                    break :blk @as(u16, @intCast(program.term_count));
                }
                const count = vectorSlotProjectorTermCount(vector_spec);
                _ = try tensorOnlyFastCursorCountWithinPolicy(count, self.tensor_only_resource_policy);
                break :blk count;
            },
            .scalar_pairing => blk: {
                const pairing_spec = tensorPairingSpecFromChannel(channel).?;
                const vector_spec = vectorProjectorSpecForPairing(pairing_spec);
                if (try self.tensorProgramFor(.pairing, vector_spec)) |program| {
                    _ = try tensorOnlyFastCursorCountWithinPolicy(program.term_count, self.tensor_only_resource_policy);
                    if (program.term_count > std.math.maxInt(u16)) return error.ProjectorProgramTooLarge;
                    break :blk @as(u16, @intCast(program.term_count));
                }
                const count = tensorPairingTermCount(pairing_spec);
                _ = try tensorOnlyFastCursorCountWithinPolicy(count, self.tensor_only_resource_policy);
                break :blk count;
            },
            .tensor_contraction => blk: {
                const vector_spec = vectorProjectorSpecForContraction(tensorContractionSpecFromChannel(channel).?);
                if (try self.tensorProgramFor(.contraction, vector_spec)) |program| {
                    _ = try tensorOnlyFastCursorCountWithinPolicy(program.term_count, self.tensor_only_resource_policy);
                    if (program.term_count > std.math.maxInt(u16)) return error.ProjectorProgramTooLarge;
                    break :blk @as(u16, @intCast(program.term_count));
                }
                break :blk @as(u16, 0);
            },
            .compressed_form_bridge => return error.UnsupportedTensorBridge,
            .spinor_clifford_bridge => blk: {
                if (try self.structuralTensorProgramFor(channel)) |program| {
                    _ = try tensorOnlyFastCursorCountWithinPolicy(program.term_count, self.tensor_only_resource_policy);
                    if (program.term_count > std.math.maxInt(u16)) return error.ProjectorProgramTooLarge;
                    break :blk @as(u16, @intCast(program.term_count));
                }
                break :blk @as(u16, 0);
            },
        };
    }

    fn tensorChannelWideTermCount(self: *StructuralProjectorProgramCache, channel: TensorCompilerChannel) !?usize {
        if (try tensorChannelLongSymmetricDeltaOrbitTermCount(channel)) |count| {
            try budgetTensorOnlyLongSymmetricDeltaOrbitCursorPolicy(self.tensor_only_resource_policy);
            return try tensorOnlyFastCursorCountWithinPolicy(count, self.tensor_only_resource_policy);
        }
        if (try self.tensorOnlyProgramForBudgetFallback(channel)) |program| return program.term_count;
        if (try tensorChannelTensorOnlyProductFullColumnScalarPairingWideTermCount(channel)) |count| return try tensorOnlyFastCursorCountWithinPolicy(count, self.tensor_only_resource_policy);
        if (try tensorChannelTensorOnlyProductYoungScalarPairingWideTermCount(channel)) |count| return try tensorOnlyFastCursorCountWithinPolicy(count, self.tensor_only_resource_policy);
        if (try tensorChannelTensorOnlyOneSidedVectorProductScalarInvariantWideTermCount(channel)) |count| return try tensorOnlyFastCursorCountWithinPolicy(count, self.tensor_only_resource_policy);
        if (try tensorChannelTensorOnlyYoungScalarPairingWideTermCount(channel)) |count| return try tensorOnlyFastCursorCountWithinPolicy(count, self.tensor_only_resource_policy);
        if (try self.tensorChannelYoungScalarPairingWideTermCount(channel)) |count| return count;
        switch (tensorChannelKind(channel) catch |err| switch (err) {
            error.UnsupportedTensorBridge => return null,
        }) {
            .young_output => {
                const vector_spec = vectorSlotProjectorSpecFromChannel(channel).?;
                if (try self.tensorProgramFor(.projector, vector_spec)) |program| return try tensorOnlyFastCursorCountWithinPolicy(program.term_count, self.tensor_only_resource_policy);
            },
            .scalar_pairing => {
                const pairing_spec = tensorPairingSpecFromChannel(channel).?;
                const vector_spec = vectorProjectorSpecForPairing(pairing_spec);
                if (try self.tensorProgramFor(.pairing, vector_spec)) |program| return try tensorOnlyFastCursorCountWithinPolicy(program.term_count, self.tensor_only_resource_policy);
            },
            .tensor_contraction => {
                const vector_spec = vectorProjectorSpecForContraction(tensorContractionSpecFromChannel(channel).?);
                if (try self.tensorProgramFor(.contraction, vector_spec)) |program| return try tensorOnlyFastCursorCountWithinPolicy(program.term_count, self.tensor_only_resource_policy);
            },
            .compressed_form_bridge => {},
            .spinor_clifford_bridge => {
                if (try self.structuralTensorProgramFor(channel)) |program| return try tensorOnlyFastCursorCountWithinPolicy(program.term_count, self.tensor_only_resource_policy);
            },
        }
        if (try self.tensorChannelTermCount(channel)) |count| return count;
        return null;
    }

    fn tensorOnlyFastCursorCountWithinPolicy(count: usize, resource_policy: TensorOnlyResourcePolicy) !usize {
        if (count > resource_policy.output_term_count_limit) return error.TensorResourceBudgetExceeded;
        return count;
    }

    fn budgetTensorOnlyLongSymmetricDeltaOrbitCursorPolicy(resource_policy: TensorOnlyResourcePolicy) !void {
        if (resource_policy.raw_diagram_count_limit == 0) return error.TensorResourceBudgetExceeded;
    }

    fn appendTensorChannelTerm(self: *StructuralProjectorProgramCache, atoms: *std.ArrayList(rendering.SymbolicAtom), channel: TensorCompilerChannel, term_index: u16) !?rendering.RationalId {
        return self.appendTensorChannelTermAt(atoms, channel, term_index);
    }

    fn appendTensorChannelTermAt(self: *StructuralProjectorProgramCache, atoms: *std.ArrayList(rendering.SymbolicAtom), channel: TensorCompilerChannel, term_index: usize) !?rendering.RationalId {
        if (try self.appendTensorChannelLongSymmetricDeltaOrbitTerm(atoms, channel, term_index, self.tensor_only_resource_policy)) |coefficient| return coefficient;
        if (try self.tensorOnlyProgramForBudgetFallback(channel)) |program| {
            return try appendTensorOnlyProgramTermAt(self.allocator, atoms, program, term_index);
        }
        if (try appendTensorChannelTensorOnlyProductFullColumnScalarPairingTerm(self.allocator, atoms, channel, term_index, self.tensor_only_resource_policy)) |coefficient| return coefficient;
        if (try appendTensorChannelTensorOnlyProductYoungScalarPairingTerm(self.allocator, atoms, channel, term_index, self.tensor_only_resource_policy)) |coefficient| return coefficient;
        if (try appendTensorChannelTensorOnlyOneSidedVectorProductScalarInvariantTerm(self.allocator, atoms, channel, term_index, self.tensor_only_resource_policy)) |coefficient| return coefficient;
        if (try appendTensorChannelTensorOnlyYoungScalarPairingTerm(self.allocator, atoms, channel, term_index, self.tensor_only_resource_policy)) |coefficient| return coefficient;
        if (try self.appendTensorChannelYoungScalarPairingTerm(atoms, channel, term_index)) |coefficient| return coefficient;
        return switch (tensorChannelKind(channel) catch |err| switch (err) {
            error.UnsupportedTensorBridge => return null,
        }) {
            .young_output => blk: {
                const vector_spec = vectorSlotProjectorSpecFromChannel(channel).?;
                if (try self.tensorProgramFor(.projector, vector_spec)) |program| break :blk try appendTensorChannelProgramTerm(self.allocator, atoms, program, term_index);
                if (term_index > std.math.maxInt(u16)) return error.ProjectorConstructorTermOutOfBounds;
                const narrow_term_index: u16 = @intCast(term_index);
                break :blk try appendVectorSlotProjectorTerm(self.allocator, atoms, vector_spec, narrow_term_index);
            },
            .scalar_pairing => blk: {
                const pairing_spec = tensorPairingSpecFromChannel(channel).?;
                const vector_spec = vectorProjectorSpecForPairing(pairing_spec);
                if (try self.tensorProgramFor(.pairing, vector_spec)) |program| break :blk try appendTensorChannelProgramTerm(self.allocator, atoms, program, term_index);
                if (term_index > std.math.maxInt(u16)) return error.ProjectorConstructorTermOutOfBounds;
                const narrow_term_index: u16 = @intCast(term_index);
                break :blk try appendTensorPairingTerm(self.allocator, atoms, pairing_spec, narrow_term_index);
            },
            .tensor_contraction => blk: {
                const vector_spec = vectorProjectorSpecForContraction(tensorContractionSpecFromChannel(channel).?);
                if (try self.tensorProgramFor(.contraction, vector_spec)) |program| break :blk try appendTensorChannelProgramTerm(self.allocator, atoms, program, term_index);
                break :blk null;
            },
            .compressed_form_bridge => return error.UnsupportedTensorBridge,
            .spinor_clifford_bridge => blk: {
                if (try self.structuralTensorProgramFor(channel)) |program| break :blk try appendTensorChannelProgramTerm(self.allocator, atoms, program, term_index);
                break :blk null;
            },
        };
    }

    fn appendTensorChannelTermPage(
        self: *StructuralProjectorProgramCache,
        atoms: *std.ArrayList(rendering.SymbolicAtom),
        coefficients: *std.ArrayList(rendering.RationalId),
        atom_ends: *std.ArrayList(usize),
        channel: TensorCompilerChannel,
        first_term: usize,
        max_terms: usize,
    ) !?usize {
        if (try appendTensorChannelLongSymmetricDeltaOrbitTermPage(self.allocator, atoms, coefficients, atom_ends, channel, first_term, max_terms, self.tensor_only_resource_policy)) |emitted| return emitted;
        if (try self.tensorOnlyProgramForBudgetFallback(channel)) |program| {
            return try appendTensorOnlyProgramTermPage(self.allocator, atoms, coefficients, atom_ends, program, first_term, max_terms);
        }
        if (try appendTensorChannelTensorOnlyProductFullColumnScalarPairingTermPage(self.allocator, atoms, coefficients, atom_ends, channel, first_term, max_terms, self.tensor_only_resource_policy)) |emitted| return emitted;
        if (try appendTensorChannelTensorOnlyProductYoungScalarPairingTermPage(self.allocator, atoms, coefficients, atom_ends, channel, first_term, max_terms, self.tensor_only_resource_policy)) |emitted| return emitted;
        if (try appendTensorChannelTensorOnlyOneSidedVectorProductScalarInvariantTermPage(self.allocator, atoms, coefficients, atom_ends, channel, first_term, max_terms, self.tensor_only_resource_policy)) |emitted| return emitted;
        if (try tensorOnlyYoungScalarPairingChannel(channel)) |owned_tensor_channel| {
            var tensor_channel = owned_tensor_channel;
            defer tensor_channel.deinit();
            return try appendTensorOnlyYoungScalarPairingTermPage(self.allocator, atoms, coefficients, atom_ends, tensor_channel, first_term, max_terms, self.tensor_only_resource_policy);
        }
        if (try appendTensorChannelTensorOnlyYoungScalarPairingTermPage(self.allocator, atoms, coefficients, atom_ends, channel, first_term, max_terms, self.tensor_only_resource_policy)) |emitted| return emitted;
        if (try self.appendTensorChannelYoungScalarPairingTermPage(atoms, coefficients, atom_ends, channel, first_term, max_terms)) |emitted| return emitted;
        const count = (try self.tensorChannelWideTermCount(channel)) orelse return null;
        if (first_term > count) return error.ProjectorConstructorTermOutOfBounds;
        var emitted: usize = 0;
        while (emitted < max_terms and first_term + emitted < count) : (emitted += 1) {
            const coefficient = (try self.appendTensorChannelTermAt(atoms, channel, first_term + emitted)) orelse return error.UnsupportedTensorBridge;
            try coefficients.append(self.allocator, coefficient);
            try atom_ends.append(self.allocator, atoms.items.len);
        }
        return emitted;
    }

    fn tensorChannelYoungScalarPairingTermCount(self: *StructuralProjectorProgramCache, channel: TensorCompilerChannel) !?u16 {
        const count = (try self.tensorChannelYoungScalarPairingWideTermCount(channel)) orelse return null;
        if (count > std.math.maxInt(u16)) return error.UnsupportedTensorPrimitiveTermCap;
        return @intCast(count);
    }

    fn tensorChannelYoungScalarPairingWideTermCount(self: *StructuralProjectorProgramCache, channel: TensorCompilerChannel) !?usize {
        const spec = tensorChannelYoungScalarPairingSpec(channel) orelse return null;
        if (youngRowsAreSingleColumn(spec.shape.row_count, spec.shape.rows)) return try tensorOnlyFastCursorCountWithinPolicy(try factorialU32(spec.shape.box_count), self.tensor_only_resource_policy);
        const entry = try self.youngScalarPairingProjectorFor(spec);
        return try tensorOnlyFastCursorCountWithinPolicy(entry.term_count, self.tensor_only_resource_policy);
    }

    fn appendTensorChannelYoungScalarPairingTerm(
        self: *StructuralProjectorProgramCache,
        atoms: *std.ArrayList(rendering.SymbolicAtom),
        channel: TensorCompilerChannel,
        term_index: usize,
    ) !?rendering.RationalId {
        const spec = tensorChannelYoungScalarPairingSpec(channel) orelse return null;
        if (youngRowsAreSingleColumn(spec.shape.row_count, spec.shape.rows)) return try appendExteriorScalarPairingTerm(self.allocator, atoms, spec, term_index);
        const entry = try self.youngScalarPairingProjectorFor(spec);
        return try appendYoungScalarPairingProjectorTerm(self.allocator, atoms, vectorProjectorSpecForPairing(spec), entry.projector, term_index);
    }

    fn appendTensorChannelYoungScalarPairingTermPage(
        self: *StructuralProjectorProgramCache,
        atoms: *std.ArrayList(rendering.SymbolicAtom),
        coefficients: *std.ArrayList(rendering.RationalId),
        atom_ends: *std.ArrayList(usize),
        channel: TensorCompilerChannel,
        first_term: usize,
        max_terms: usize,
    ) !?usize {
        const spec = tensorChannelYoungScalarPairingSpec(channel) orelse return null;
        if (youngRowsAreSingleColumn(spec.shape.row_count, spec.shape.rows)) {
            const count = try factorialU32(spec.shape.box_count);
            if (first_term > count) return error.ProjectorConstructorTermOutOfBounds;
            return try appendExteriorScalarPairingTermPage(self.allocator, atoms, coefficients, atom_ends, spec, first_term, max_terms);
        }
        const entry = try self.youngScalarPairingProjectorFor(spec);
        if (first_term > entry.term_count) return error.ProjectorConstructorTermOutOfBounds;
        return try appendYoungScalarPairingProjectorTermPage(self.allocator, atoms, coefficients, atom_ends, vectorProjectorSpecForPairing(spec), entry.projector, first_term, max_terms);
    }

    fn youngScalarPairingProjectorFor(self: *StructuralProjectorProgramCache, spec: TensorPairingSpec) !*const YoungScalarPairingProjectorEntry {
        const vector_spec = vectorProjectorSpecForPairing(spec);
        const key = cachedVectorProgramKey(.pairing, vector_spec);
        const key_hash = cachedVectorProgramKeyHash(key);
        if (self.young_scalar_pairing_index_by_hash.get(key_hash)) |entry_index| {
            if (entry_index < self.young_scalar_pairing_entries.items.len) {
                const entry = self.young_scalar_pairing_entries.items[entry_index];
                if (cachedVectorProgramKeyEql(entry.key, key)) {
                    self.hits += 1;
                    return &self.young_scalar_pairing_entries.items[entry_index];
                }
            }
        }
        for (self.young_scalar_pairing_entries.items, 0..) |entry, entry_index| {
            if (cachedVectorProgramKeyEql(entry.key, key)) {
                self.hits += 1;
                return &self.young_scalar_pairing_entries.items[entry_index];
            }
        }

        var entry = YoungScalarPairingProjectorEntry{
            .key = key,
            .projector = try compileYoungScalarPairingProjector(vector_spec),
            .term_count = 0,
        };
        errdefer entry.projector.deinit();
        entry.term_count = try countTraceFreeBrauerProjectorTerms(entry.projector);
        if (entry.term_count == 0) return error.UnsupportedStructuralProjectorTerm;

        self.misses += 1;
        const entry_index: u32 = @intCast(self.young_scalar_pairing_entries.items.len);
        var index_inserted = false;
        if (!self.young_scalar_pairing_index_by_hash.contains(key_hash)) {
            try self.young_scalar_pairing_index_by_hash.put(key_hash, entry_index);
            index_inserted = true;
        }
        errdefer {
            if (index_inserted) _ = self.young_scalar_pairing_index_by_hash.remove(key_hash);
        }
        try self.young_scalar_pairing_entries.append(self.allocator, entry);
        index_inserted = false;
        return &self.young_scalar_pairing_entries.items[entry_index];
    }

    fn tensorChannelLongSymmetricDeltaOrbitTermCount(channel: TensorCompilerChannel) !?usize {
        var tensor_channel = liveTensorOnlyChannelFromCompilerChannel(channel) catch |err| switch (err) {
            error.UnsupportedTensorBridge => return null,
            else => return err,
        };
        defer tensor_channel.deinit();
        if (!tensorOnlyChannelUsesSymmetricDeltaOrbitStream(tensor_channel)) return null;
        const action_word_count = try tensorOnlySymmetricDeltaOrbitProjectedActionWordCount(tensor_channel);
        return std.math.mul(usize, action_word_count, action_word_count) catch return error.TensorResourceBudgetExceeded;
    }

    fn appendTensorChannelLongSymmetricDeltaOrbitTermPage(
        allocator: std.mem.Allocator,
        atoms: *std.ArrayList(rendering.SymbolicAtom),
        coefficients: *std.ArrayList(rendering.RationalId),
        atom_ends: *std.ArrayList(usize),
        channel: TensorCompilerChannel,
        first_term: usize,
        max_terms: usize,
        resource_policy: TensorOnlyResourcePolicy,
    ) !?usize {
        var tensor_channel = liveTensorOnlyChannelFromCompilerChannel(channel) catch |err| switch (err) {
            error.UnsupportedTensorBridge => return null,
            else => return err,
        };
        defer tensor_channel.deinit();
        if (!tensorOnlyChannelUsesSymmetricDeltaOrbitStream(tensor_channel)) return null;
        try budgetTensorOnlyLongSymmetricDeltaOrbitCursorPolicy(resource_policy);
        const action_word_count = try tensorOnlySymmetricDeltaOrbitProjectedActionWordCount(tensor_channel);
        const count = std.math.mul(usize, action_word_count, action_word_count) catch return error.TensorResourceBudgetExceeded;
        if (count > resource_policy.output_term_count_limit) return error.TensorResourceBudgetExceeded;
        if (first_term > count) return error.ProjectorConstructorTermOutOfBounds;
        const page_limit = @min(max_terms, resource_policy.output_term_page_limit);
        if (page_limit > resource_policy.term_pair_work_limit) return error.TensorResourceBudgetExceeded;
        const coefficient = try tensorOnlySymmetricDeltaOrbitNormalization(tensor_channel);
        return try appendTensorOnlySymmetricDeltaOrbitActionPairTermPage(allocator, atoms, coefficients, atom_ends, tensor_channel, coefficient, action_word_count, first_term, page_limit, resource_policy);
    }

    fn appendTensorChannelLongSymmetricDeltaOrbitTerm(
        self: *StructuralProjectorProgramCache,
        atoms: *std.ArrayList(rendering.SymbolicAtom),
        channel: TensorCompilerChannel,
        term_index: usize,
        resource_policy: TensorOnlyResourcePolicy,
    ) !?rendering.RationalId {
        var coefficients: std.ArrayList(rendering.RationalId) = .empty;
        defer coefficients.deinit(self.allocator);
        var atom_ends: std.ArrayList(usize) = .empty;
        defer atom_ends.deinit(self.allocator);
        const emitted = (try appendTensorChannelLongSymmetricDeltaOrbitTermPage(self.allocator, atoms, &coefficients, &atom_ends, channel, term_index, 1, resource_policy)) orelse return null;
        if (emitted != 1) return error.ProjectorConstructorTermOutOfBounds;
        return coefficients.items[0];
    }

    fn prepareLongSymmetricDeltaOrbitProgram(channel: TensorCompilerChannel) !?TensorOnlyProgram {
        var tensor_channel = liveTensorOnlyChannelFromCompilerChannel(channel) catch |err| switch (err) {
            error.UnsupportedTensorBridge => return null,
            else => return err,
        };
        defer tensor_channel.deinit();
        if (!tensorOnlyChannelUsesSymmetricDeltaOrbitStream(tensor_channel)) return null;
        return try prepareTensorOnlyBrauerProgramBeforePivots(tensor_channel, .{});
    }

    fn tensorOnlyProgramFor(self: *StructuralProjectorProgramCache, channel: TensorCompilerChannel) !?*TensorOnlyProgram {
        return self.tensorOnlyProgramForWithPolicy(channel, self.tensor_only_resource_policy);
    }

    fn tensorOnlyProgramForWithPolicy(self: *StructuralProjectorProgramCache, channel: TensorCompilerChannel, compile_policy: TensorOnlyResourcePolicy) !?*TensorOnlyProgram {
        var tensor_channel = liveTensorOnlyChannelFromCompilerChannel(channel) catch |err| switch (err) {
            error.UnsupportedTensorBridge => return null,
            else => return err,
        };
        defer tensor_channel.deinit();
        const key_hash = tensorOnlyProgramCacheKeyHash(tensor_channel);
        if (self.tensor_only_index_by_hash.get(key_hash)) |entry_index| {
            if (entry_index < self.tensor_only_entries.items.len) {
                const entry = self.tensor_only_entries.items[entry_index];
                if (tensorOnlyChannelCacheKeyEql(entry.program.channel, tensor_channel)) {
                    self.hits += 1;
                    return &self.tensor_only_entries.items[entry_index].program;
                }
            }
        }
        for (self.tensor_only_entries.items, 0..) |entry, entry_index| {
            if (entry.key_hash == key_hash and tensorOnlyChannelCacheKeyEql(entry.program.channel, tensor_channel)) {
                self.hits += 1;
                return &self.tensor_only_entries.items[entry_index].program;
            }
        }
        var program = compileGeneralTensorOnlyBrauerProgramWithPolicy(tensor_channel, compile_policy) catch |err| switch (err) {
            error.UnsupportedTensorBridge => return null,
            error.UnsupportedTensorShapeOverCap => if (tensorChannelRequiresTensorOnlySizeError(channel)) return err else return null,
            error.TensorResourceBudgetExceeded => return err,
            error.ProjectorProgramTooLarge => if (tensorChannelRequiresTensorOnlySizeError(channel)) return err else return null,
            else => return err,
        };
        errdefer program.deinit();
        self.misses += 1;
        const entry_index: u32 = @intCast(self.tensor_only_entries.items.len);
        var index_inserted = false;
        if (!self.tensor_only_index_by_hash.contains(key_hash)) {
            try self.tensor_only_index_by_hash.put(key_hash, entry_index);
            index_inserted = true;
        }
        errdefer {
            if (index_inserted) _ = self.tensor_only_index_by_hash.remove(key_hash);
        }
        try self.tensor_only_entries.append(self.allocator, .{ .key_hash = key_hash, .program = program });
        index_inserted = false;
        return &self.tensor_only_entries.items[entry_index].program;
    }

    fn tensorOnlyProgramForBudgetFallback(self: *StructuralProjectorProgramCache, channel: TensorCompilerChannel) !?*TensorOnlyProgram {
        if (tensorCompilerChannelUsesExteriorFormVectorBackend(channel)) return null;
        if (tensorCompilerChannelUsesDirectTensorOnlyScalarCursor(channel)) return null;
        if (tensorChannelYoungScalarPairingSpec(channel) != null) return null;
        const compile_policy = if (tensorChannelRequiresBoundedGenericTensorOnlyProbe(channel))
            tensorOnlyScalarCursorCompileProbePolicy(self.tensor_only_resource_policy)
        else
            self.tensor_only_resource_policy;
        return self.tensorOnlyProgramForWithPolicy(channel, compile_policy) catch |err| switch (err) {
            error.TensorResourceBudgetExceeded => return err,
            else => return err,
        };
    }

    fn structuralTensorProgramFor(self: *StructuralProjectorProgramCache, channel: TensorCompilerChannel) !?*TensorChannelProgram {
        const spec = structuralProjectorSpecFromTensorChannel(channel);
        if (!structuralProgramKeyFits(spec)) return null;
        const key = structuralProgramKey(spec);
        const key_hash = structuralProgramKeyHash(key);
        if (self.tensor_index_by_hash.get(key_hash)) |entry_index| {
            if (entry_index < self.tensor_entries.items.len) {
                const entry = self.tensor_entries.items[entry_index];
                if (structuralProgramKeyEql(entry.key, key)) {
                    self.hits += 1;
                    return &self.tensor_entries.items[entry_index].program;
                }
            }
        }
        for (self.tensor_entries.items, 0..) |entry, entry_index| {
            if (structuralProgramKeyEql(entry.key, key)) {
                self.hits += 1;
                return &self.tensor_entries.items[entry_index].program;
            }
        }
        const program = compileFallbackTensorChannelProgram(channel) catch |err| switch (err) {
            error.UnsupportedStructuralProjectorTerm => return null,
            else => return err,
        };
        self.misses += 1;
        const entry_index: u32 = @intCast(self.tensor_entries.items.len);
        try self.tensor_entries.append(self.allocator, .{ .key = key, .program = program });
        if (!self.tensor_index_by_hash.contains(key_hash)) try self.tensor_index_by_hash.put(key_hash, entry_index);
        return &self.tensor_entries.items[entry_index].program;
    }
};

fn tensorChannelYoungScalarPairingSpec(channel: TensorCompilerChannel) ?TensorPairingSpec {
    if (channel.output.descriptor.kind != .scalar) return null;
    if (!descriptorUsesPureYoungScalarPairingOrbit(channel.left.descriptor)) return null;
    if (!descriptorUsesPureYoungScalarPairingOrbit(channel.right.descriptor)) return null;
    if (channel.left.descriptor.form_duality != .none or channel.right.descriptor.form_duality != .none) return null;
    if (channel.left.descriptor.young_box_count == 0) return null;
    if (channel.left.descriptor.young_box_count != channel.right.descriptor.young_box_count) return null;
    return tensorPairingSpecFromChannel(channel);
}

fn descriptorUsesPureYoungScalarPairingOrbit(descriptor: OrthogonalTensorDescriptor) bool {
    return descriptor.kind == .vector_young or
        descriptor.kind == .exterior_form or
        descriptor.kind == .mixed_tensor_form;
}

fn tensorChannelYoungScalarPairingTermCount(channel: TensorCompilerChannel) !?u16 {
    const spec = tensorChannelYoungScalarPairingSpec(channel) orelse return null;
    return try youngScalarPairingTermCount(spec);
}

fn appendTensorChannelYoungScalarPairingTermPage(
    allocator: std.mem.Allocator,
    atoms: *std.ArrayList(rendering.SymbolicAtom),
    coefficients: *std.ArrayList(rendering.RationalId),
    atom_ends: *std.ArrayList(usize),
    channel: TensorCompilerChannel,
    first_term: usize,
    max_terms: usize,
) !?usize {
    const spec = tensorChannelYoungScalarPairingSpec(channel) orelse return null;
    const count = try youngScalarPairingTermCount(spec);
    if (first_term > count) return error.ProjectorConstructorTermOutOfBounds;
    return try appendYoungScalarPairingTermPage(allocator, atoms, coefficients, atom_ends, spec, first_term, max_terms);
}

fn tensorChannelTensorOnlyYoungScalarPairingWideTermCount(channel: TensorCompilerChannel) !?usize {
    var tensor_channel = (try tensorOnlyYoungScalarPairingChannel(channel)) orelse return null;
    defer tensor_channel.deinit();
    return try tensorOnlyYoungScalarPairingTermCount(tensor_channel);
}

