fn tensorChannelTensorOnlyOneSidedVectorProductScalarInvariantWideTermCount(channel: TensorCompilerChannel) !?usize {
    var tensor_channel = (try tensorOnlyOneSidedVectorProductScalarInvariantChannel(channel)) orelse return null;
    defer tensor_channel.deinit();
    return try tensorOnlyOneSidedVectorProductScalarInvariantTermCount(tensor_channel);
