fn appendTensorChannelTensorOnlyProductFullColumnScalarPairingTerm(
    allocator: std.mem.Allocator,
    atoms: *std.ArrayList(rendering.SymbolicAtom),
    channel: TensorCompilerChannel,
    term_index: usize,
    resource_policy: TensorOnlyResourcePolicy,
