    var coefficients: std.ArrayList(rendering.RationalId) = .empty;
    defer coefficients.deinit(allocator);
    var atom_ends: std.ArrayList(usize) = .empty;
    defer atom_ends.deinit(allocator);
    const emitted = (try appendTensorChannelTensorOnlyProductFullColumnScalarPairingTermPage(allocator, atoms, &coefficients, &atom_ends, channel, term_index, 1, resource_policy)) orelse return null;
    if (emitted != 1) return error.ProjectorConstructorTermOutOfBounds;
