}

fn appendTensorChannelTensorOnlyProductFullColumnScalarPairingTermPage(
    allocator: std.mem.Allocator,
    atoms: *std.ArrayList(rendering.SymbolicAtom),
    coefficients: *std.ArrayList(rendering.RationalId),
    atom_ends: *std.ArrayList(usize),
    channel: TensorCompilerChannel,
    first_term: usize,
    max_terms: usize,
    resource_policy: TensorOnlyResourcePolicy,
) !?usize {
    var tensor_channel = (try tensorOnlyProductFullColumnScalarPairingChannel(channel)) orelse return null;
    defer tensor_channel.deinit();
    return try appendTensorOnlyProductFullColumnScalarPairingTermPage(allocator, atoms, coefficients, atom_ends, tensor_channel, first_term, max_terms, resource_policy);
}

fn tensorOnlyProductFullColumnScalarPairingChannel(channel: TensorCompilerChannel) !?TensorOnlyChannel {
    var tensor_channel = liveTensorOnlyChannelFromCompilerChannel(channel) catch |err| switch (err) {
        error.UnsupportedTensorBridge => return null,
        else => return err,
    };
    errdefer tensor_channel.deinit();
    if (!tensorOnlyChannelUsesProductFullColumnScalarPairingOrbitStream(tensor_channel)) {
        tensor_channel.deinit();
        return null;
    }
    return tensor_channel;
}

fn appendTensorChannelTensorOnlyProductYoungScalarPairingTerm(
    allocator: std.mem.Allocator,
