    defer atom_ends.deinit(allocator);
    const emitted = (try appendTensorChannelTensorOnlyProductYoungScalarPairingTermPage(allocator, atoms, &coefficients, &atom_ends, channel, term_index, 1, resource_policy)) orelse return null;
    if (emitted != 1) return error.ProjectorConstructorTermOutOfBounds;
    return coefficients.items[0];
