fn tensorCompilerChannelUsesDirectTensorOnlyScalarCursor(channel: TensorCompilerChannel) bool {
    var tensor_channel = liveTensorOnlyChannelFromCompilerChannel(channel) catch return false;
    defer tensor_channel.deinit();
    return tensorOnlyChannelUsesDirectTensorOnlyScalarCursor(tensor_channel);
}

fn tensorCompilerChannelUsesExteriorFormVectorBackend(channel: TensorCompilerChannel) bool {
    if (!tensorCompilerChannelHasExteriorFormEndpoint(channel)) return false;
    return switch (tensorChannelKind(channel) catch return false) {
        .young_output, .scalar_pairing, .tensor_contraction => true,
        else => false,
    };
}

fn tensorCompilerChannelHasExteriorFormEndpoint(channel: TensorCompilerChannel) bool {
    return tensorEndpointIsExteriorForm(channel.left) or
        tensorEndpointIsExteriorForm(channel.right) or
        tensorEndpointIsExteriorForm(channel.output);
}

fn tensorEndpointIsExteriorForm(endpoint: ExplicitEndpoint) bool {
    if (tensorDescriptorIsExplicitExteriorForm(endpoint.descriptor)) return true;
    var factor_index: usize = 0;
    while (factor_index < endpoint.factor_count) : (factor_index += 1) {
        if (tensorDescriptorIsExplicitExteriorForm(endpoint.factors[factor_index].descriptor)) return true;
    }
    return false;
}

fn tensorDescriptorIsExplicitExteriorForm(descriptor: OrthogonalTensorDescriptor) bool {
    return descriptor.kind == .exterior_form and
        descriptor.young_box_count > 1 and
        (descriptor.form_profile != 0 or descriptor.form_mask != 0);
}

fn tensorChannelRequiresBoundedGenericTensorOnlyProbe(channel: TensorCompilerChannel) bool {
    if (spinorCliffordBridgeApplies(channel)) return false;
    return tensorEndpointRequiresBoundedGenericTensorOnlyProbe(channel.left) or
        tensorEndpointRequiresBoundedGenericTensorOnlyProbe(channel.right) or
        tensorEndpointRequiresBoundedGenericTensorOnlyProbe(channel.output);
}

fn tensorEndpointRequiresBoundedGenericTensorOnlyProbe(endpoint: ExplicitEndpoint) bool {
    if (endpoint.factor_count != 0) {
        var factor_index: usize = 0;
        while (factor_index < endpoint.factor_count) : (factor_index += 1) {
            if (tensorEndpointFactorRequiresBoundedGenericTensorOnlyProbe(endpoint.factors[factor_index])) return true;
        }
        return false;
    }
    return tensorDescriptorRequiresBoundedGenericTensorOnlyProbe(endpoint.descriptor);
}

fn tensorEndpointFactorRequiresBoundedGenericTensorOnlyProbe(factor: ExplicitEndpointFactor) bool {
    return tensorDescriptorRequiresBoundedGenericTensorOnlyProbe(factor.descriptor);
}

fn tensorDescriptorRequiresBoundedGenericTensorOnlyProbe(descriptor: OrthogonalTensorDescriptor) bool {
    return descriptor.kind == .mixed_tensor_form or descriptor.form_duality != .none;
}

fn tensorOnlyChannelUsesDirectTensorOnlyScalarCursor(tensor_channel: TensorOnlyChannel) bool {
    return tensorOnlyChannelUsesProductFullColumnScalarPairingOrbitStream(tensor_channel) or
        tensorOnlyChannelUsesProductYoungScalarPairingOrbitStream(tensor_channel) or
        tensorOnlyChannelUsesOneSidedVectorProductScalarInvariantStream(tensor_channel) or
        tensorOnlyChannelUsesFullColumnScalarPairingOrbitStream(tensor_channel);
}

fn tensorOnlyChannelCompileProbePolicy(tensor_channel: TensorOnlyChannel, base: TensorOnlyResourcePolicy) TensorOnlyResourcePolicy {
    return if (tensorOnlyChannelUsesDirectTensorOnlyScalarCursor(tensor_channel))
        tensorOnlyScalarCursorCompileProbePolicy(base)
    else
        base;
}

fn tensorOnlyScalarCursorCompileProbePolicy(base: TensorOnlyResourcePolicy) TensorOnlyResourcePolicy {
    return .{
        .raw_diagram_enumeration_limit = @min(base.raw_diagram_enumeration_limit, 64),
        .raw_diagram_count_limit = @min(base.raw_diagram_count_limit, 64),
        .endpoint_action_word_limit = @min(base.endpoint_action_word_limit, 512),
        .candidate_count_limit = @min(base.candidate_count_limit, 64),
        .gram_action_pair_work_limit = @min(base.gram_action_pair_work_limit, 10_000),
        .term_pair_work_limit = @min(base.term_pair_work_limit, 10_000),
        .sparse_pivot_row_term_limit = @min(base.sparse_pivot_row_term_limit, 512),
        .pair_merge_entry_limit = @min(base.pair_merge_entry_limit, 512),
        .output_term_count_limit = @min(base.output_term_count_limit, 1_024),
        .output_term_page_limit = base.output_term_page_limit,
        .coefficient_bit_limit = base.coefficient_bit_limit,
        .trace_generator_count_limit = base.trace_generator_count_limit,
        .trace_closure_basis_limit = base.trace_closure_basis_limit,
    };
}

fn youngScalarPairingTermCount(spec: TensorPairingSpec) !u16 {
    if (youngRowsAreSingleColumn(spec.shape.row_count, spec.shape.rows)) {
        const count = try factorialU32(spec.shape.box_count);
        if (count > std.math.maxInt(u16)) return error.UnsupportedTensorPrimitiveTermCap;
        return @intCast(count);
    }
    var projector = try compileYoungScalarPairingProjector(vectorProjectorSpecForPairing(spec));
    defer projector.deinit();
    const count = try countTraceFreeBrauerProjectorTerms(projector);
    if (count > std.math.maxInt(u16)) return error.UnsupportedTensorPrimitiveTermCap;
    return @intCast(count);
}

fn appendYoungScalarPairingTerm(allocator: std.mem.Allocator, atoms: *std.ArrayList(rendering.SymbolicAtom), spec: TensorPairingSpec, term_index: usize) !rendering.RationalId {
    if (youngRowsAreSingleColumn(spec.shape.row_count, spec.shape.rows)) return appendExteriorScalarPairingTerm(allocator, atoms, spec, term_index);
    var projector = try compileYoungScalarPairingProjector(vectorProjectorSpecForPairing(spec));
    defer projector.deinit();
    return appendYoungScalarPairingProjectorTerm(allocator, atoms, vectorProjectorSpecForPairing(spec), projector, term_index);
}

fn appendYoungScalarPairingTermPage(
    allocator: std.mem.Allocator,
    atoms: *std.ArrayList(rendering.SymbolicAtom),
    coefficients: *std.ArrayList(rendering.RationalId),
    atom_ends: *std.ArrayList(usize),
    spec: TensorPairingSpec,
    first_term: usize,
    max_terms: usize,
) !usize {
    if (max_terms == 0) return 0;
    if (youngRowsAreSingleColumn(spec.shape.row_count, spec.shape.rows)) {
        return try appendExteriorScalarPairingTermPage(allocator, atoms, coefficients, atom_ends, spec, first_term, max_terms);
    }

    const vector_spec = vectorProjectorSpecForPairing(spec);
    var projector = try compileYoungScalarPairingProjector(vector_spec);
    defer projector.deinit();
    return appendYoungScalarPairingProjectorTermPage(allocator, atoms, coefficients, atom_ends, vector_spec, projector, first_term, max_terms);
}

fn compileYoungScalarPairingProjector(vector_spec: VectorSlotProjectorSpec) !TraceFreeBrauerProjector {
    const rank = vectorYoungRank(vector_spec) orelse return error.UnsupportedStructuralProjectorTerm;
    var program = try compileVectorYoungBrauerCore(vector_spec);
    defer program.deinit();
    if (program.candidate_count == 0) return error.UnsupportedStructuralProjectorTerm;
    const shape = try normalizedVectorYoungShape(vector_spec, rank);
    return traceFreeBrauerProjectorBasisForShape(shape, vector_spec.dimension, program.candidates[0]);
}

fn countTraceFreeBrauerProjectorTerms(projector: TraceFreeBrauerProjector) !usize {
    var count: usize = 0;
    var basis_index: usize = 0;
    while (basis_index < projector.basis_count) : (basis_index += 1) {
        const scale = projector.coefficients[basis_index];
        if (scale.numerator == 0) continue;
        const candidate = projector.basis[basis_index];
        var word_index: usize = 0;
        while (word_index < candidate.word_count) : (word_index += 1) {
            const coefficient = try candidate.words[word_index].coefficient.mul(scale);
            if (coefficient.numerator == 0) continue;
            count += 1;
        }
    }
    return count;
}

fn appendYoungScalarPairingProjectorTerm(
    allocator: std.mem.Allocator,
    atoms: *std.ArrayList(rendering.SymbolicAtom),
    vector_spec: VectorSlotProjectorSpec,
    projector: TraceFreeBrauerProjector,
    term_index: usize,
) !rendering.RationalId {
    var coefficients: std.ArrayList(rendering.RationalId) = .empty;
    defer coefficients.deinit(allocator);
    var atom_ends: std.ArrayList(usize) = .empty;
    defer atom_ends.deinit(allocator);
    const emitted = try appendYoungScalarPairingProjectorTermPage(allocator, atoms, &coefficients, &atom_ends, vector_spec, projector, term_index, 1);
    if (emitted != 1) return error.ProjectorConstructorTermOutOfBounds;
    return coefficients.items[0];
}

fn appendYoungScalarPairingProjectorTermPage(
    allocator: std.mem.Allocator,
    atoms: *std.ArrayList(rendering.SymbolicAtom),
    coefficients: *std.ArrayList(rendering.RationalId),
    atom_ends: *std.ArrayList(usize),
    vector_spec: VectorSlotProjectorSpec,
    projector: TraceFreeBrauerProjector,
    first_term: usize,
    max_terms: usize,
) !usize {
    if (max_terms == 0) return 0;
    var seen: usize = 0;
    var emitted: usize = 0;
    var basis_index: usize = 0;
    while (basis_index < projector.basis_count) : (basis_index += 1) {
        const scale = projector.coefficients[basis_index];
        if (scale.numerator == 0) continue;
        const candidate = projector.basis[basis_index];
        var word_index: usize = 0;
        while (word_index < candidate.word_count) : (word_index += 1) {
            const coefficient = try candidate.words[word_index].coefficient.mul(scale);
            if (coefficient.numerator == 0) continue;
            if (seen >= first_term and emitted < max_terms) {
                var term = try vectorBrauerTerm(coefficient);
                defer term.deinit();
                try appendVectorBrauerWordTermAtoms(&term, vector_spec, candidate.words[word_index], false);
                canonicalizeVectorBrauerTerm(&term);
                const rendered_coefficient = try appendTensorPairingBrauerTermAtoms(allocator, atoms, term);
                try coefficients.append(allocator, rendered_coefficient);
                try atom_ends.append(allocator, atoms.items.len);
                emitted += 1;
                if (emitted == max_terms) return emitted;
            }
            seen += 1;
        }
    }
    return emitted;
}

fn appendExteriorScalarPairingTermPage(
    allocator: std.mem.Allocator,
    atoms: *std.ArrayList(rendering.SymbolicAtom),
    coefficients: *std.ArrayList(rendering.RationalId),
    atom_ends: *std.ArrayList(usize),
    spec: TensorPairingSpec,
    first_term: usize,
    max_terms: usize,
) !usize {
    const count = try factorialU32(spec.shape.box_count);
    if (first_term > count) return error.ProjectorConstructorTermOutOfBounds;
    var emitted: usize = 0;
    while (emitted < max_terms and first_term + emitted < count) : (emitted += 1) {
        const coefficient = try appendExteriorScalarPairingTerm(allocator, atoms, spec, first_term + emitted);
        try coefficients.append(allocator, coefficient);
        try atom_ends.append(allocator, atoms.items.len);
    }
    return emitted;
}

fn appendTensorOnlyYoungScalarPairingTermPage(
    allocator: std.mem.Allocator,
    atoms: *std.ArrayList(rendering.SymbolicAtom),
    coefficients: *std.ArrayList(rendering.RationalId),
    atom_ends: *std.ArrayList(usize),
    channel: TensorOnlyChannel,
    first_term: usize,
    max_terms: usize,
    resource_policy: TensorOnlyResourcePolicy,
) !usize {
    if (max_terms == 0) return 0;
    if (!tensorOnlyChannelUsesFullColumnScalarPairingOrbitStream(channel)) return error.UnsupportedStructuralProjectorTerm;
    const count_or_null = factorialUsizeOrNull(channel.left.slot_count);
    if (count_or_null) |count| {
        if (first_term > count) return error.ProjectorConstructorTermOutOfBounds;
    } else if (!try factorialOrdinalInRange(channel.left.slot_count, first_term)) {
        return error.ProjectorConstructorTermOutOfBounds;
    }
    const page_limit = @min(max_terms, resource_policy.output_term_page_limit);
    var emitted: usize = 0;
    while (emitted < page_limit) : (emitted += 1) {
        const term_index = std.math.add(usize, first_term, emitted) catch break;
        if (count_or_null) |count| {
            if (term_index >= count) break;
        } else if (!try factorialOrdinalInRange(channel.left.slot_count, term_index)) {
            break;
        }
        const coefficient = try appendTensorOnlyExteriorScalarPairingTerm(allocator, atoms, channel, term_index, resource_policy);
        try coefficients.append(allocator, coefficient);
        try atom_ends.append(allocator, atoms.items.len);
    }
    return emitted;
}

fn appendTensorOnlyProductFullColumnScalarPairingTermPage(
    allocator: std.mem.Allocator,
    atoms: *std.ArrayList(rendering.SymbolicAtom),
    coefficients: *std.ArrayList(rendering.RationalId),
    atom_ends: *std.ArrayList(usize),
    channel: TensorOnlyChannel,
    first_term: usize,
    max_terms: usize,
    resource_policy: TensorOnlyResourcePolicy,
) !usize {
    if (max_terms == 0) return 0;
    var pairing = (try tensorOnlyProductFullColumnScalarPairingFactorPairing(channel)) orelse return error.UnsupportedStructuralProjectorTerm;
    defer pairing.deinit();
    const count_or_null = try tensorOnlyProductFullColumnScalarPairingTermCountOrNullWithPairing(channel, pairing);
    if (count_or_null) |count| {
        if (first_term > count) return error.ProjectorConstructorTermOutOfBounds;
    } else if (!try tensorOnlyProductFullColumnScalarPairingOrdinalInRange(channel, pairing, first_term)) {
        return error.ProjectorConstructorTermOutOfBounds;
    }
    const page_limit = @min(max_terms, resource_policy.output_term_page_limit);
    var emitted: usize = 0;
    while (emitted < page_limit) : (emitted += 1) {
        const term_index = std.math.add(usize, first_term, emitted) catch break;
        if (count_or_null) |count| {
            if (term_index >= count) break;
        } else if (!try tensorOnlyProductFullColumnScalarPairingOrdinalInRange(channel, pairing, term_index)) {
            break;
        }
        const coefficient = try appendTensorOnlyProductFullColumnScalarPairingTermWithPairing(allocator, atoms, channel, pairing, term_index, resource_policy);
        try coefficients.append(allocator, coefficient);
        try atom_ends.append(allocator, atoms.items.len);
    }
    return emitted;
}

fn appendTensorOnlyProductFullColumnScalarPairingTerm(
    allocator: std.mem.Allocator,
    atoms: *std.ArrayList(rendering.SymbolicAtom),
    channel: TensorOnlyChannel,
    term_index: usize,
    resource_policy: TensorOnlyResourcePolicy,
) !rendering.RationalId {
    var pairing = (try tensorOnlyProductFullColumnScalarPairingFactorPairing(channel)) orelse return error.UnsupportedStructuralProjectorTerm;
    defer pairing.deinit();
    return try appendTensorOnlyProductFullColumnScalarPairingTermWithPairing(allocator, atoms, channel, pairing, term_index, resource_policy);
}

fn appendTensorOnlyProductYoungScalarPairingTermPage(
    allocator: std.mem.Allocator,
    atoms: *std.ArrayList(rendering.SymbolicAtom),
    coefficients: *std.ArrayList(rendering.RationalId),
    atom_ends: *std.ArrayList(usize),
    channel: TensorOnlyChannel,
    first_term: usize,
    max_terms: usize,
    resource_policy: TensorOnlyResourcePolicy,
) !usize {
    if (max_terms == 0) return 0;
    var pairing = (try tensorOnlyProductYoungScalarPairingFactorPairing(channel)) orelse return error.UnsupportedStructuralProjectorTerm;
    defer pairing.deinit();
    const count = try tensorOnlyProductYoungScalarPairingTermCountWithPairing(channel, pairing);
    if (count > resource_policy.output_term_count_limit) return error.TensorResourceBudgetExceeded;
    if (first_term > count) return error.ProjectorConstructorTermOutOfBounds;
    const page_limit = @min(max_terms, resource_policy.output_term_page_limit);
    var emitted: usize = 0;
    while (emitted < page_limit and first_term + emitted < count) : (emitted += 1) {
        const coefficient = try appendTensorOnlyProductYoungScalarPairingTermWithPairing(allocator, atoms, channel, pairing, first_term + emitted);
        try coefficients.append(allocator, coefficient);
        try atom_ends.append(allocator, atoms.items.len);
    }
    return emitted;
}

fn appendTensorOnlyProductYoungScalarPairingTermWithPairing(
    allocator: std.mem.Allocator,
    atoms: *std.ArrayList(rendering.SymbolicAtom),
    channel: TensorOnlyChannel,
    pairing: TensorOnlyProductFactorPairing,
    term_index: usize,
) !rendering.RationalId {
    const count = try tensorOnlyProductYoungScalarPairingTermCountWithPairing(channel, pairing);
    if (term_index >= count) return error.ProjectorConstructorTermOutOfBounds;
    var coefficient = rendering.rationalOne();
    var rest = term_index;
    var factor_index: usize = 0;
    while (factor_index < channel.left.factor_count) : (factor_index += 1) {
        const spec = try tensorOnlyProductYoungScalarPairingFactorSpec(channel, pairing, factor_index);
        const factor_term_count = try youngScalarPairingTermCount(spec);
        const local_term = rest % factor_term_count;
        rest /= factor_term_count;
        const local_coefficient = try appendYoungScalarPairingTerm(allocator, atoms, spec, local_term);
        coefficient = try multiplyRenderingRationals(coefficient, local_coefficient);
    }
    return coefficient;
}

fn tensorOnlyChannelUsesOneSidedVectorProductScalarInvariantStream(channel: TensorOnlyChannel) bool {
    if (channel.output.slot_count != 0) return false;
    const endpoint = tensorOnlyOneSidedVectorProductScalarInvariantEndpoint(channel) orelse return false;
    if (endpoint.slot_count == 0 or (endpoint.slot_count & 1) != 0) return false;
    if (channel.input_slot_count != endpoint.slot_count) return false;
    return tensorOnlyEndpointIsVectorFactorProduct(endpoint);
}

fn tensorOnlyOneSidedVectorProductScalarInvariantEndpoint(channel: TensorOnlyChannel) ?TensorOnlyEndpoint {
    if (channel.left.slot_count != 0 and channel.right.slot_count == 0) return channel.left;
    if (channel.right.slot_count != 0 and channel.left.slot_count == 0) return channel.right;
    return null;
}

fn tensorOnlyEndpointIsVectorFactorProduct(endpoint: TensorOnlyEndpoint) bool {
    if (endpoint.kind != .product or endpoint.factor_count == 0) return false;
    var factor_index: usize = 0;
    while (factor_index < endpoint.factor_count) : (factor_index += 1) {
        if (!tensorOnlyEndpointFactorIsVectorSlot(endpoint.factors[factor_index])) return false;
    }
    return endpoint.factor_count == endpoint.slot_count;
}

fn tensorOnlyEndpointFactorIsVectorSlot(factor: TensorOnlyEndpointFactor) bool {
    if (factor.slot_count != 1 or factor.duality != .none) return false;
    if (factor.kind != .vector_young and factor.kind != .exterior_form) return false;
    const rows = tensorOnlyEndpointFactorWideRows(factor);
    return factor.row_count == 1 and rows.len == 1 and rows[0] == 1;
}

fn tensorOnlyOneSidedVectorProductScalarInvariantTermCount(channel: TensorOnlyChannel) !usize {
    if (!tensorOnlyChannelUsesOneSidedVectorProductScalarInvariantStream(channel)) return error.UnsupportedStructuralProjectorTerm;
    const endpoint = tensorOnlyOneSidedVectorProductScalarInvariantEndpoint(channel).?;
    return try oddDoubleFactorialUsize(endpoint.slot_count);
}

fn appendTensorOnlyOneSidedVectorProductScalarInvariantTermPage(
    allocator: std.mem.Allocator,
    atoms: *std.ArrayList(rendering.SymbolicAtom),
    coefficients: *std.ArrayList(rendering.RationalId),
    atom_ends: *std.ArrayList(usize),
    channel: TensorOnlyChannel,
    first_term: usize,
    max_terms: usize,
    resource_policy: TensorOnlyResourcePolicy,
) !usize {
    if (max_terms == 0) return 0;
    const count = try tensorOnlyOneSidedVectorProductScalarInvariantTermCount(channel);
    if (first_term > count) return error.ProjectorConstructorTermOutOfBounds;
    const page_limit = @min(max_terms, resource_policy.output_term_page_limit);
    const endpoint = tensorOnlyOneSidedVectorProductScalarInvariantEndpoint(channel) orelse return error.UnsupportedStructuralProjectorTerm;
    if (endpoint.layout.slots.len < endpoint.slot_count) return error.ProjectorConstructorTermOutOfBounds;
    const used = try allocator.alloc(bool, endpoint.slot_count);
    defer allocator.free(used);
    const pair_count = endpoint.slot_count / 2;
    const pairs = try allocator.alloc([2]usize, pair_count);
    defer allocator.free(pairs);
    var emitted: usize = 0;
    while (emitted < page_limit and first_term + emitted < count) : (emitted += 1) {
        const coefficient = try appendTensorOnlyOneSidedVectorProductScalarInvariantTermWithBuffers(allocator, atoms, endpoint, first_term + emitted, used, pairs);
        try coefficients.append(allocator, coefficient);
        try atom_ends.append(allocator, atoms.items.len);
    }
    return emitted;
}

fn appendTensorOnlyOneSidedVectorProductScalarInvariantTerm(
    allocator: std.mem.Allocator,
    atoms: *std.ArrayList(rendering.SymbolicAtom),
    channel: TensorOnlyChannel,
    term_index: usize,
) !rendering.RationalId {
    const endpoint = tensorOnlyOneSidedVectorProductScalarInvariantEndpoint(channel) orelse return error.UnsupportedStructuralProjectorTerm;
    const count = try tensorOnlyOneSidedVectorProductScalarInvariantTermCount(channel);
    if (term_index >= count) return error.ProjectorConstructorTermOutOfBounds;
    if (endpoint.layout.slots.len < endpoint.slot_count) return error.ProjectorConstructorTermOutOfBounds;

    const used = try allocator.alloc(bool, endpoint.slot_count);
    defer allocator.free(used);
    const pair_count = endpoint.slot_count / 2;
    const pairs = try allocator.alloc([2]usize, pair_count);
    defer allocator.free(pairs);
    return try appendTensorOnlyOneSidedVectorProductScalarInvariantTermWithBuffers(allocator, atoms, endpoint, term_index, used, pairs);
}

fn appendTensorOnlyOneSidedVectorProductScalarInvariantTermWithBuffers(
    allocator: std.mem.Allocator,
    atoms: *std.ArrayList(rendering.SymbolicAtom),
    endpoint: TensorOnlyEndpoint,
    term_index: usize,
    used: []bool,
    pairs: [][2]usize,
) !rendering.RationalId {
    if (endpoint.layout.slots.len < endpoint.slot_count or used.len < endpoint.slot_count or pairs.len < endpoint.slot_count / 2) return error.ProjectorConstructorTermOutOfBounds;
    @memset(used[0..endpoint.slot_count], false);
    var written_pairs: usize = 0;
    var ordinal = term_index;
    try fillOneSidedVectorProductPairingAt(endpoint.slot_count, used[0..endpoint.slot_count], 0, &ordinal, pairs[0 .. endpoint.slot_count / 2], &written_pairs);
    if (written_pairs != endpoint.slot_count / 2) return error.ProjectorConstructorTermOutOfBounds;

    var pair_index: usize = 0;
    while (pair_index < endpoint.slot_count / 2) : (pair_index += 1) {
        const left = endpoint.layout.slots[pairs[pair_index][0]];
        const right = endpoint.layout.slots[pairs[pair_index][1]];
        try atoms.append(allocator, .{ .vector_slot_metric = .{
            .left = left.block,
            .left_slot = left.slot,
            .right = right.block,
            .right_slot = right.slot,
        } });
    }
    return rendering.rationalOne();
}

fn fillOneSidedVectorProductPairingAt(
    slot_count: usize,
    used: []bool,
    used_count: usize,
    ordinal: *usize,
    pairs: [][2]usize,
    written_pairs: *usize,
) !void {
    if (used_count == slot_count) return;
    const first = firstUnusedTensorBoundarySlotDynamic(used) orelse return;
    const remaining_after_pair = slot_count - used_count - 2;
    const branch_count = try oddDoubleFactorialUsize(remaining_after_pair);
    var second = first + 1;
    while (second < slot_count) : (second += 1) {
        if (used[second]) continue;
        if (ordinal.* >= branch_count) {
            ordinal.* -= branch_count;
            continue;
        }
        used[first] = true;
        used[second] = true;
        if (written_pairs.* >= pairs.len) return error.ProjectorConstructorTermOutOfBounds;
        pairs[written_pairs.*] = .{ first, second };
        written_pairs.* += 1;
        try fillOneSidedVectorProductPairingAt(slot_count, used, used_count + 2, ordinal, pairs, written_pairs);
        return;
    }
    return error.ProjectorConstructorTermOutOfBounds;
}

fn multiplyRenderingRationals(left: rendering.RationalId, right: rendering.RationalId) !rendering.RationalId {
    if (left.numerator == 0 or right.numerator == 0) return rendering.rationalFromWide(0, 1);
    var left_numerator = left.numerator;
    var right_numerator = right.numerator;
    var left_denominator = left.denominator;
    var right_denominator = right.denominator;
    const first_common = gcdU128(absI128(left_numerator), right_denominator);
    if (first_common != 1) {
        left_numerator = @divExact(left_numerator, @as(i128, @intCast(first_common)));
        right_denominator = @divExact(right_denominator, first_common);
    }
    const second_common = gcdU128(absI128(right_numerator), left_denominator);
    if (second_common != 1) {
        right_numerator = @divExact(right_numerator, @as(i128, @intCast(second_common)));
        left_denominator = @divExact(left_denominator, second_common);
    }
    const numerator = std.math.mul(i128, left_numerator, right_numerator) catch return error.TensorResourceBudgetExceeded;
    if (right_denominator != 0 and left_denominator > std.math.maxInt(u128) / right_denominator) return error.TensorResourceBudgetExceeded;
    return rendering.rationalFromWide(numerator, left_denominator * right_denominator);
}

fn appendTensorOnlyProductFullColumnScalarPairingTermWithPairing(
    allocator: std.mem.Allocator,
    atoms: *std.ArrayList(rendering.SymbolicAtom),
    channel: TensorOnlyChannel,
    pairing: TensorOnlyProductFactorPairing,
    term_index: usize,
    resource_policy: TensorOnlyResourcePolicy,
) !rendering.RationalId {
    if (!try tensorOnlyProductFullColumnScalarPairingOrdinalInRange(channel, pairing, term_index)) return error.ProjectorConstructorTermOutOfBounds;
    var denominator: u128 = 1;
    var sign: i128 = 1;
    var rest = term_index;
    var factor_index: usize = 0;
    while (factor_index < channel.left.factor_count) : (factor_index += 1) {
        const left_factor = channel.left.factors[factor_index];
        const right_factor = channel.right.factors[pairing.right_indices[factor_index]];
        const factor_term_count = factorialUsizeOrNull(left_factor.slot_count);
        const local_term = if (factor_term_count) |count| rest % count else rest;
        rest = if (factor_term_count) |count| rest / count else 0;
        const permutation = try exteriorScalarPairingPermutationAtWide(allocator, left_factor.slot_count, local_term);
        defer allocator.free(permutation);
        if (youngPermutationOdd(permutation, left_factor.slot_count)) sign = -sign;
        var slot: usize = 0;
        while (slot < left_factor.slot_count) : (slot += 1) {
            const left = left_factor.layout.slots[slot];
            const right = right_factor.layout.slots[permutation[slot]];
            try atoms.append(allocator, .{ .vector_slot_metric = .{
                .left = left.block,
                .left_slot = left.slot,
                .right = right.block,
                .right_slot = right.slot,
            } });
        }
        const factor_denominator = try factorialU128ForResourceCount(left_factor.slot_count);
        if (factor_denominator > std.math.maxInt(u128) / denominator) return error.TensorResourceBudgetExceeded;
        denominator *= factor_denominator;
        if (bitLengthU128(denominator) > resource_policy.coefficient_bit_limit) return error.TensorResourceBudgetExceeded;
    }
    return rendering.rationalFromWide(sign, denominator);
}

fn appendTensorOnlyExteriorScalarPairingTerm(
    allocator: std.mem.Allocator,
    atoms: *std.ArrayList(rendering.SymbolicAtom),
    channel: TensorOnlyChannel,
    term_index: usize,
    resource_policy: TensorOnlyResourcePolicy,
) !rendering.RationalId {
    const rank = channel.left.slot_count;
    if (!try factorialOrdinalInRange(rank, term_index)) return error.ProjectorConstructorTermOutOfBounds;
    var coefficient = try tensorOnlyFactorialDenominatorRenderingCoefficient(rank, resource_policy);
    const permutation = try exteriorScalarPairingPermutationAtWide(allocator, rank, term_index);
    defer allocator.free(permutation);
    var slot: usize = 0;
    while (slot < rank) : (slot += 1) {
        const left = channel.left.layout.slots[slot];
        const right = channel.right.layout.slots[permutation[slot]];
        try atoms.append(allocator, .{ .vector_slot_metric = .{
            .left = left.block,
            .left_slot = left.slot,
            .right = right.block,
            .right_slot = right.slot,
        } });
    }
    if (youngPermutationOdd(permutation, rank)) coefficient.numerator = -coefficient.numerator;
    return coefficient;
}

fn appendExteriorScalarPairingTerm(allocator: std.mem.Allocator, atoms: *std.ArrayList(rendering.SymbolicAtom), spec: TensorPairingSpec, term_index: usize) !rendering.RationalId {
    const rank = spec.shape.box_count;
    const count = try factorialU32(rank);
    if (term_index >= count) return error.ProjectorConstructorTermOutOfBounds;
    const permutation = try exteriorScalarPairingPermutationAt(allocator, rank, term_index);
    defer allocator.free(permutation);
    var slot: u8 = 0;
    while (slot < rank) : (slot += 1) {
        try atoms.append(allocator, .{ .vector_slot_metric = .{
            .left = spec.left,
            .left_slot = slot,
            .right = spec.right,
            .right_slot = permutation[slot],
        } });
    }
    const sign: i64 = if (youngPermutationOdd(permutation[0..rank], rank)) -1 else 1;
    return rationalToRenderingId(try Rational.init(sign, @intCast(count)));
}

fn exteriorScalarPairingPermutationAt(allocator: std.mem.Allocator, rank: u8, term_index: usize) ![]u8 {
    const count = try factorialU32(rank);
    if (term_index >= count) return error.ProjectorConstructorTermOutOfBounds;
    const available = try allocator.alloc(u8, rank);
    defer allocator.free(available);
    var slot: u8 = 0;
    while (slot < rank) : (slot += 1) available[slot] = slot;

    const permutation = try allocator.alloc(u8, rank);
    errdefer allocator.free(permutation);
    var remaining: u8 = rank;
    var rest = term_index;
    var position: u8 = 0;
    while (position < rank) : (position += 1) {
        const stride = try factorialU32(remaining - 1);
        const available_index: u8 = @intCast(rest / stride);
        rest %= stride;
        permutation[position] = available[available_index];
        var shift = available_index;
        while (shift + 1 < remaining) : (shift += 1) {
            available[shift] = available[shift + 1];
        }
        remaining -= 1;
    }
    return permutation;
}

fn exteriorScalarPairingPermutationAtWide(allocator: std.mem.Allocator, rank: usize, term_index: usize) ![]usize {
    if (!try factorialOrdinalInRange(rank, term_index)) return error.ProjectorConstructorTermOutOfBounds;
    const available = try allocator.alloc(usize, rank);
    defer allocator.free(available);
    var slot: usize = 0;
    while (slot < rank) : (slot += 1) available[slot] = slot;

    const permutation = try allocator.alloc(usize, rank);
    errdefer allocator.free(permutation);
    var remaining = rank;
    var rest = term_index;
    var position: usize = 0;
    while (position < rank) : (position += 1) {
        const stride = factorialUsizeOrNull(remaining - 1);
        const available_index = if (stride) |value| rest / value else 0;
        if (available_index >= remaining) return error.ProjectorConstructorTermOutOfBounds;
        if (stride) |value| rest %= value;
        permutation[position] = available[available_index];
        var shift = available_index;
        while (shift + 1 < remaining) : (shift += 1) {
            available[shift] = available[shift + 1];
        }
        remaining -= 1;
    }
    return permutation;
}

fn factorialOrdinalInRange(rank: usize, ordinal: usize) !bool {
    var count: usize = 1;
    if (ordinal < count) return true;
    var factor: usize = 2;
    while (factor <= rank) : (factor += 1) {
        if (count > ordinal / factor) return true;
        count = std.math.mul(usize, count, factor) catch return true;
    }
    return ordinal < count;
}

fn factorialUsizeOrNull(value: usize) ?usize {
    var out: usize = 1;
    var factor: usize = 2;
    while (factor <= value) : (factor += 1) {
        out = std.math.mul(usize, out, factor) catch return null;
    }
    return out;
}

const Rational = struct {
    numerator: i64,
    denominator: i64,

    fn init(numerator: i64, denominator: i64) !Rational {
        if (denominator == 0) return error.InvalidGramDenominator;
        var out = Rational{ .numerator = numerator, .denominator = denominator };
        out.normalize();
        return out;
    }

    fn zero() Rational {
        return .{ .numerator = 0, .denominator = 1 };
    }

    fn one() Rational {
        return .{ .numerator = 1, .denominator = 1 };
    }

    fn add(self: Rational, other: Rational) !Rational {
        if (self.numerator == 0) return other;
        if (other.numerator == 0) return self;
        const common: i64 = @intCast(gcdU64(absI64(self.denominator), absI64(other.denominator)));
        const left_scale = @divExact(other.denominator, common);
        const right_scale = @divExact(self.denominator, common);
        return Rational.init(try checkedAddI64(
            try checkedMulI64(self.numerator, left_scale),
            try checkedMulI64(other.numerator, right_scale),
        ), try checkedMulI64(self.denominator, left_scale));
    }

    fn sub(self: Rational, other: Rational) !Rational {
        return self.add(.{ .numerator = try checkedNegI64(other.numerator), .denominator = other.denominator });
    }

    fn mul(self: Rational, other: Rational) !Rational {
        if (self.numerator == 0 or other.numerator == 0) return Rational.zero();
        var left_numerator = self.numerator;
        var left_denominator = self.denominator;
        var right_numerator = other.numerator;
        var right_denominator = other.denominator;

        const first_common: i64 = @intCast(gcdU64(absI64(left_numerator), absI64(right_denominator)));
        left_numerator = @divExact(left_numerator, first_common);
        right_denominator = @divExact(right_denominator, first_common);

        const second_common: i64 = @intCast(gcdU64(absI64(right_numerator), absI64(left_denominator)));
        right_numerator = @divExact(right_numerator, second_common);
        left_denominator = @divExact(left_denominator, second_common);

        return Rational.init(try checkedMulI64(left_numerator, right_numerator), try checkedMulI64(left_denominator, right_denominator));
    }

    fn div(self: Rational, other: Rational) !Rational {
        if (other.numerator == 0) return error.SingularGramMatrix;
        return self.mul(.{ .numerator = other.denominator, .denominator = other.numerator });
    }

    fn normalize(self: *Rational) void {
        if (self.numerator == 0) {
            self.denominator = 1;
            return;
        }
        if (self.denominator < 0) {
            self.numerator = -self.numerator;
            self.denominator = -self.denominator;
        }
        const divisor: i64 = @intCast(gcdU64(absI64(self.numerator), absI64(self.denominator)));
        self.numerator = @divExact(self.numerator, divisor);
        self.denominator = @divExact(self.denominator, divisor);
    }
};

const WideRational = struct {
    numerator: i128,
    denominator: i128,

    fn init(numerator: i128, denominator: i128) !WideRational {
        if (denominator == 0) return error.InvalidGramDenominator;
        var out = WideRational{ .numerator = numerator, .denominator = denominator };
        out.normalize();
        return out;
    }

    fn zero() WideRational {
        return .{ .numerator = 0, .denominator = 1 };
    }

    fn one() WideRational {
        return .{ .numerator = 1, .denominator = 1 };
    }

    fn fromRational(value: Rational) WideRational {
        return .{ .numerator = value.numerator, .denominator = value.denominator };
    }

    fn toRational(self: WideRational) !Rational {
        if (self.numerator < std.math.minInt(i64) or self.numerator > std.math.maxInt(i64)) return error.GramIntegerOverflow;
        if (self.denominator <= 0 or self.denominator > std.math.maxInt(i64)) return error.GramIntegerOverflow;
        return Rational.init(@intCast(self.numerator), @intCast(self.denominator));
    }

    fn add(self: WideRational, other: WideRational) !WideRational {
        if (self.numerator == 0) return other;
        if (other.numerator == 0) return self;
        const common: i128 = @intCast(gcdU128(absI128(self.denominator), absI128(other.denominator)));
        const left_scale = @divExact(other.denominator, common);
        const right_scale = @divExact(self.denominator, common);
        return WideRational.init(try checkedAddI128(
            try checkedMulI128(self.numerator, left_scale),
            try checkedMulI128(other.numerator, right_scale),
        ), try checkedMulI128(self.denominator, left_scale));
    }

    fn sub(self: WideRational, other: WideRational) !WideRational {
        return self.add(.{ .numerator = try checkedNegI128(other.numerator), .denominator = other.denominator });
    }

    fn mul(self: WideRational, other: WideRational) !WideRational {
        if (self.numerator == 0 or other.numerator == 0) return WideRational.zero();
        var left_numerator = self.numerator;
        var left_denominator = self.denominator;
        var right_numerator = other.numerator;
        var right_denominator = other.denominator;

        const first_common: i128 = @intCast(gcdU128(absI128(left_numerator), absI128(right_denominator)));
        left_numerator = @divExact(left_numerator, first_common);
        right_denominator = @divExact(right_denominator, first_common);

        const second_common: i128 = @intCast(gcdU128(absI128(right_numerator), absI128(left_denominator)));
        right_numerator = @divExact(right_numerator, second_common);
        left_denominator = @divExact(left_denominator, second_common);

        return WideRational.init(try checkedMulI128(left_numerator, right_numerator), try checkedMulI128(left_denominator, right_denominator));
    }

    fn div(self: WideRational, other: WideRational) !WideRational {
        if (other.numerator == 0) return error.SingularGramMatrix;
        return self.mul(.{ .numerator = other.denominator, .denominator = other.numerator });
    }

    fn normalize(self: *WideRational) void {
        if (self.numerator == 0) {
            self.denominator = 1;
            return;
        }
        if (self.denominator < 0) {
            self.numerator = -self.numerator;
            self.denominator = -self.denominator;
        }
        const divisor: i128 = @intCast(gcdU128(absI128(self.numerator), absI128(self.denominator)));
        self.numerator = @divExact(self.numerator, divisor);
        self.denominator = @divExact(self.denominator, divisor);
    }
};

const ContractionAccumulator = struct {
    coefficient: Rational = .{ .numerator = 1, .denominator = 1 },
    remaining_form_profile: u128 = 0,
    remaining_tower_power: u8 = 0,
    chirality: u8 = 0,
    duality: rendering.DualityTag = .none,
    is_zero: bool = false,
};

const StructuralProgramKey = struct {
    dimension: u16 = 0,
    multiplicity_copy: u16 = 0,
    source_form_profile: u128 = 0,
    target_form_profile: u128 = 0,
    source_young_row_count: u8 = 0,
    source_young_rows: [max_young_rows]u8 = [_]u8{0} ** max_young_rows,
    source_young_wide_rows: [max_young_rows]usize = [_]usize{0} ** max_young_rows,
    source_young_box_count: usize = 0,
    right_young_row_count: u8 = 0,
    right_young_rows: [max_young_rows]u8 = [_]u8{0} ** max_young_rows,
    right_young_wide_rows: [max_young_rows]usize = [_]usize{0} ** max_young_rows,
    right_young_box_count: usize = 0,
    target_young_row_count: u8 = 0,
    target_young_rows: [max_young_rows]u8 = [_]u8{0} ** max_young_rows,
    target_young_wide_rows: [max_young_rows]usize = [_]usize{0} ** max_young_rows,
    target_young_box_count: usize = 0,
    source_tower_power: u16 = 0,
    target_tower_power: u16 = 0,
