    } });
}

fn appendTensorFormGammaTerm(allocator: std.mem.Allocator, atoms: *std.ArrayList(rendering.SymbolicAtom), spec: TensorFormProjectionSpec, term_index: u16) !rendering.RationalId {
    if (term_index != 0) return error.ProjectorConstructorTermOutOfBounds;
    try appendTensorFormGammaExpression(allocator, atoms, .{
        .operator_id = spec.operator_id,
        .left = spec.left,
        .right = spec.right,
        .output = spec.output,
        .orthogonal_dimension = spec.orthogonal_dimension,
        .input_form_profile = spec.input_form_profile,
        .output_form_profile = spec.output_form_profile,
        .chirality = spec.chirality,
    });
    return rendering.rationalOne();
}

/// structuralProjectorTermCount returns the streamed term count for a structural channel.
pub fn structuralProjectorTermCount(spec: StructuralProjectorSpec) u16 {
    if (tensorCompilerChannelFromStructuralOrNull(spec) catch null) |owned_channel| {
        var channel = owned_channel;
        defer channel.deinit();
        if (tensorChannelUsesDirectStructuralProgram(channel)) {
            const program = compileStructuralProjectorProgram(spec) catch return 0;
            return projectorProgramTermCount(program);
        }
        const count = tensorChannelTermCount(channel) catch |err| switch (err) {
            error.ProjectorProgramTooLarge, error.UnsupportedTensorPrimitiveTermCap => return std.math.maxInt(u16),
            else => null,
        };
        if (count) |value| {
            if (value != 0 or !tensorChannelStructuralFallbackAllowed(channel)) return value;
        }
        if (!tensorChannelStructuralFallbackAllowed(channel)) return 0;
    }
    const program = compileStructuralProjectorProgram(spec) catch return 0;
    return projectorProgramTermCount(program);
}

/// structuralProjectorTermCountWide returns the streamed term count without truncating tensor-only programs.
pub fn structuralProjectorTermCountWide(spec: StructuralProjectorSpec) !usize {
    var cache = StructuralProjectorProgramCache.init(std.heap.page_allocator);
    defer cache.deinit();
    return cache.termCountWide(spec);
}

/// structuralProjectorTermCountWideWithTensorOnlyResourcePolicy counts with tensor-only resource bounds.
pub fn structuralProjectorTermCountWideWithTensorOnlyResourcePolicy(spec: StructuralProjectorSpec, policy: TensorOnlyResourcePolicy) !usize {
    var cache = StructuralProjectorProgramCache.initWithTensorOnlyResourcePolicy(std.heap.page_allocator, policy);
    defer cache.deinit();
    return cache.termCountWide(spec);
}

/// appendStructuralProjectorTerm emits one exact structural projector program term.
pub fn appendStructuralProjectorTerm(allocator: std.mem.Allocator, atoms: *std.ArrayList(rendering.SymbolicAtom), spec: StructuralProjectorSpec, term_index: u16) !rendering.RationalId {
    return appendStructuralProjectorTermAt(allocator, atoms, spec, term_index);
}

/// appendStructuralProjectorTermAt emits one exact structural projector term with a wide streamed index.
pub fn appendStructuralProjectorTermAt(allocator: std.mem.Allocator, atoms: *std.ArrayList(rendering.SymbolicAtom), spec: StructuralProjectorSpec, term_index: usize) !rendering.RationalId {
    if (try tensorCompilerChannelFromStructuralOrNull(spec)) |owned_channel| {
        var channel = owned_channel;
        defer channel.deinit();
        if (tensorChannelUsesDirectStructuralProgram(channel)) {
            const program = try compileStructuralProjectorProgram(spec);
            return appendStructuralProjectorProgramTermAt(allocator, atoms, spec, program, term_index);
        }
        var cache = StructuralProjectorProgramCache.init(allocator);
        defer cache.deinit();
        const coefficient = cache.appendTermAt(atoms, spec, term_index) catch |err| switch (err) {
            error.UnsupportedTensorBridge => if (tensorChannelStructuralFallbackAllowed(channel)) null else return err,
            else => return err,
        };
        if (coefficient) |value| return value;
        if (!tensorChannelStructuralFallbackAllowed(channel)) return error.UnsupportedTensorBridge;
    }
    const program = try compileStructuralProjectorProgram(spec);
    return appendStructuralProjectorProgramTermAt(allocator, atoms, spec, program, term_index);
}

