/// tensorOnlyStructuralScaleAudit reports tensor-only fast-path counts before sparse pivots.
pub fn tensorOnlyStructuralScaleAudit(spec: StructuralProjectorSpec) !TensorOnlyScaleAudit {
    return tensorOnlyStructuralScaleAuditWithTensorOnlyResourcePolicy(spec, .{
        .gram_action_pair_work_limit = max_tensor_solve_audit_gram_action_pair_work,
    });
}

/// tensorOnlyStructuralScaleAuditWithTensorOnlyResourcePolicy reports pre-pivot counts under policy.
pub fn tensorOnlyStructuralScaleAuditWithTensorOnlyResourcePolicy(spec: StructuralProjectorSpec, policy: TensorOnlyResourcePolicy) !TensorOnlyScaleAudit {
    var channel = try tensorCompilerChannelFromStructural(spec);
    defer channel.deinit();
    var tensor_channel = try liveTensorOnlyChannelFromCompilerChannel(channel);
    defer tensor_channel.deinit();
    if (tensorOnlyChannelUsesProductFullColumnScalarPairingOrbitStream(tensor_channel)) {
        try budgetTensorOnlyProductFullColumnScalarPairingTermCount(tensor_channel, policy.output_term_count_limit);
        return try tensorOnlyProductFullColumnScalarPairingScaleAudit(tensor_channel);
    }
    if (tensorOnlyChannelUsesProductYoungScalarPairingOrbitStream(tensor_channel)) {
        try budgetTensorOnlyProductYoungScalarPairingTermCount(tensor_channel, policy.output_term_count_limit);
        return try tensorOnlyProductYoungScalarPairingScaleAudit(tensor_channel);
    }
    if (tensorOnlyChannelUsesOneSidedVectorProductScalarInvariantStream(tensor_channel)) {
        try budgetTensorOnlyOneSidedVectorProductScalarInvariantTermCount(tensor_channel, policy.output_term_count_limit);
        return try tensorOnlyOneSidedVectorProductScalarInvariantScaleAudit(tensor_channel);
    }
    if (tensorOnlyChannelUsesFullColumnScalarPairingOrbitStream(tensor_channel)) {
        try budgetTensorOnlyYoungScalarPairingTermCount(tensor_channel, policy.output_term_count_limit);
        return try tensorOnlyYoungScalarPairingScaleAudit(tensor_channel);
    }
    if (try prepareTensorOnlyBrauerProgramBeforePivotsForAudit(tensor_channel, policy)) |program| {
        var owned_program = program;
        defer owned_program.deinit();
        return tensorOnlyScaleAuditFromProgram(&owned_program);
    }
    var program = try prepareTensorOnlyBrauerProgramBeforePivots(tensor_channel, policy);
    defer program.deinit();
    return tensorOnlyScaleAuditFromProgram(&program);
}

/// tensorOnlyStructuralSolveAudit reports tensor-only post-pivot sparse and term-index pressure.
pub fn tensorOnlyStructuralSolveAudit(spec: StructuralProjectorSpec) !TensorOnlySolveAudit {
    return tensorOnlyStructuralSolveAuditWithTensorOnlyResourcePolicy(spec, .{
        .gram_action_pair_work_limit = max_tensor_solve_audit_gram_action_pair_work,
    });
}

/// tensorOnlyStructuralSolveAuditWithTensorOnlyResourcePolicy reports solved counts under policy.
pub fn tensorOnlyStructuralSolveAuditWithTensorOnlyResourcePolicy(spec: StructuralProjectorSpec, policy: TensorOnlyResourcePolicy) !TensorOnlySolveAudit {
    var channel = try tensorCompilerChannelFromStructural(spec);
    defer channel.deinit();
    var tensor_channel = try liveTensorOnlyChannelFromCompilerChannel(channel);
    defer tensor_channel.deinit();
    if (tensorOnlyChannelUsesProductFullColumnScalarPairingOrbitStream(tensor_channel)) {
        try budgetTensorOnlyProductFullColumnScalarPairingTermCount(tensor_channel, policy.output_term_count_limit);
        return try tensorOnlyProductFullColumnScalarPairingSolveAudit(tensor_channel);
    }
    if (tensorOnlyChannelUsesProductYoungScalarPairingOrbitStream(tensor_channel)) {
        try budgetTensorOnlyProductYoungScalarPairingTermCount(tensor_channel, policy.output_term_count_limit);
        return try tensorOnlyProductYoungScalarPairingSolveAudit(tensor_channel);
    }
    if (tensorOnlyChannelUsesOneSidedVectorProductScalarInvariantStream(tensor_channel)) {
        try budgetTensorOnlyOneSidedVectorProductScalarInvariantTermCount(tensor_channel, policy.output_term_count_limit);
        return try tensorOnlyOneSidedVectorProductScalarInvariantSolveAudit(tensor_channel);
    }
    if (tensorOnlyChannelUsesFullColumnScalarPairingOrbitStream(tensor_channel)) {
        try budgetTensorOnlyYoungScalarPairingTermCount(tensor_channel, policy.output_term_count_limit);
        return try tensorOnlyYoungScalarPairingSolveAudit(tensor_channel);
    }
    if (try compileTensorOnlyBrauerProgramForAudit(tensor_channel, policy)) |program| {
        var owned_program = program;
        defer owned_program.deinit();
        return tensorOnlySolveAuditFromProgram(&owned_program);
    }
    var program = try prepareTensorOnlyBrauerProgramBeforePivots(tensor_channel, policy);
    defer program.deinit();
    try finishTensorOnlyProgram(&program);
    if (program.term_count == 0) return error.UnsupportedStructuralProjectorTerm;
    return tensorOnlySolveAuditFromProgram(&program);
}

/// tensorOnlyStructuralRenderPageAudit renders one tensor-only page and classifies atom compactness.
pub fn tensorOnlyStructuralRenderPageAudit(spec: StructuralProjectorSpec, first_term: usize, max_terms: usize) !TensorOnlyRenderPageAudit {
    return tensorOnlyStructuralRenderPageAuditWithTensorOnlyResourcePolicy(spec, first_term, max_terms, .{
        .term_pair_work_limit = std.math.maxInt(u64),
    });
}

/// tensorOnlyStructuralRenderPageAuditWithTensorOnlyResourcePolicy renders one page under policy.
pub fn tensorOnlyStructuralRenderPageAuditWithTensorOnlyResourcePolicy(spec: StructuralProjectorSpec, first_term: usize, max_terms: usize, policy: TensorOnlyResourcePolicy) !TensorOnlyRenderPageAudit {
    if (try tensorCompilerChannelFromStructuralOrNull(spec)) |owned_channel| {
        var channel = owned_channel;
        defer channel.deinit();
        const maybe_tensor_channel: ?TensorOnlyChannel = liveTensorOnlyChannelFromCompilerChannel(channel) catch |err| switch (err) {
            error.UnsupportedTensorBridge => null,
            else => return err,
        };
        if (maybe_tensor_channel) |owned_tensor_channel| {
            var tensor_channel = owned_tensor_channel;
            defer tensor_channel.deinit();
            if (tensorOnlyChannelUsesSymmetricDeltaOrbitStream(tensor_channel)) {
                var cache = StructuralProjectorProgramCache.initWithTensorOnlyResourcePolicy(std.heap.page_allocator, policy);
                defer cache.deinit();
                const term_count = try cache.termCountWide(spec);
                var atoms: std.ArrayList(rendering.SymbolicAtom) = .empty;
                defer atoms.deinit(std.heap.page_allocator);
                var coefficients: std.ArrayList(rendering.RationalId) = .empty;
                defer coefficients.deinit(std.heap.page_allocator);
                var atom_ends: std.ArrayList(usize) = .empty;
                defer atom_ends.deinit(std.heap.page_allocator);
                const emitted = try cache.appendTermPage(&atoms, &coefficients, &atom_ends, spec, first_term, max_terms);
                return tensorOnlyRenderPageAuditFromPage(term_count, emitted, atoms.items, coefficients.items, atom_ends.items);
            }
            if (tensorOnlyChannelUsesProductFullColumnScalarPairingOrbitStream(tensor_channel)) {
                var cache = StructuralProjectorProgramCache.initWithTensorOnlyResourcePolicy(std.heap.page_allocator, policy);
                defer cache.deinit();
                const term_count_wide = try tensorOnlyProductFullColumnScalarPairingTermCountWide(tensor_channel);
                const term_count = std.math.cast(usize, term_count_wide) orelse std.math.maxInt(usize);
                var atoms: std.ArrayList(rendering.SymbolicAtom) = .empty;
                defer atoms.deinit(std.heap.page_allocator);
                var coefficients: std.ArrayList(rendering.RationalId) = .empty;
                defer coefficients.deinit(std.heap.page_allocator);
                var atom_ends: std.ArrayList(usize) = .empty;
                defer atom_ends.deinit(std.heap.page_allocator);
                const emitted = try cache.appendTermPage(&atoms, &coefficients, &atom_ends, spec, first_term, max_terms);
                return tensorOnlyRenderPageAuditFromPageWide(term_count, term_count_wide, emitted, atoms.items, coefficients.items, atom_ends.items);
            }
            if (tensorOnlyChannelUsesProductYoungScalarPairingOrbitStream(tensor_channel)) {
                var cache = StructuralProjectorProgramCache.initWithTensorOnlyResourcePolicy(std.heap.page_allocator, policy);
                defer cache.deinit();
                const term_count = try tensorOnlyProductYoungScalarPairingTermCount(tensor_channel);
                var atoms: std.ArrayList(rendering.SymbolicAtom) = .empty;
                defer atoms.deinit(std.heap.page_allocator);
                var coefficients: std.ArrayList(rendering.RationalId) = .empty;
                defer coefficients.deinit(std.heap.page_allocator);
                var atom_ends: std.ArrayList(usize) = .empty;
                defer atom_ends.deinit(std.heap.page_allocator);
                const emitted = try cache.appendTermPage(&atoms, &coefficients, &atom_ends, spec, first_term, max_terms);
                return tensorOnlyRenderPageAuditFromPage(term_count, emitted, atoms.items, coefficients.items, atom_ends.items);
            }
            if (tensorOnlyChannelUsesOneSidedVectorProductScalarInvariantStream(tensor_channel)) {
                var cache = StructuralProjectorProgramCache.initWithTensorOnlyResourcePolicy(std.heap.page_allocator, policy);
                defer cache.deinit();
                const term_count = try tensorOnlyOneSidedVectorProductScalarInvariantTermCount(tensor_channel);
                if (term_count > policy.output_term_count_limit) return error.TensorResourceBudgetExceeded;
                var atoms: std.ArrayList(rendering.SymbolicAtom) = .empty;
                defer atoms.deinit(std.heap.page_allocator);
                var coefficients: std.ArrayList(rendering.RationalId) = .empty;
                defer coefficients.deinit(std.heap.page_allocator);
                var atom_ends: std.ArrayList(usize) = .empty;
                defer atom_ends.deinit(std.heap.page_allocator);
                const emitted = try cache.appendTermPage(&atoms, &coefficients, &atom_ends, spec, first_term, max_terms);
                return tensorOnlyRenderPageAuditFromPage(term_count, emitted, atoms.items, coefficients.items, atom_ends.items);
            }
            if (tensorOnlyChannelUsesFullColumnScalarPairingOrbitStream(tensor_channel)) {
                var cache = StructuralProjectorProgramCache.initWithTensorOnlyResourcePolicy(std.heap.page_allocator, policy);
                defer cache.deinit();
                const term_count_wide = try factorialU128ForResourceCount(tensor_channel.left.slot_count);
                const term_count = std.math.cast(usize, term_count_wide) orelse std.math.maxInt(usize);
                var atoms: std.ArrayList(rendering.SymbolicAtom) = .empty;
                defer atoms.deinit(std.heap.page_allocator);
                var coefficients: std.ArrayList(rendering.RationalId) = .empty;
                defer coefficients.deinit(std.heap.page_allocator);
                var atom_ends: std.ArrayList(usize) = .empty;
                defer atom_ends.deinit(std.heap.page_allocator);
                const emitted = try cache.appendTermPage(&atoms, &coefficients, &atom_ends, spec, first_term, max_terms);
                return tensorOnlyRenderPageAuditFromPageWide(term_count, term_count_wide, emitted, atoms.items, coefficients.items, atom_ends.items);
            }
            if (try compileTensorOnlyBrauerProgramForAudit(tensor_channel, policy)) |program| {
                var owned_program = program;
                defer owned_program.deinit();
                var atoms: std.ArrayList(rendering.SymbolicAtom) = .empty;
                defer atoms.deinit(std.heap.page_allocator);
                var coefficients: std.ArrayList(rendering.RationalId) = .empty;
                defer coefficients.deinit(std.heap.page_allocator);
                var atom_ends: std.ArrayList(usize) = .empty;
                defer atom_ends.deinit(std.heap.page_allocator);
                const emitted = try appendTensorOnlyProgramTermPage(std.heap.page_allocator, &atoms, &coefficients, &atom_ends, &owned_program, first_term, max_terms);
                return tensorOnlyRenderPageAuditFromPage(owned_program.term_count, emitted, atoms.items, coefficients.items, atom_ends.items);
            }
            var program = try prepareTensorOnlyBrauerProgramBeforePivots(tensor_channel, policy);
            defer program.deinit();
            if (try tensorOnlySingleCandidateRenderPageAudit(&program, first_term, max_terms)) |audit| return audit;
            try finishTensorOnlyProgram(&program);
            if (program.term_count == 0) return error.UnsupportedStructuralProjectorTerm;
            var atoms: std.ArrayList(rendering.SymbolicAtom) = .empty;
            defer atoms.deinit(std.heap.page_allocator);
            var coefficients: std.ArrayList(rendering.RationalId) = .empty;
            defer coefficients.deinit(std.heap.page_allocator);
            var atom_ends: std.ArrayList(usize) = .empty;
            defer atom_ends.deinit(std.heap.page_allocator);
            const emitted = try appendTensorOnlyProgramTermPage(std.heap.page_allocator, &atoms, &coefficients, &atom_ends, &program, first_term, max_terms);
            return tensorOnlyRenderPageAuditFromPage(program.term_count, emitted, atoms.items, coefficients.items, atom_ends.items);
        }
    }
    var cache = StructuralProjectorProgramCache.initWithTensorOnlyResourcePolicy(std.heap.page_allocator, policy);
    defer cache.deinit();
    const term_count = try cache.termCountWide(spec);
    var atoms: std.ArrayList(rendering.SymbolicAtom) = .empty;
    defer atoms.deinit(std.heap.page_allocator);
    var coefficients: std.ArrayList(rendering.RationalId) = .empty;
    defer coefficients.deinit(std.heap.page_allocator);
    var atom_ends: std.ArrayList(usize) = .empty;
    defer atom_ends.deinit(std.heap.page_allocator);
    const emitted = try cache.appendTermPage(&atoms, &coefficients, &atom_ends, spec, first_term, max_terms);

    return tensorOnlyRenderPageAuditFromPage(term_count, emitted, atoms.items, coefficients.items, atom_ends.items);
}

fn tensorOnlySingleCandidateRenderPageAudit(program: *const TensorOnlyProgram, first_term: usize, max_terms: usize) !?TensorOnlyRenderPageAudit {
    var atoms: std.ArrayList(rendering.SymbolicAtom) = .empty;
    defer atoms.deinit(std.heap.page_allocator);
    var coefficients: std.ArrayList(rendering.RationalId) = .empty;
    defer coefficients.deinit(std.heap.page_allocator);
    var atom_ends: std.ArrayList(usize) = .empty;
    defer atom_ends.deinit(std.heap.page_allocator);

    const term_count = (try tensorOnlySingleCandidateExpandedTermCount(program)) orelse return null;
    const page_limit = @min(max_terms, program.resource_policy.output_term_page_limit);
    const emitted = (try appendTensorOnlySingleCandidateExpandedTermPage(std.heap.page_allocator, &atoms, &coefficients, &atom_ends, program, first_term, page_limit)).?;
    return tensorOnlyRenderPageAuditFromPage(term_count, emitted, atoms.items, coefficients.items, atom_ends.items);
}

fn tensorOnlyLongSymmetricDeltaOrbitProjectedAction(channel: TensorOnlyChannel, resource_policy: TensorOnlyResourcePolicy) !TensorEndpointActionBuildBuffer {
    if (!tensorOnlyChannelUsesSymmetricDeltaOrbitStream(channel)) return error.UnsupportedStructuralProjectorTerm;
    var output_projector = try endpointProjectorWithPolicy(channel.output, channel.dimension, resource_policy);
    defer output_projector.deinit();

    var raw_action: TensorEndpointActionBuildBuffer = .{ .word_limit = resource_policy.endpoint_action_word_limit };
    defer raw_action.deinit();
    try appendTensorEndpointActionWord(&raw_action, .{ .word = try tensorOnlySymmetricDeltaOrbitRepresentative(channel) });
    return try applyTensorEndpointProjectorActionWithPolicy(channel, .output, &output_projector, raw_action, resource_policy);
}

fn appendTensorOnlySymmetricDeltaOrbitActionPairTermPage(
    allocator: std.mem.Allocator,
    atoms: *std.ArrayList(rendering.SymbolicAtom),
    coefficients: *std.ArrayList(rendering.RationalId),
    atom_ends: *std.ArrayList(usize),
    channel: TensorOnlyChannel,
    coefficient: Rational,
    action_word_count: usize,
    first_term: usize,
    max_terms: usize,
    resource_policy: TensorOnlyResourcePolicy,
) !usize {
    if (max_terms == 0) return 0;
    var left_ordinal = first_term / action_word_count;
    var right_ordinal = first_term % action_word_count;
    var emitted: usize = 0;
    while (emitted < max_terms and left_ordinal < action_word_count) {
        {
            var left_word = try tensorOnlySymmetricDeltaOrbitActionWordAt(channel, left_ordinal, resource_policy);
            defer left_word.deinit();
            var right_word = try tensorOnlySymmetricDeltaOrbitActionWordAt(channel, right_ordinal, resource_policy);
            defer right_word.deinit();
            var term = try tensorOnlyActionWordPairTerm(channel, left_word, right_word, coefficient);
            defer term.deinit();
            const rendered_coefficient = try appendVectorBrauerTermAtoms(allocator, atoms, term);
            try coefficients.append(allocator, rendered_coefficient);
            try atom_ends.append(allocator, atoms.items.len);
        }
        emitted += 1;

        right_ordinal += 1;
        if (right_ordinal == action_word_count) {
            right_ordinal = 0;
            left_ordinal += 1;
        }
    }
    return emitted;
}

fn tensorOnlySymmetricDeltaOrbitActionWordAt(channel: TensorOnlyChannel, ordinal: usize, resource_policy: TensorOnlyResourcePolicy) !TensorEndpointActionWord {
    var word = try tensorOnlySymmetricDeltaOrbitBoundaryMatchingWordAt(channel, ordinal);
    errdefer word.deinit();
    word.coefficient = try tensorOnlySymmetricDeltaOrbitBoundaryMatchingCoefficient(channel, word, resource_policy);
    return .{ .word = moveBrauerWord(&word) };
}

fn tensorOnlySymmetricDeltaOrbitBoundaryMatchingWordAt(channel: TensorOnlyChannel, ordinal: usize) !BrauerWord {
    if (!tensorOnlyChannelUsesSymmetricDeltaOrbitStream(channel)) return error.UnsupportedStructuralProjectorTerm;
    const total = std.math.mul(usize, 2, channel.output.slot_count) catch return error.TensorResourceBudgetExceeded;
    const count = try oddDoubleFactorialUsize(total);
    if (ordinal >= count) return error.ProjectorConstructorTermOutOfBounds;
    const allocator = std.heap.page_allocator;
    const used = try allocator.alloc(bool, total);
    defer allocator.free(used);
    @memset(used, false);
    var remaining_ordinal = ordinal;
    var word = BrauerWord{ .coefficient = Rational.one() };
    errdefer word.deinit();
    try appendTensorOnlyBoundaryMatchingWordAtRec(channel, used, 0, &remaining_ordinal, &word);
    canonicalizeBrauerWord(&word);
    return word;
}

fn appendTensorOnlyBoundaryMatchingWordAtRec(channel: TensorOnlyChannel, used: []bool, used_count: usize, ordinal: *usize, word: *BrauerWord) !void {
    if (used_count == used.len) return;
    const first = firstUnusedTensorBoundarySlotDynamic(used) orelse return;
    const remaining_after_pair = used.len - used_count - 2;
    const branch_count = try oddDoubleFactorialUsize(remaining_after_pair);
    var second = first + 1;
    while (second < used.len) : (second += 1) {
        if (used[second]) continue;
        if (ordinal.* >= branch_count) {
            ordinal.* -= branch_count;
            continue;
        }
        used[first] = true;
        used[second] = true;
        try pushTensorBrauerBoundaryEdge(channel, word, first, second);
        try appendTensorOnlyBoundaryMatchingWordAtRec(channel, used, used_count + 2, ordinal, word);
        return;
    }
    return error.ProjectorConstructorTermOutOfBounds;
}

fn tensorOnlySymmetricDeltaOrbitBoundaryMatchingCoefficient(channel: TensorOnlyChannel, word: BrauerWord, resource_policy: TensorOnlyResourcePolicy) !Rational {
    const trace_count = try tensorOnlySymmetricDeltaOrbitBoundaryTraceCount(word);
    var coefficient = try symmetricTraceRemovalCoefficientWide(channel.output.slot_count, channel.dimension, trace_count);
    coefficient = try coefficient.mul(try tensorOnlyFactorialDenominatorCoefficient(channel.output.slot_count, resource_policy));
    var multiplicity: usize = 0;
    while (multiplicity < trace_count) : (multiplicity += 1) {
        coefficient = try coefficient.mul(try Rational.init(2, 1));
        try budgetTensorOnlyCoefficient(coefficient, resource_policy);
    }
    try budgetTensorOnlyCoefficient(coefficient, resource_policy);
    return coefficient;
}

fn tensorOnlySymmetricDeltaOrbitBoundaryTraceCount(word: BrauerWord) !usize {
    var input_trace_count: usize = 0;
    var output_metric_count: usize = 0;
    var edge_index: usize = 0;
    while (edge_index < word.edge_count) : (edge_index += 1) {
        switch (brauerWordEdge(word, edge_index).kind) {
            .delta => {},
            .input_trace => input_trace_count += 1,
            .output_metric => output_metric_count += 1,
        }
    }
    if (input_trace_count != output_metric_count) return error.UnsupportedStructuralProjectorTerm;
    return input_trace_count;
}

fn symmetricTraceRemovalCoefficientWide(rank: usize, dimension: u16, trace_count: usize) !Rational {
    if (trace_count == 0) return Rational.one();
    const rank_i64 = std.math.cast(i64, rank) orelse return error.TensorResourceBudgetExceeded;
    var denominator: i64 = 1;
    var step: usize = 0;
    while (step < trace_count) : (step += 1) {
        const step_i64 = std.math.cast(i64, step) orelse return error.TensorResourceBudgetExceeded;
        const term = try checkedSubI64(
            try checkedAddI64(@intCast(dimension), try checkedMulI64(2, rank_i64)),
            try checkedAddI64(4, try checkedMulI64(2, step_i64)),
        );
        if (term == 0) return error.SingularGramMatrix;
        denominator = try checkedMulI64(denominator, term);
    }
    const numerator: i64 = if (trace_count % 2 == 0) 1 else -1;
    return Rational.init(numerator, denominator);
}

fn tensorOnlySymmetricDeltaOrbitProjectedActionWordCount(channel: TensorOnlyChannel) !usize {
    if (!tensorOnlyChannelUsesSymmetricDeltaOrbitStream(channel)) return error.UnsupportedStructuralProjectorTerm;
    const total = std.math.mul(usize, 2, channel.output.slot_count) catch return error.TensorResourceBudgetExceeded;
    return oddDoubleFactorialUsize(total);
}

fn oddDoubleFactorialUsize(total: usize) !usize {
    var out: usize = 1;
    var factor: usize = if (total == 0) 1 else total - 1;
    while (factor > 1) : (factor -= 2) {
        out = std.math.mul(usize, out, factor) catch return error.TensorResourceBudgetExceeded;
    }
    return out;
}

fn tensorEndpointActionBufferFromBuild(action: TensorEndpointActionBuildBuffer) TensorEndpointActionBuffer {
    return .{
        .word_count = action.word_count,
        .words = action.words[0..action.word_count],
        .owns_words = false,
    };
}

fn countTensorEndpointActionPairTerms(left: TensorEndpointActionBuffer, right: TensorEndpointActionBuffer) !usize {
    return std.math.mul(
        usize,
        countNonzeroTensorEndpointActionWords(left),
        countNonzeroTensorEndpointActionWords(right),
    ) catch return error.TensorResourceBudgetExceeded;
}

fn tensorOnlySymmetricDeltaOrbitNormalization(channel: TensorOnlyChannel) !Rational {
    const dimension = symmetricTraceFreeDimensionI64(channel.dimension, channel.output.slot_count) catch |err| switch (err) {
        error.GramIntegerOverflow => return error.TensorResourceBudgetExceeded,
        else => return err,
    };
    return try Rational.one().div(try Rational.init(dimension, 1));
}

fn tensorOnlySingleCandidateExpandedTermCount(program: *const TensorOnlyProgram) !?usize {
    if (program.candidate_count != 1) return null;
    const coefficient = (try tensorOnlySingleCandidatePairCoefficient(program)) orelse return null;
    return try countTensorOnlyCandidatePairActionTermsFast(program, program.candidates[0], program.candidates[0], coefficient);
}

fn appendTensorOnlySingleCandidateExpandedTermPage(
    allocator: std.mem.Allocator,
    atoms: *std.ArrayList(rendering.SymbolicAtom),
    coefficients: *std.ArrayList(rendering.RationalId),
    atom_ends: *std.ArrayList(usize),
    program: *const TensorOnlyProgram,
    first_term: usize,
    max_terms: usize,
) !?usize {
    if (program.candidate_count != 1) return null;
    const coefficient = (try tensorOnlySingleCandidatePairCoefficient(program)) orelse return null;
    const term_count = try countTensorOnlyCandidatePairActionTermsFast(program, program.candidates[0], program.candidates[0], coefficient);
    if (first_term > term_count) return error.ProjectorConstructorTermOutOfBounds;
    return try appendTensorOnlyCandidatePairActionTermPage(allocator, program, atoms, coefficients, atom_ends, program.candidates[0], program.candidates[0], coefficient, first_term, max_terms);
}

fn tensorOnlySingleCandidatePairCoefficient(program: *const TensorOnlyProgram) !?Rational {
    if (program.candidate_count != 1) return null;
    const gram = if (try tensorOnlySymmetricDeltaOrbitCandidateInnerProduct(program, program.candidates[0], program.candidates[0])) |fast_gram|
        fast_gram
    else blk: {
        try budgetTensorOnlySingleCandidateNormalization(program, program.candidates[0]);
        break :blk try tensorOnlyCandidateInnerProductByEndpointActions(program, program.candidates[0], program.candidates[0]);
    };
    if (gram.numerator == 0) return error.SingularGramMatrix;
    return try Rational.one().div(gram);
}

fn tensorOnlyChannelInputSlotCountMatches(channel: TensorOnlyChannel) bool {
    const expected = std.math.add(usize, channel.left.slot_count, channel.right.slot_count) catch return false;
    return channel.input_slot_count == expected;
}

fn tensorOnlyChannelUsesYoungScalarPairingOrbitStream(channel: TensorOnlyChannel) bool {
    if (channel.output.kind != .scalar or channel.output_slot_count != 0) return false;
    if (!tensorOnlyEndpointUsesPureYoungScalarPairingOrbit(channel.left)) return false;
    if (!tensorOnlyEndpointUsesPureYoungScalarPairingOrbit(channel.right)) return false;
    if (channel.left.duality != .none or channel.right.duality != .none) return false;
    if (channel.left.slot_count == 0 or channel.left.slot_count != channel.right.slot_count) return false;
    if (!tensorOnlyChannelInputSlotCountMatches(channel)) return false;
    return tensorOnlyEndpointShapeEql(channel.left, channel.right) and
        tensorOnlyEndpointUsesFullColumnAntisymmetry(channel.left);
}

fn tensorOnlyChannelUsesFullColumnScalarPairingOrbitStream(channel: TensorOnlyChannel) bool {
    return tensorOnlyChannelUsesYoungScalarPairingOrbitStream(channel);
}

fn tensorOnlyChannelUsesProductFullColumnScalarPairingOrbitStream(channel: TensorOnlyChannel) bool {
    var pairing = (tensorOnlyProductFullColumnScalarPairingFactorPairing(channel) catch return false) orelse return false;
    defer pairing.deinit();
    return true;
}

fn tensorOnlyChannelUsesProductYoungScalarPairingOrbitStream(channel: TensorOnlyChannel) bool {
    var pairing = (tensorOnlyProductYoungScalarPairingFactorPairing(channel) catch return false) orelse return false;
    defer pairing.deinit();
    return true;
}

fn tensorOnlyProductFullColumnScalarPairingFactorPairing(channel: TensorOnlyChannel) !?TensorOnlyProductFactorPairing {
    if (channel.output.kind != .scalar or channel.output_slot_count != 0) return null;
    if (channel.left.kind != .product or channel.right.kind != .product) return null;
    if (channel.left.factor_count == 0 or channel.left.factor_count != channel.right.factor_count) return null;
    if (channel.left.slot_count == 0 or channel.left.slot_count != channel.right.slot_count) return null;
    if (!tensorOnlyChannelInputSlotCountMatches(channel)) return null;
    const allocator = std.heap.page_allocator;
    var out = TensorOnlyProductFactorPairing{
        .right_indices = try allocator.alloc(usize, channel.left.factor_count),
    };
    errdefer out.deinit();
    const used = try allocator.alloc(bool, channel.right.factor_count);
    defer allocator.free(used);
    @memset(used, false);
    var factor_index: usize = 0;
    while (factor_index < channel.left.factor_count) : (factor_index += 1) {
        const left_factor = channel.left.factors[factor_index];
        if (!tensorOnlyEndpointFactorUsesFullColumnScalarPairingOrbit(left_factor)) {
            out.deinit();
            return null;
        }
        var right_index: usize = 0;
        while (right_index < channel.right.factor_count) : (right_index += 1) {
            if (used[right_index]) continue;
            const right_factor = channel.right.factors[right_index];
            if (!tensorOnlyEndpointFactorUsesFullColumnScalarPairingOrbit(right_factor)) continue;
            if (!tensorOnlyEndpointFactorShapeEql(left_factor, right_factor)) continue;
            used[right_index] = true;
            out.right_indices[factor_index] = right_index;
            break;
        }
        if (right_index == channel.right.factor_count) {
            out.deinit();
            return null;
        }
    }
    return out;
}

fn tensorOnlyProductYoungScalarPairingFactorPairing(channel: TensorOnlyChannel) !?TensorOnlyProductFactorPairing {
    if (channel.output.kind != .scalar or channel.output_slot_count != 0) return null;
    if (channel.left.kind != .product or channel.right.kind != .product) return null;
    if (channel.left.factor_count == 0 or channel.left.factor_count != channel.right.factor_count) return null;
    if (channel.left.slot_count == 0 or channel.left.slot_count != channel.right.slot_count) return null;
    if (!tensorOnlyChannelInputSlotCountMatches(channel)) return null;
    const allocator = std.heap.page_allocator;
    var out = TensorOnlyProductFactorPairing{
        .right_indices = try allocator.alloc(usize, channel.left.factor_count),
    };
    errdefer out.deinit();
    const used = try allocator.alloc(bool, channel.right.factor_count);
    defer allocator.free(used);
    @memset(used, false);
    var factor_index: usize = 0;
    while (factor_index < channel.left.factor_count) : (factor_index += 1) {
        const left_factor = channel.left.factors[factor_index];
        if (!tensorOnlyEndpointFactorUsesPureYoungScalarPairingOrbit(left_factor)) {
            out.deinit();
            return null;
        }
        var right_index: usize = 0;
        while (right_index < channel.right.factor_count) : (right_index += 1) {
            if (used[right_index]) continue;
            const right_factor = channel.right.factors[right_index];
            if (!tensorOnlyEndpointFactorUsesPureYoungScalarPairingOrbit(right_factor)) continue;
            if (!tensorOnlyEndpointFactorShapeEql(left_factor, right_factor)) continue;
            _ = tensorOnlyEndpointFactorYoungShape(left_factor) catch continue;
            _ = tensorOnlyEndpointFactorYoungShape(right_factor) catch continue;
            used[right_index] = true;
            out.right_indices[factor_index] = right_index;
            break;
        }
        if (right_index == channel.right.factor_count) {
            out.deinit();
            return null;
        }
    }
    return out;
}

fn tensorOnlyEndpointUsesPureYoungScalarPairingOrbit(endpoint: TensorOnlyEndpoint) bool {
    return endpoint.kind == .vector_young or endpoint.kind == .exterior_form;
}

fn tensorOnlyEndpointFactorUsesPureYoungScalarPairingOrbit(factor: TensorOnlyEndpointFactor) bool {
    if (factor.duality != .none) return false;
    const endpoint = tensorOnlyEndpointFromFactor(.left, factor);
    return tensorOnlyEndpointUsesPureYoungScalarPairingOrbit(endpoint);
}

fn tensorOnlyEndpointFactorUsesFullColumnScalarPairingOrbit(factor: TensorOnlyEndpointFactor) bool {
    if (factor.duality != .none) return false;
    const endpoint = tensorOnlyEndpointFromFactor(.left, factor);
    return tensorOnlyEndpointUsesPureYoungScalarPairingOrbit(endpoint) and
        tensorOnlyEndpointUsesFullColumnAntisymmetry(endpoint);
}

fn tensorOnlyEndpointFactorShapeEql(left: TensorOnlyEndpointFactor, right: TensorOnlyEndpointFactor) bool {
    const left_endpoint = tensorOnlyEndpointFromFactor(.left, left);
    const right_endpoint = tensorOnlyEndpointFromFactor(.right, right);
    return tensorOnlyEndpointShapeEql(left_endpoint, right_endpoint);
}

fn tensorOnlyEndpointFactorYoungShape(factor: TensorOnlyEndpointFactor) !YoungShape {
    const endpoint = tensorOnlyEndpointFromFactor(.left, factor);
    return tensorOnlyEndpointShape(endpoint);
}

fn tensorOnlyProductYoungScalarPairingFactorSpec(channel: TensorOnlyChannel, pairing: TensorOnlyProductFactorPairing, factor_index: usize) !TensorPairingSpec {
    if (factor_index >= channel.left.factor_count or factor_index >= pairing.right_indices.len) return error.ProjectorConstructorTermOutOfBounds;
    const left_factor = channel.left.factors[factor_index];
    const right_factor = channel.right.factors[pairing.right_indices[factor_index]];
    return .{
        .operator_id = channel.operator_id,
        .dimension = channel.dimension,
        .left = left_factor.block,
        .left_form_profile = left_factor.form_profile,
        .right = right_factor.block,
        .right_form_profile = right_factor.form_profile,
        .shape = try tensorOnlyEndpointFactorYoungShape(left_factor),
    };
}

fn tensorOnlyEndpointShapeEql(left: TensorOnlyEndpoint, right: TensorOnlyEndpoint) bool {
    if (left.row_count != right.row_count or left.slot_count != right.slot_count) return false;
    const left_rows = endpointShapeWideRows(&left);
    const right_rows = endpointShapeWideRows(&right);
    var row: usize = 0;
    while (row < left_rows.len) : (row += 1) {
        if (left_rows[row] != right_rows[row]) return false;
    }
    return true;
}

fn tensorOnlyEndpointUsesFullColumnAntisymmetry(endpoint: TensorOnlyEndpoint) bool {
    if (endpoint.row_count != endpoint.slot_count or endpoint.column_count != 1) return false;
    const rows = endpointShapeWideRows(&endpoint);
    var row: usize = 0;
    while (row < endpoint.row_count) : (row += 1) {
        if (rows[row] != 1) return false;
    }
    return true;
}

fn tensorOnlyYoungScalarPairingTermCount(channel: TensorOnlyChannel) !usize {
    if (!tensorOnlyChannelUsesFullColumnScalarPairingOrbitStream(channel)) return error.UnsupportedStructuralProjectorTerm;
    return try factorialUsizeForResourceCount(channel.left.slot_count);
}

fn tensorOnlyProductFullColumnScalarPairingTermCount(channel: TensorOnlyChannel) !usize {
    var pairing = (try tensorOnlyProductFullColumnScalarPairingFactorPairing(channel)) orelse return error.UnsupportedStructuralProjectorTerm;
    defer pairing.deinit();
    return try tensorOnlyProductFullColumnScalarPairingTermCountWithPairing(channel, pairing);
}

fn tensorOnlyProductYoungScalarPairingTermCount(channel: TensorOnlyChannel) !usize {
    var pairing = (try tensorOnlyProductYoungScalarPairingFactorPairing(channel)) orelse return error.UnsupportedStructuralProjectorTerm;
    defer pairing.deinit();
    return try tensorOnlyProductYoungScalarPairingTermCountWithPairing(channel, pairing);
}

fn tensorOnlyProductFullColumnScalarPairingTermCountWithPairing(channel: TensorOnlyChannel, pairing: TensorOnlyProductFactorPairing) !usize {
    if (pairing.right_indices.len != channel.left.factor_count) return error.UnsupportedStructuralProjectorTerm;
    var count: usize = 1;
    var factor_index: usize = 0;
    while (factor_index < channel.left.factor_count) : (factor_index += 1) {
        const factor_count = try factorialUsizeForResourceCount(channel.left.factors[factor_index].slot_count);
        count = std.math.mul(usize, count, factor_count) catch return error.TensorResourceBudgetExceeded;
    }
    return count;
}

fn tensorOnlyProductFullColumnScalarPairingTermCountOrNullWithPairing(channel: TensorOnlyChannel, pairing: TensorOnlyProductFactorPairing) !?usize {
    if (pairing.right_indices.len != channel.left.factor_count) return error.UnsupportedStructuralProjectorTerm;
    var count: usize = 1;
    var factor_index: usize = 0;
    while (factor_index < channel.left.factor_count) : (factor_index += 1) {
        const factor_count = factorialUsizeOrNull(channel.left.factors[factor_index].slot_count) orelse return null;
        if (count > std.math.maxInt(usize) / factor_count) return null;
        count *= factor_count;
    }
    return count;
}

fn tensorOnlyProductYoungScalarPairingTermCountWithPairing(channel: TensorOnlyChannel, pairing: TensorOnlyProductFactorPairing) !usize {
    if (pairing.right_indices.len != channel.left.factor_count) return error.UnsupportedStructuralProjectorTerm;
    var count: usize = 1;
    var factor_index: usize = 0;
    while (factor_index < channel.left.factor_count) : (factor_index += 1) {
        const spec = try tensorOnlyProductYoungScalarPairingFactorSpec(channel, pairing, factor_index);
        const factor_count = try youngScalarPairingTermCount(spec);
        count = std.math.mul(usize, count, factor_count) catch return error.TensorResourceBudgetExceeded;
    }
    return count;
}

fn tensorOnlyProductFullColumnScalarPairingOrdinalInRange(channel: TensorOnlyChannel, pairing: TensorOnlyProductFactorPairing, ordinal: usize) !bool {
    if (pairing.right_indices.len != channel.left.factor_count) return error.UnsupportedStructuralProjectorTerm;
    var count: usize = 1;
    if (ordinal < count) return true;
    var factor_index: usize = 0;
    while (factor_index < channel.left.factor_count) : (factor_index += 1) {
        const factor_count = factorialUsizeOrNull(channel.left.factors[factor_index].slot_count) orelse return true;
        if (count > ordinal / factor_count) return true;
        count = std.math.mul(usize, count, factor_count) catch return true;
    }
    return ordinal < count;
}

fn tensorOnlyProductFullColumnScalarPairingTermCountWide(channel: TensorOnlyChannel) !u128 {
    var pairing = (try tensorOnlyProductFullColumnScalarPairingFactorPairing(channel)) orelse return error.UnsupportedStructuralProjectorTerm;
    defer pairing.deinit();
    var count: u128 = 1;
    var factor_index: usize = 0;
    while (factor_index < channel.left.factor_count) : (factor_index += 1) {
        const factor_count = try factorialU128ForResourceCount(channel.left.factors[factor_index].slot_count);
        if (factor_count > std.math.maxInt(u128) / count) return error.TensorResourceBudgetExceeded;
        count *= factor_count;
    }
    return count;
}

fn budgetTensorOnlyYoungScalarPairingTermCount(channel: TensorOnlyChannel, limit: usize) !void {
    if (!tensorOnlyChannelUsesFullColumnScalarPairingOrbitStream(channel)) return error.UnsupportedStructuralProjectorTerm;
    try budgetFactorialUsize(channel.left.slot_count, limit);
}

fn budgetTensorOnlyProductFullColumnScalarPairingTermCount(channel: TensorOnlyChannel, limit: usize) !void {
    const count = try tensorOnlyProductFullColumnScalarPairingTermCount(channel);
    if (count > limit) return error.TensorResourceBudgetExceeded;
}

