fn budgetTensorOnlySingleCandidateNormalization(program: *const TensorOnlyProgram, candidate: TensorOnlyCandidateWord) !void {
    const action_count = try countTensorOnlyCandidatePairActionTermsFast(program, candidate, candidate, Rational.one());
    if (action_count > program.resource_policy.gram_action_pair_work_limit) return error.TensorResourceBudgetExceeded;
}

fn countTensorOnlyCandidatePairActionTermsFast(program: *const TensorOnlyProgram, left: TensorOnlyCandidateWord, right: TensorOnlyCandidateWord, coefficient: Rational) !usize {
    if (coefficient.numerator == 0) return 0;
    const left_raw = try tensorOnlyWordRawDiagramIndex(program, left);
    const right_raw = try tensorOnlyWordRawDiagramIndex(program, right);
    const left_action = tensorOnlyProjectedRawAction(program, left_raw);
    const right_action = tensorOnlyProjectedRawAction(program, right_raw);
    return std.math.mul(
        usize,
        countNonzeroTensorEndpointActionWords(left_action),
        countNonzeroTensorEndpointActionWords(right_action),
    ) catch return error.TensorResourceBudgetExceeded;
}

fn countNonzeroTensorEndpointActionWords(action: TensorEndpointActionBuffer) usize {
    var count: usize = 0;
    var word_index: usize = 0;
    while (word_index < action.word_count) : (word_index += 1) {
        if (action.words[word_index].word.coefficient.numerator != 0) count += 1;
    }
    return count;
}

fn tensorEndpointActionWordsHaveNoHodge(action: TensorEndpointActionBuffer) bool {
    var word_index: usize = 0;
    while (word_index < action.word_count) : (word_index += 1) {
        if (action.words[word_index].hodge_count != 0) return false;
    }
    return true;
}

fn tensorOnlyProgramHasHodgeActions(program: *const TensorOnlyProgram) bool {
    var action_index: usize = 0;
    while (action_index < program.endpoint_action_count) : (action_index += 1) {
        if (!tensorEndpointActionWordsHaveNoHodge(program.endpoint_actions[action_index])) return true;
    }
    return false;
}

fn budgetTensorOnlyProgramHodgeCrossGram(program: *const TensorOnlyProgram) !void {
    if (!tensorOnlyProgramHasHodgeActions(program)) return;
    var exact_work: u64 = 0;
    var left_action_index: usize = 0;
    while (left_action_index < program.endpoint_action_count) : (left_action_index += 1) {
        const left_action = program.endpoint_actions[left_action_index];
        var right_action_index: usize = 0;
        while (right_action_index < program.endpoint_action_count) : (right_action_index += 1) {
            const right_action = program.endpoint_actions[right_action_index];
            var left_word_index: usize = 0;
            while (left_word_index < left_action.word_count) : (left_word_index += 1) {
                var right_word_index: usize = 0;
                while (right_word_index < right_action.word_count) : (right_word_index += 1) {
                    const left_word = left_action.words[left_word_index];
                    const right_word = right_action.words[right_word_index];
                    if ((tensorEndpointActionWordResidualHodgeGramFactor(program.channel, left_word, right_word) catch null) != null) continue;
                    const work = try tensorEndpointActionWordExactHodgeEpsilonWorkEstimate(program.channel, left_word, right_word);
                    exact_work = std.math.add(u64, exact_work, @intCast(work)) catch return error.TensorResourceBudgetExceeded;
                    if (exact_work > max_tensor_hodge_epsilon_exact_program_work) return error.TensorResourceBudgetExceeded;
                    if (exact_work > program.resource_policy.gram_action_pair_work_limit) return error.TensorResourceBudgetExceeded;
                }
            }
        }
    }
}

fn appendTensorOnlyCandidatePairActionTermPage(
    allocator: std.mem.Allocator,
    program: *const TensorOnlyProgram,
    atoms: *std.ArrayList(rendering.SymbolicAtom),
    coefficients: *std.ArrayList(rendering.RationalId),
    atom_ends: *std.ArrayList(usize),
    left: TensorOnlyCandidateWord,
    right: TensorOnlyCandidateWord,
    coefficient: Rational,
    first_term: usize,
    max_terms: usize,
) !usize {
    if (coefficient.numerator == 0 or max_terms == 0) return 0;
    const left_raw = try tensorOnlyWordRawDiagramIndex(program, left);
    const right_raw = try tensorOnlyWordRawDiagramIndex(program, right);
    const left_action = tensorOnlyProjectedRawAction(program, left_raw);
    const right_action = tensorOnlyProjectedRawAction(program, right_raw);
    return try appendTensorOnlyCandidatePairActionTermPageCartesian(allocator, program, atoms, coefficients, atom_ends, left_action, right_action, coefficient, first_term, max_terms);
}

fn appendTensorOnlyCandidatePairHodgeActionTermPage(
    allocator: std.mem.Allocator,
    program: *const TensorOnlyProgram,
    atoms: *std.ArrayList(rendering.SymbolicAtom),
    coefficients: *std.ArrayList(rendering.RationalId),
    atom_ends: *std.ArrayList(usize),
    left_action: TensorEndpointActionBuffer,
    right_action: TensorEndpointActionBuffer,
    coefficient: Rational,
    first_term: usize,
    max_terms: usize,
) !usize {
    return appendTensorOnlyCandidatePairActionTermPageCartesian(
        allocator,
        program,
        atoms,
        coefficients,
        atom_ends,
        left_action,
        right_action,
        coefficient,
        first_term,
        max_terms,
    );
}

fn appendTensorOnlyCandidatePairActionTermPageCartesian(
    allocator: std.mem.Allocator,
    program: *const TensorOnlyProgram,
    atoms: *std.ArrayList(rendering.SymbolicAtom),
    coefficients: *std.ArrayList(rendering.RationalId),
    atom_ends: *std.ArrayList(usize),
    left_action: TensorEndpointActionBuffer,
    right_action: TensorEndpointActionBuffer,
    coefficient: Rational,
    first_term: usize,
    max_terms: usize,
) !usize {
    const right_nonzero_count = countNonzeroTensorEndpointActionWords(right_action);
    if (right_nonzero_count == 0) return 0;
    const left_ordinal = first_term / right_nonzero_count;
    const right_ordinal = first_term % right_nonzero_count;
    var left_index = tensorEndpointActionNthNonzeroWordIndex(left_action, left_ordinal) orelse return 0;
    var right_index = tensorEndpointActionNthNonzeroWordIndex(right_action, right_ordinal) orelse return 0;

    var emitted: usize = 0;
    while (emitted < max_terms and left_index < left_action.word_count) {
        const left_word = left_action.words[left_index];
        const right_word = right_action.words[right_index];
        var word_coefficient = try coefficient.mul(left_word.word.coefficient);
        word_coefficient = try word_coefficient.mul(right_word.word.coefficient);
        if (word_coefficient.numerator == 0) return error.ProjectorProgramTooLarge;
        var term = try tensorOnlyActionWordPairTerm(program.channel, left_word, right_word, word_coefficient);
        defer term.deinit();
        const rendered_coefficient = try appendVectorBrauerTermAtoms(allocator, atoms, term);
        try coefficients.append(allocator, rendered_coefficient);
        try atom_ends.append(allocator, atoms.items.len);
        emitted += 1;

        if (tensorEndpointActionNextNonzeroWordIndex(right_action, right_index + 1)) |next_right| {
            right_index = next_right;
            continue;
        }
        right_index = tensorEndpointActionNthNonzeroWordIndex(right_action, 0) orelse return emitted;
        left_index = tensorEndpointActionNextNonzeroWordIndex(left_action, left_index + 1) orelse return emitted;
    }
    return emitted;
}

fn appendTensorOnlyCandidatePairNoHodgeActionTermPage(
    allocator: std.mem.Allocator,
    program: *const TensorOnlyProgram,
    atoms: *std.ArrayList(rendering.SymbolicAtom),
    coefficients: *std.ArrayList(rendering.RationalId),
    atom_ends: *std.ArrayList(usize),
    left_action: TensorEndpointActionBuffer,
    right_action: TensorEndpointActionBuffer,
    coefficient: Rational,
    first_term: usize,
    max_terms: usize,
) !usize {
    return appendTensorOnlyCandidatePairActionTermPageCartesian(
        allocator,
        program,
        atoms,
        coefficients,
        atom_ends,
        left_action,
        right_action,
        coefficient,
        first_term,
        max_terms,
    );
}

fn tensorEndpointActionNthNonzeroWordIndex(action: TensorEndpointActionBuffer, ordinal: usize) ?usize {
    var seen: usize = 0;
    var word_index: usize = 0;
    while (word_index < action.word_count) : (word_index += 1) {
        if (action.words[word_index].word.coefficient.numerator == 0) continue;
        if (seen == ordinal) return word_index;
        seen += 1;
    }
    return null;
}

fn tensorEndpointActionNextNonzeroWordIndex(action: TensorEndpointActionBuffer, first_index: usize) ?usize {
    var word_index = first_index;
    while (word_index < action.word_count) : (word_index += 1) {
        if (action.words[word_index].word.coefficient.numerator != 0) return word_index;
    }
    return null;
}

fn tensorOnlyRenderPageAuditFromPage(
    term_count: usize,
    emitted: usize,
    atoms: []const rendering.SymbolicAtom,
    coefficients: []const rendering.RationalId,
    atom_ends: []const usize,
) TensorOnlyRenderPageAudit {
    return tensorOnlyRenderPageAuditFromPageWide(term_count, term_count, emitted, atoms, coefficients, atom_ends);
}

fn tensorOnlyRenderPageAuditFromPageWide(
    term_count: usize,
    term_count_wide: u128,
    emitted: usize,
    atoms: []const rendering.SymbolicAtom,
    coefficients: []const rendering.RationalId,
    atom_ends: []const usize,
) TensorOnlyRenderPageAudit {
    var audit = TensorOnlyRenderPageAudit{
        .term_count = term_count,
        .term_count_wide = term_count_wide,
        .emitted_count = emitted,
        .atom_count = atoms.len,
        .coefficient_count = coefficients.len,
        .atom_end_count = atom_ends.len,
    };
    for (atoms) |atom| switch (atom) {
        .vector_slot_delta => audit.vector_delta_count += 1,
        .vector_slot_metric => audit.vector_metric_count += 1,
        .hodge_star => audit.hodge_star_count += 1,
        else => audit.compact_atom_count += 1,
    };
    return audit;
}

fn prepareTensorOnlyBrauerProgramBeforePivotsForAudit(channel: TensorOnlyChannel, policy: TensorOnlyResourcePolicy) !?TensorOnlyProgram {
    const compile_policy = tensorOnlyChannelCompileProbePolicy(channel, policy);
    return prepareTensorOnlyBrauerProgramBeforePivots(channel, compile_policy) catch |err| switch (err) {
        error.TensorResourceBudgetExceeded => null,
        else => return err,
    };
}

fn compileTensorOnlyBrauerProgramForAudit(channel: TensorOnlyChannel, policy: TensorOnlyResourcePolicy) !?TensorOnlyProgram {
    var program = (try prepareTensorOnlyBrauerProgramBeforePivotsForAudit(channel, policy)) orelse return null;
    errdefer program.deinit();
    finishTensorOnlyProgram(&program) catch |err| switch (err) {
        error.TensorResourceBudgetExceeded => {
            program.deinit();
            return null;
        },
        else => return err,
    };
    if (program.term_count == 0) return error.UnsupportedStructuralProjectorTerm;
    return program;
}

