test "projector constructor absorbs symmetric input projectors into output delta orbit" {
    const channel = tensorOnlyTestChannel(2, 2, 4);
    var left_projector = try endpointProjector(channel.left, channel.dimension);
    defer left_projector.deinit();
    var right_projector = try endpointProjector(channel.right, channel.dimension);
    defer right_projector.deinit();
