    defer output_projector.deinit();

    var raw_action: TensorEndpointActionBuildBuffer = .{};
    defer raw_action.deinit();
    try appendTensorEndpointActionWord(&raw_action, .{ .word = try tensorOnlySymmetricDeltaOrbitRepresentative(channel) });

    var left_action = try applyTensorEndpointProjectorAction(channel, .left, &left_projector, raw_action);
    defer left_action.deinit();
    var right_action = try applyTensorEndpointProjectorAction(channel, .right, &right_projector, left_action);
    defer right_action.deinit();
    var full_action = try applyTensorEndpointProjectorAction(channel, .output, &output_projector, right_action);
    defer full_action.deinit();

    var output_only = try applyTensorEndpointProjectorAction(channel, .output, &output_projector, raw_action);
    defer output_only.deinit();
    try expectTensorEndpointActionBuildBuffersEql(full_action, output_only);
}

test "projector constructor cursors symmetric delta orbit action words" {
    const testing = std.testing;
    const channel = tensorOnlyTestChannel(1, 2, 3);
    const action_word_count = try tensorOnlySymmetricDeltaOrbitProjectedActionWordCount(channel);
    try testing.expectEqual(@as(usize, 15), action_word_count);

    var pure_delta_count: usize = 0;
    var trace_count: usize = 0;
    var ordinal: usize = 0;
    while (ordinal < action_word_count) : (ordinal += 1) {
        {
            var word = try tensorOnlySymmetricDeltaOrbitActionWordAt(channel, ordinal, .{});
            defer word.deinit();
            const boundary_trace_count = try tensorOnlySymmetricDeltaOrbitBoundaryTraceCount(word.word);
            switch (boundary_trace_count) {
                0 => {
                    pure_delta_count += 1;
                    try testing.expect(rationalValueEql(word.word.coefficient, try Rational.init(1, 6)));
                },
                1 => {
                    trace_count += 1;
                    try testing.expect(rationalValueEql(word.word.coefficient, try Rational.init(-1, 36)));
                },
                else => return error.ExpectedSymmetricDeltaOrbitCursorWord,
            }
        }
    }
    try testing.expectEqual(@as(usize, 6), pure_delta_count);
    try testing.expectEqual(@as(usize, 9), trace_count);
}

