test "projector constructor reports tensor-only cap audit classifications" {
    const testing = std.testing;
    const audit = tensorOnlyCapAudit(.{
        .trace_generator_count_limit = 13,
        .trace_closure_basis_limit = 21,
        .coefficient_bit_limit = 29,
    });
    const entries = audit.items();

    try testing.expectEqual(@as(usize, 10), entries.len);
    try testing.expectEqual(TensorOnlyCapBoundary.young_rows, entries[0].boundary);
    try testing.expectEqual(TensorOnlyCapDisposition.span_backed_compact_public_cap, entries[0].disposition);
    try testing.expectEqual(@as(usize, max_young_rows), entries[0].hard_limit);
    try testing.expect(entries[0].can_stop_supported_route);

    try testing.expectEqual(TensorOnlyCapBoundary.endpoint_factors, entries[1].boundary);
    try testing.expectEqual(TensorOnlyCapDisposition.public_span_ownership_audit, entries[1].disposition);
    try testing.expect(entries[1].can_stop_supported_route);

    try testing.expectEqual(TensorOnlyCapBoundary.vector_young_boxes, entries[4].boundary);
    try testing.expectEqual(TensorOnlyCapDisposition.legacy_bypass_required, entries[4].disposition);
    try testing.expect(!entries[4].can_stop_supported_route);

    try testing.expectEqual(TensorOnlyCapBoundary.trace_closure_basis, entries[6].boundary);
    try testing.expectEqual(TensorOnlyCapDisposition.resource_policy, entries[6].disposition);
    try testing.expectEqual(@as(usize, max_tensor_trace_closure_basis), entries[6].hard_limit);
    try testing.expectEqual(@as(usize, 13), entries[6].policy_limit);

    try testing.expectEqual(TensorOnlyCapBoundary.hodge_epsilon_components, entries[7].boundary);
    try testing.expectEqual(TensorOnlyCapDisposition.hard_default_needs_policy, entries[7].disposition);
    try testing.expect(entries[7].can_stop_supported_route);

    try testing.expectEqual(TensorOnlyCapBoundary.coefficient_bits, entries[8].boundary);
    try testing.expectEqual(@as(usize, 29), entries[8].policy_limit);

    var blocker_count: usize = 0;
    for (entries) |entry| {
        if (entry.can_stop_supported_route) blocker_count += 1;
    }
    try testing.expectEqual(@as(usize, 6), blocker_count);
}

