    try testing.expect(word.factor_count > max_tensor_word_factors);
    try testing.expect(word.factor_capacity >= word.factor_count);
    try testing.expect(word.factors.len >= word.factor_count);
    try testing.expectEqual(@as(usize, max_tensor_word_factors), word.factors[max_tensor_word_factors].candidate_index);
}

