    var projector = try endpointProjectorWithPolicy(tensor_channel.left, tensor_channel.dimension, .{});
    defer projector.deinit();
    try testing.expect(projector.is_identity);
    try budgetOddDoubleFactorialUsize(tensor_channel.left.slot_count, std.math.maxInt(usize));
    try testing.expectError(error.TensorResourceBudgetExceeded, budgetTensorOnlyRawDiagramTraversal(tensor_channel, tensorOnlyRawDiagramStreamKind(tensor_channel), .{ .raw_diagram_enumeration_limit = 1 }));
    try testing.expectError(error.TensorResourceBudgetExceeded, compileGeneralTensorOnlyBrauerProgramWithPolicy(tensor_channel, .{ .raw_diagram_enumeration_limit = 1 }));
}

