test "projector constructor canonicalizes projected endpoint actions during stream build" {
    const testing = std.testing;
    const allocator = std.heap.page_allocator;
    var program: TensorOnlyProgram = .{
        .channel = tensorOnlyTestChannel(1, 1, 0),
        .raw_diagram_count = 2,
    };
    defer program.deinit();

    var buckets = std.AutoHashMap(u64, usize).init(allocator);
    defer buckets.deinit();
    var next: std.ArrayList(usize) = .empty;
    defer next.deinit(allocator);
    var output_input_buckets = std.AutoHashMap(u64, usize).init(allocator);
    defer output_input_buckets.deinit();
    var output_input_next: std.ArrayList(usize) = .empty;
    defer output_input_next.deinit(allocator);
    var output_input_cache: std.ArrayList(TensorOnlyOutputInputCacheEntry) = .empty;
    defer {
        var entry_index: usize = 0;
        while (entry_index < output_input_cache.items.len) : (entry_index += 1) {
            output_input_cache.items[entry_index].input.deinit();
        }
        output_input_cache.deinit(allocator);
    }
    var candidate_buckets = std.AutoHashMap(u64, usize).init(allocator);
    defer candidate_buckets.deinit();
    var candidate_next: std.ArrayList(usize) = .empty;
    defer candidate_next.deinit(allocator);
    var audit: TensorEndpointActionCompactionAudit = .{};
    var candidate_audit: TensorCandidateCanonicalizationAudit = .{};
    var cursor = TensorOnlyEndpointActionBuildCursor{
        .program = &program,
        .projected_buckets = &buckets,
        .projected_next = &next,
        .output_input_buckets = &output_input_buckets,
        .output_input_next = &output_input_next,
        .output_input_cache = &output_input_cache,
        .candidate_buckets = &candidate_buckets,
        .candidate_next = &candidate_next,
        .audit = &audit,
        .candidate_audit = &candidate_audit,
    };

    var raw = TensorBrauerDiagram{ .coefficient = Rational.one() };
    defer raw.deinit();
    try appendBrauerInputTraceEdge(&raw, 0, 1);
    var input: TensorEndpointActionBuildBuffer = .{};
    defer input.deinit();
    try appendTensorEndpointActionWord(&input, try cloneTensorEndpointActionWord(.{ .word = raw }));
    var action = try cloneTensorEndpointActionBuildBuffer(input);
    defer action.deinit();

    const first = try appendTensorOnlyCanonicalProjectedEndpointAction(&cursor, 0, input, action);
    try cacheTensorOnlyOutputInputAction(&cursor, input, first);
    try testing.expectEqual(first, (try findTensorOnlyCachedOutputInputAction(&cursor, input)).?);
    const second = try appendTensorOnlyCanonicalProjectedEndpointAction(&cursor, 1, input, action);
    try testing.expectEqual(first, second);
    try testing.expectEqual(@as(usize, 1), program.endpoint_action_count);
    try testing.expectEqual(@as(usize, 1), program.endpoint_action_word_count);
    try testing.expectEqual(@as(usize, 2), audit.input_action_count);
    try testing.expectEqual(@as(usize, 2), audit.input_word_count);
    try testing.expectEqual(@as(usize, 1), audit.duplicate_projected_action_count);
    try testing.expectEqual(@as(usize, 1), audit.bucket_probe_count);
    try testing.expectEqual(@as(usize, 0), audit.hash_collision_count);
}

