test "projector constructor caches tensor-only endpoint actions by raw side" {
    const testing = std.testing;
    var program = try compileTensorOnlyBrauerProgram(tensorOnlyTestChannel(1, 1, 2));
    defer program.deinit();

    try testing.expect(program.endpoint_action_count != 0);
    try testing.expect(program.endpoint_action_count <= program.raw_diagram_count);
    try testing.expectEqual(program.endpoint_action_count, program.endpoint_actions.len);
    try testing.expectEqual(program.endpoint_action_count, program.endpoint_action_capacity);
    try testing.expectEqual(program.endpoint_action_count, program.action_fragment_spans.len);
    try testing.expect(program.action_fragments.len != 0);
    try testing.expect(program.endpoint_action_bucket_count != 0);
    try testing.expect(program.endpoint_action_buckets.len >= program.endpoint_action_bucket_count);
    try testing.expect(program.endpoint_action_next.len >= program.endpoint_action_count);
    try testing.expect(program.endpoint_action_compaction_audit.input_action_count >= program.endpoint_action_compaction_audit.kept_action_count);
    try testing.expectEqual(program.endpoint_action_count, program.endpoint_action_compaction_audit.kept_action_count);
    try testing.expectEqual(program.endpoint_action_word_count, program.endpoint_action_compaction_audit.kept_word_count);
    var stored_action_word_count: usize = 0;
    var action_index: usize = 0;
    while (action_index < program.endpoint_action_count) : (action_index += 1) {
        const action = program.endpoint_actions[action_index];
        stored_action_word_count += action.word_count;
        try testing.expect(action.key.raw_diagram_index < program.raw_diagram_count);
        try testing.expect(action.key.input_word_count != 0);
        try testing.expect(action.key.boundary_signature != 0);
        try testing.expectEqual(action_index, findTensorEndpointAction(&program, action.key).?);
        var other_index: usize = action_index + 1;
        while (other_index < program.endpoint_action_count) : (other_index += 1) {
            try testing.expect(!tensorEndpointActionKeyEql(action.key, program.endpoint_actions[other_index].key));
        }
    }
    try testing.expectEqual(stored_action_word_count, program.endpoint_action_word_count);

    var raw_index: usize = 0;
    while (raw_index < program.raw_diagram_count) : (raw_index += 1) {
        const output_action = tensorOnlyProjectedRawAction(&program, raw_index);
        try testing.expectEqual(TensorEndpointSide.output, output_action.key.side);
        try testing.expect(output_action.key.raw_diagram_index < program.raw_diagram_count);
        try testing.expect(output_action.word_count != 0);
    }
}

