test "projector constructor indexes tensor-only candidate-pair term windows" {
    const testing = std.testing;
    var program = try compileGeneralTensorOnlyBrauerProgram(tensorOnlyTestChannel(1, 1, 2));
    defer program.deinit();

    var covered: usize = 0;
    var active_index: usize = 0;
    var row: u8 = 0;
    while (row < program.pivot_count) : (row += 1) {
        var column: u8 = 0;
        while (column < program.pivot_count) : (column += 1) {
            const pair_slot = @as(usize, row) * program.pivot_count + column;
            const pair_index = program.pair_term_indices[pair_slot];
            if (pair_index.term_count == 0) continue;
            try testing.expect(active_index < program.active_pair_term_count);
            try testing.expectEqual(pair_slot, program.active_pair_term_indices[active_index]);
            try testing.expectEqual(pair_slot, try tensorOnlyActivePairSlotForTerm(&program, pair_index.first_term));
            try testing.expectEqual(pair_slot, try tensorOnlyActivePairSlotForTerm(&program, pair_index.first_term + pair_index.term_count - 1));
            try testing.expectEqual(covered, pair_index.first_term);
            covered += pair_index.term_count;
            active_index += 1;
        }
    }
    try testing.expectEqual(active_index, program.active_pair_term_count);
    try testing.expectEqual(program.term_count, covered);
    try testing.expect(program.term_count != 0);

    var atoms: std.ArrayList(rendering.SymbolicAtom) = .empty;
    defer atoms.deinit(testing.allocator);
    _ = try appendTensorOnlyProgramTerm(testing.allocator, &atoms, &program, 0);
    try testing.expect(atoms.items.len != 0);
}

test "projector constructor merges tensor-only action pair streams into primitive spans" {
    const testing = std.testing;
    var program = try compileGeneralTensorOnlyBrauerProgram(tensorOnlyTestChannel(1, 1, 2));
    defer program.deinit();

    var active_index: usize = 0;
    while (active_index < program.active_pair_term_count) : (active_index += 1) {
        const pair_slot = program.active_pair_term_indices[active_index];
        const row = pair_slot / program.pivot_count;
        const column = pair_slot % program.pivot_count;
        const coefficient = program.inverse_gram[row * program.pivot_count + column];
        const action_count = try countTensorOnlyCandidatePairActionTerms(
            &program,
            program.candidates[program.pivots[row]],
            program.candidates[program.pivots[column]],
            coefficient,
        );
        const pair_index = program.pair_term_indices[pair_slot];
        try testing.expect(pair_index.term_count <= action_count);
        try testing.expect(pair_index.first_term + pair_index.term_count <= program.term_count);
        var pair_terms = try tensorOnlyProgramPairTerms(&program, pair_slot);
        defer deinitVectorBrauerTermList(std.heap.page_allocator, &pair_terms);
        const count_only_pair_terms = try countTensorOnlyCandidatePairMergedActionTerms(
            &program,
            program.candidates[program.pivots[row]],
            program.candidates[program.pivots[column]],
            coefficient,
        );
        if (count_only_pair_terms > 0) {
            try testing.expectError(
                error.TensorResourceBudgetExceeded,
                countTensorOnlyCandidatePairMergedActionTermsBounded(
                    &program,
                    program.candidates[program.pivots[row]],
                    program.candidates[program.pivots[column]],
                    coefficient,
                    count_only_pair_terms - 1,
                ),
            );
        }
        try testing.expectEqual(count_only_pair_terms, pair_terms.items.len);
        try testing.expectEqual(pair_index.term_count, pair_terms.items.len);
        try testing.expect(pair_terms.items[pair_terms.items.len - 1].atom_count != 0);
    }
}

test "projector constructor releases zeroed tensor-only merged term entries" {
    const testing = std.testing;
    var set = tensorOnlyMergedTermCountSetWithLimit(1);
    defer set.deinit();

    var scalar = try vectorBrauerTerm(Rational.one());
    try appendTensorOnlyMergedTermCount(&set, moveVectorBrauerTerm(&scalar));
    try testing.expectEqual(@as(usize, 1), set.live_count);
    try testing.expectEqual(@as(usize, 1), set.entry_count);

    var negative_scalar = try vectorBrauerTerm(try Rational.init(-1, 1));
    try appendTensorOnlyMergedTermCount(&set, moveVectorBrauerTerm(&negative_scalar));
    try testing.expectEqual(@as(usize, 0), set.live_count);
    try testing.expectEqual(@as(usize, 0), set.entry_count);

    var metric = try vectorBrauerTerm(Rational.one());
    try vectorBrauerTermMetric(&metric, 1, 0, 1, 1);
    canonicalizeVectorBrauerTerm(&metric);
    var expected_metric = try cloneVectorBrauerTerm(metric);
    defer expected_metric.deinit();
    try appendTensorOnlyMergedTermCount(&set, moveVectorBrauerTerm(&metric));
    try testing.expectEqual(@as(usize, 1), set.live_count);
    try testing.expectEqual(@as(usize, 1), set.entry_count);
    try testing.expect(vectorBrauerTermAtomsEql(expected_metric, set.entries[0].term));

    var swap_set = tensorOnlyMergedTermCountSetWithLimit(2);
    defer swap_set.deinit();
    var swap_scalar = try vectorBrauerTerm(Rational.one());
    try appendTensorOnlyMergedTermCount(&swap_set, moveVectorBrauerTerm(&swap_scalar));
    var swap_metric = try cloneVectorBrauerTerm(expected_metric);
    try appendTensorOnlyMergedTermCount(&swap_set, moveVectorBrauerTerm(&swap_metric));
    var swap_negative_scalar = try vectorBrauerTerm(try Rational.init(-1, 1));
    try appendTensorOnlyMergedTermCount(&swap_set, moveVectorBrauerTerm(&swap_negative_scalar));
    try testing.expectEqual(@as(usize, 1), swap_set.live_count);
    try testing.expectEqual(@as(usize, 1), swap_set.entry_count);
    try testing.expect(vectorBrauerTermAtomsEql(expected_metric, swap_set.entries[0].term));
}

test "projector constructor pages tensor-only rendered terms without a global term buffer" {
    const testing = std.testing;
    var program = try compileGeneralTensorOnlyBrauerProgram(tensorOnlyTestChannel(1, 1, 2));
    defer program.deinit();

    var atoms: std.ArrayList(rendering.SymbolicAtom) = .empty;
    defer atoms.deinit(testing.allocator);
    var coefficients: std.ArrayList(rendering.RationalId) = .empty;
    defer coefficients.deinit(testing.allocator);
    var atom_ends: std.ArrayList(usize) = .empty;
    defer atom_ends.deinit(testing.allocator);

    const emitted = try appendTensorOnlyProgramTermPage(testing.allocator, &atoms, &coefficients, &atom_ends, &program, 0, 2);
    try testing.expect(emitted != 0);
    try testing.expect(emitted <= 2);
    try testing.expectEqual(emitted, coefficients.items.len);
    try testing.expectEqual(emitted, atom_ends.items.len);
    try testing.expect(atoms.items.len != 0);
    try testing.expectEqual(atoms.items.len, atom_ends.items[atom_ends.items.len - 1]);

    var previous_atom_end: usize = 0;
    var term_index: usize = 0;
    while (term_index < emitted) : (term_index += 1) {
        var single_atoms: std.ArrayList(rendering.SymbolicAtom) = .empty;
        defer single_atoms.deinit(testing.allocator);
        const single_coefficient = try appendTensorOnlyProgramTermAt(testing.allocator, &single_atoms, &program, term_index);
        try testing.expectEqual(single_coefficient, coefficients.items[term_index]);
        try testing.expectEqualDeep(single_atoms.items, atoms.items[previous_atom_end..atom_ends.items[term_index]]);
        previous_atom_end = atom_ends.items[term_index];
    }
}

