}

test "projector constructor budgets tensor-only action pair work before construction" {
    const testing = std.testing;
    var words = [_]TensorEndpointActionWord{.{ .word = .{ .coefficient = Rational.one() } }} ** max_tensor_endpoint_action_words;
    const allocator = std.heap.page_allocator;
    var program: TensorOnlyProgram = .{
        .channel = tensorOnlyTestChannel(1, 1, 0),
        .raw_diagram_count = 1,
        .endpoint_action_count = 1,
        .candidate_count = 1,
        .pivot_count = max_tensor_pivots,
    };
    program.endpoint_actions = try allocator.alloc(TensorEndpointActionBuffer, 1);
    defer allocator.free(program.endpoint_actions);
    program.projected_raw_action_indices = try allocator.alloc(usize, 1);
    defer allocator.free(program.projected_raw_action_indices);
    program.candidates = try allocator.alloc(TensorOnlyCandidateWord, 1);
    defer allocator.free(program.candidates);
    program.candidates[0] = .{};
    defer program.candidates[0].deinit();
    program.endpoint_actions[0] = .{
        .word_count = max_tensor_endpoint_action_words,
        .words = words[0..],
    };
    program.projected_raw_action_indices[0] = 0;
    try program.candidates[0].append(.{ .kind = .raw_brauer_diagram, .candidate_index = 0 });
    program.pivots = try allocator.alloc(usize, program.pivot_count);
    defer allocator.free(program.pivots);
    program.inverse_gram = try allocator.alloc(Rational, program.pivot_count * program.pivot_count);
    defer allocator.free(program.inverse_gram);
    var pivot_index: usize = 0;
    while (pivot_index < program.pivot_count) : (pivot_index += 1) {
        program.pivots[pivot_index] = 0;
        var inverse_column: usize = 0;
        while (inverse_column < program.pivot_count) : (inverse_column += 1) {
            program.inverse_gram[pivot_index * program.pivot_count + inverse_column] = Rational.one();
        }
    }

    try testing.expectError(error.TensorResourceBudgetExceeded, budgetTensorOnlyPairTermsBeforeConstruction(&program));
}

test "projector constructor stores tensor-only pivots past old fixed cap" {
    const testing = std.testing;
    const allocator = std.heap.page_allocator;
    var program: TensorOnlyProgram = .{ .channel = tensorOnlyTestChannel(1, 1, 0) };
    defer program.deinit();

    const pivot_count = max_tensor_pivots + 1;
    const pivots = try allocator.alloc(usize, pivot_count);
    defer allocator.free(pivots);
    var pivot_index: usize = 0;
    while (pivot_index < pivot_count) : (pivot_index += 1) {
        pivots[pivot_index] = pivot_index;
    }
    try installTensorOnlyPivotStorage(&program, pivots);
    try testing.expectEqual(@as(usize, pivot_count), program.pivot_count);
    try testing.expectEqual(@as(usize, pivot_count * pivot_count), program.pair_term_indices.len);

    const gram = try allocator.alloc(Rational, pivot_count * pivot_count);
    defer allocator.free(gram);
    @memset(gram, Rational.zero());
    var row: usize = 0;
    while (row < pivot_count) : (row += 1) {
        gram[row * pivot_count + row] = Rational.one();
    }
    program.inverse_gram = try invertTensorOnlyGram(pivot_count, gram);
    try testing.expectEqual(@as(usize, pivot_count * pivot_count), program.inverse_gram.len);
    try testing.expect(rationalValueEql(Rational.one(), program.inverse_gram[(pivot_count - 1) * pivot_count + pivot_count - 1]));
}

