        var word: TensorOnlyCandidateWord = .{};
        try word.append(.{ .kind = .raw_brauer_diagram, .candidate_index = 0 });
        try appendTensorOnlyCandidate(&program, word);
    }

    try testing.expectError(error.TensorResourceBudgetExceeded, finishTensorOnlyProgram(&program));
}

test "projector constructor treats single Hodge cross Gram terms as zero" {
    const testing = std.testing;
    const allocator = std.heap.page_allocator;
    var program: TensorOnlyProgram = .{ .channel = tensorOnlyTestChannel(1, 1, 0) };
    defer program.deinit();

    var raw = TensorBrauerDiagram{ .coefficient = Rational.one() };
    defer raw.deinit();
    try appendBrauerInputTraceEdge(&raw, 0, 1);
    program.raw_diagrams = try allocator.alloc(TensorBrauerDiagram, 2);
    program.raw_diagrams[0] = try cloneBrauerWord(raw);
    program.raw_diagrams[1] = try cloneBrauerWord(raw);
    program.raw_diagram_count = 2;
    program.projected_raw_action_indices = try allocator.alloc(usize, 2);
    program.projected_raw_action_indices[0] = 0;
    program.projected_raw_action_indices[1] = 1;
    program.endpoint_actions = try allocator.alloc(TensorEndpointActionBuffer, 2);
    program.endpoint_action_count = 2;
    const plain_words = try allocator.alloc(TensorEndpointActionWord, 1);
    plain_words[0] = try cloneTensorEndpointActionWord(.{ .word = raw });
    var hodge_word = try cloneTensorEndpointActionWord(.{ .word = raw });
    try appendTensorEndpointActionWordHodge(&hodge_word, .{
        .side = .left,
        .block = 0,
        .duality = .self_dual,
    });
    const hodge_words = try allocator.alloc(TensorEndpointActionWord, 1);
    hodge_words[0] = hodge_word;
    program.endpoint_actions[0] = .{ .word_count = 1, .words = plain_words };
    program.endpoint_actions[1] = .{ .word_count = 1, .words = hodge_words };

    var candidate_index: usize = 0;
    while (candidate_index <= max_tensor_tiny_dense_gram_candidates) : (candidate_index += 1) {
        var word: TensorOnlyCandidateWord = .{};
        try word.append(.{
            .kind = .raw_brauer_diagram,
            .candidate_index = candidate_index % 2,
        });
        try appendTensorOnlyCandidate(&program, word);
    }

    try testing.expect(tensorOnlyProgramHasHodgeActions(&program));
    try finishTensorOnlyProgram(&program);
    try testing.expectEqual(@as(usize, max_tensor_tiny_dense_gram_candidates + 1), program.sparse_pivot_audit.candidate_count);
    try testing.expectEqual(program.sparse_pivot_audit.dense_candidate_pair_count, program.sparse_pivot_audit.support_candidate_pair_probe_count);
    try testing.expectEqual(@as(usize, 0), program.sparse_pivot_audit.support_pruned_candidate_pair_count);
    try testing.expectEqual(@as(usize, 2), program.pivot_count);
    try testing.expectEqual(@as(usize, 0), program.inverse_gram.len);
    try expectTensorOnlySparseProjectorDualLaw(&program);
}

fn expectTensorOnlySparseProjectorDualLaw(program: *const TensorOnlyProgram) !void {
    const testing = std.testing;
    try testing.expectEqual(program.pivot_count, program.sparse_projector_rows.len);
    var row: usize = 0;
    while (row < program.sparse_projector_rows.len) : (row += 1) {
        var pivot_column: usize = 0;
        while (pivot_column < program.pivot_count) : (pivot_column += 1) {
            var value = Rational.zero();
            for (tensorSparseProjectorRowTerms(&program.sparse_projector_rows[row])) |term| {
                const gram_entry = try tensorOnlyCandidateInnerProduct(
                    program,
                    program.candidates[term.candidate],
                    program.candidates[program.pivots[pivot_column]],
                );
                value = try value.add(try term.coefficient.mul(gram_entry));
            }
            const expected = if (row == pivot_column) Rational.one() else Rational.zero();
            try testing.expect(rationalValueEql(expected, value));
        }
    }
}

