fn expectStructuralPageConcatenationMatchesSingleTerms(spec: StructuralProjectorSpec, page_size: usize, max_full_terms: usize) !void {
    const testing = std.testing;
    var full_cache = StructuralProjectorProgramCache.init(testing.allocator);
    defer full_cache.deinit();

    const term_count = try full_cache.termCountWide(spec);
    try testing.expect(term_count != 0);
    try testing.expect(term_count <= max_full_terms);

    var full_atoms: std.ArrayList(rendering.SymbolicAtom) = .empty;
    defer full_atoms.deinit(testing.allocator);
    var full_coefficients: std.ArrayList(rendering.RationalId) = .empty;
    defer full_coefficients.deinit(testing.allocator);
    var full_atom_ends: std.ArrayList(usize) = .empty;
    defer full_atom_ends.deinit(testing.allocator);

    try testing.expectEqual(term_count, try full_cache.appendTermPage(&full_atoms, &full_coefficients, &full_atom_ends, spec, 0, term_count));
    try testing.expectEqual(term_count, full_coefficients.items.len);
    try testing.expectEqual(term_count, full_atom_ends.items.len);
    try testing.expectEqual(@as(usize, 0), try full_cache.appendTermPage(&full_atoms, &full_coefficients, &full_atom_ends, spec, term_count, 1));
    try testing.expectError(error.ProjectorConstructorTermOutOfBounds, full_cache.appendTermPage(&full_atoms, &full_coefficients, &full_atom_ends, spec, term_count + 1, 1));

    var single_atoms: std.ArrayList(rendering.SymbolicAtom) = .empty;
    defer single_atoms.deinit(testing.allocator);
    var first_atom: usize = 0;
    var term_index: usize = 0;
    while (term_index < term_count) : (term_index += 1) {
        const atom_end = full_atom_ends.items[term_index];
        single_atoms.clearRetainingCapacity();
        const coefficient = try full_cache.appendTermAt(&single_atoms, spec, term_index);
        try testing.expectEqual(full_coefficients.items[term_index], coefficient);
        try testing.expectEqualDeep(full_atoms.items[first_atom..atom_end], single_atoms.items);
        first_atom = atom_end;
    }

    var paged_cache = StructuralProjectorProgramCache.init(testing.allocator);
    defer paged_cache.deinit();
    var paged_atoms: std.ArrayList(rendering.SymbolicAtom) = .empty;
    defer paged_atoms.deinit(testing.allocator);
    var paged_coefficients: std.ArrayList(rendering.RationalId) = .empty;
    defer paged_coefficients.deinit(testing.allocator);
    var paged_atom_ends: std.ArrayList(usize) = .empty;
    defer paged_atom_ends.deinit(testing.allocator);

    var first_term: usize = 0;
    while (first_term < term_count) {
        const emitted = try paged_cache.appendTermPage(&paged_atoms, &paged_coefficients, &paged_atom_ends, spec, first_term, page_size);
        try testing.expect(emitted != 0);
        first_term += emitted;
    }
    try testing.expectEqual(term_count, first_term);
    try testing.expectEqualDeep(full_coefficients.items, paged_coefficients.items);
    try testing.expectEqualDeep(full_atom_ends.items, paged_atom_ends.items);
    try testing.expectEqualDeep(full_atoms.items, paged_atoms.items);
}

