    const single_coefficient = try cache.appendTerm(&single_atoms, spec, 0);
    try testing.expectEqual(single_coefficient, page_coefficients.items[0]);
    try testing.expectEqualDeep(single_atoms.items, page_atoms.items[0..page_atom_ends.items[0]]);
