test "projector constructor pages no-Hodge action pairs by indexed offset" {
    const testing = std.testing;
    const allocator = std.heap.page_allocator;
    var program: TensorOnlyProgram = .{ .channel = tensorOnlyTestChannel(1, 1, 0) };
    defer program.deinit();

    var raw = TensorBrauerDiagram{ .coefficient = Rational.one() };
    defer raw.deinit();
    try appendBrauerInputTraceEdge(&raw, 0, 1);
    const word_count = 64;
    const left_words = try allocator.alloc(TensorEndpointActionWord, word_count);
    const right_words = try allocator.alloc(TensorEndpointActionWord, word_count);
    program.endpoint_actions = try allocator.alloc(TensorEndpointActionBuffer, 2);
    program.endpoint_action_count = 2;
    var word_index: usize = 0;
    while (word_index < word_count) : (word_index += 1) {
        left_words[word_index] = try cloneTensorEndpointActionWord(.{ .word = raw });
        right_words[word_index] = try cloneTensorEndpointActionWord(.{ .word = raw });
    }
    program.endpoint_actions[0] = .{ .word_count = word_count, .words = left_words };
    program.endpoint_actions[1] = .{ .word_count = word_count, .words = right_words };

    var atoms: std.ArrayList(rendering.SymbolicAtom) = .empty;
    defer atoms.deinit(testing.allocator);
    var coefficients: std.ArrayList(rendering.RationalId) = .empty;
    defer coefficients.deinit(testing.allocator);
    var atom_ends: std.ArrayList(usize) = .empty;
    defer atom_ends.deinit(testing.allocator);

    const first_term = word_count * word_count - 4;
    try testing.expectEqual(
        @as(usize, 4),
        try appendTensorOnlyCandidatePairNoHodgeActionTermPage(
            testing.allocator,
            &program,
            &atoms,
            &coefficients,
            &atom_ends,
            program.endpoint_actions[0],
            program.endpoint_actions[1],
            Rational.one(),
            first_term,
            4,
        ),
    );
    try testing.expectEqual(@as(usize, 4), coefficients.items.len);
    try testing.expectEqual(@as(usize, 4), atom_ends.items.len);
    try testing.expectEqual(atoms.items.len, atom_ends.items[atom_ends.items.len - 1]);
}

