test "projector constructor evaluates Levi-Civita signs beyond u128 bitset dimension" {
    const testing = std.testing;
    const dimension = 129;
    const allocator = testing.allocator;
    const components = try allocator.alloc(usize, dimension);
    defer allocator.free(components);
    const assignments = try allocator.alloc(usize, dimension);
    defer allocator.free(assignments);

    var index: usize = 0;
    while (index < dimension) : (index += 1) {
        components[index] = index;
        assignments[index] = index;
    }
    try testing.expectEqual(@as(i64, 1), try tensorEndpointLeviCivitaSign(dimension, components, assignments));

    assignments[0] = 1;
    assignments[1] = 0;
    try testing.expectEqual(@as(i64, -1), try tensorEndpointLeviCivitaSign(dimension, components, assignments));

    assignments[1] = 1;
    try testing.expectEqual(@as(i64, 0), try tensorEndpointLeviCivitaSign(dimension, components, assignments));
}

