    try testing.expect(!tensorOnlyChannelUsesProductYoungScalarPairingOrbitStream(tensor_channel));
    try testing.expect(!tensorOnlyChannelUsesProductFullColumnScalarPairingOrbitStream(tensor_channel));
    try testing.expect(tensorOnlyChannelUsesProductScalarInputPairingStream(tensor_channel));
