test "projector constructor compiles tensor contraction channels through Brauer Gram" {
    const testing = std.testing;

    const contraction_spec: StructuralProjectorSpec = .{
        .operator_id = 321,
        .orthogonal_dimension = 9,
        .left = .{
            .index = 1,
            .form_profile = 1,
            .form_mask = 1,
            .form_count = 1,
