test "projector constructor routes mixed form scalar pairing as one-sided pairing terms" {
    const testing = std.testing;

    const profile = (@as(u128, 1) << 0) | (@as(u128, 1) << 4);
    const spec: StructuralProjectorSpec = .{
        .operator_id = 9231,
        .orthogonal_dimension = 10,
        .left = .{
            .index = 1,
            .form_profile = profile,
            .form_mask = 0b11,
            .form_count = 2,
        },
        .right = .{
            .index = 2,
            .form_profile = profile,
            .form_mask = 0b11,
            .form_count = 2,
        },
        .output = .{ .index = 3 },
    };

    var cache = StructuralProjectorProgramCache.init(testing.allocator);
    defer cache.deinit();

    const term_count = try cache.termCount(spec);
    try testing.expectEqual(@as(u16, 10), term_count);
    try testing.expectEqual(@as(usize, 0), cache.tensor_only_entries.items.len);
    try testing.expectEqual(@as(usize, 0), cache.vector_entries.items.len);
    try testing.expectEqual(@as(usize, 1), cache.young_scalar_pairing_entries.items.len);

    var atoms: std.ArrayList(rendering.SymbolicAtom) = .empty;
    defer atoms.deinit(testing.allocator);
    _ = try cache.appendTerm(&atoms, spec, 0);
    try testing.expectEqual(@as(usize, 3), atoms.items.len);
    for (atoms.items, 0..) |atom, atom_index| {
        const metric = switch (atom) {
            .vector_slot_metric => |metric| metric,
            else => return error.ExpectedVectorSlotPrimitive,
        };
        for (atoms.items[0..atom_index]) |previous_atom| {
            const previous = previous_atom.vector_slot_metric;
            try testing.expect(metric.left != previous.left or
                metric.left_slot != previous.left_slot or
                metric.right != previous.right or
                metric.right_slot != previous.right_slot);
        }
    }
    try testing.expectEqual(@as(usize, 0), cache.tensor_only_entries.items.len);
}

