        factors[factor_index] = .{
            .index = @intCast(300 + factor_index),
            .young_row_count = 1,
            .young_rows = vector_rows,
            .young_box_count = 1,
        };
    }
    const spec: StructuralProjectorSpec = .{
        .operator_id = 9326,
        .orthogonal_dimension = 12,
