    try testing.expectEqual(TensorOnlyRawDiagramStreamKind.trace_surviving, tensorOnlyRawDiagramStreamKind(tensor_channel));
    try testing.expectEqual(@as(usize, 3), try countTensorOnlyRawDiagramStream(tensor_channel, tensorOnlyRawDiagramStreamKind(tensor_channel)));

    var program = try compileGeneralTensorOnlyBrauerProgramWithPolicy(tensor_channel, .{
        .raw_diagram_enumeration_limit = 8,
        .raw_diagram_count_limit = 8,
        .gram_action_pair_work_limit = max_tensor_solve_audit_gram_action_pair_work,
        .term_pair_work_limit = max_tensor_term_pair_work,
