    const left_ranks = [_]u8{ 2, 3 };
    const right_ranks = [_]u8{ 3, 2 };
    var factor_index: usize = 0;
    while (factor_index < left_ranks.len) : (factor_index += 1) {
        const left_rank = left_ranks[factor_index];
        const right_rank = right_ranks[factor_index];
        left_factors[factor_index] = .{
            .index = @intCast(10 + factor_index),
            .form_count = 1,
            .form_rank = left_rank,
        };
        right_factors[factor_index] = .{
            .index = @intCast(20 + factor_index),
            .form_count = 1,
            .form_rank = right_rank,
        };
    }
    const spec: StructuralProjectorSpec = .{
        .operator_id = 9320,
        .orthogonal_dimension = 12,
        .left = .{
            .index = 1,
            .factor_span = left_factors[0..],
        },
        .right = .{
            .index = 2,
            .factor_span = right_factors[0..],
        },
        .output = .{ .index = 3 },
    };

    var channel = try tensorCompilerChannelFromStructural(spec);
    defer channel.deinit();
    var tensor_channel = try liveTensorOnlyChannelFromCompilerChannel(channel);
    defer tensor_channel.deinit();
    try testing.expect(tensorOnlyChannelUsesProductFullColumnScalarPairingOrbitStream(tensor_channel));
    try testing.expectEqual(@as(usize, 5), tensor_channel.left.slot_count);
    try testing.expectEqual(@as(usize, 12), try tensorOnlyProductFullColumnScalarPairingTermCount(tensor_channel));
    var factor_pairing = (try tensorOnlyProductFullColumnScalarPairingFactorPairing(tensor_channel)).?;
    defer factor_pairing.deinit();
    try testing.expectEqual(@as(usize, 1), factor_pairing.right_indices[0]);
    try testing.expectEqual(@as(usize, 0), factor_pairing.right_indices[1]);

    const scale_audit = try tensorOnlyStructuralScaleAudit(spec);
    try testing.expectEqual(@as(usize, 1), scale_audit.candidate_kept_count);
    const solve_audit = try tensorOnlyStructuralSolveAudit(spec);
    try testing.expectEqual(@as(usize, 1), solve_audit.candidate_count);
    try testing.expectEqual(@as(usize, 12), solve_audit.term_count);

    var cache = StructuralProjectorProgramCache.init(testing.allocator);
    defer cache.deinit();
    try testing.expectEqual(@as(usize, 12), try cache.termCountWide(spec));
    try testing.expectEqual(@as(usize, 0), cache.tensor_only_entries.items.len);

    var atoms: std.ArrayList(rendering.SymbolicAtom) = .empty;
    defer atoms.deinit(testing.allocator);
    var coefficients: std.ArrayList(rendering.RationalId) = .empty;
    defer coefficients.deinit(testing.allocator);
    var atom_ends: std.ArrayList(usize) = .empty;
    defer atom_ends.deinit(testing.allocator);
    try testing.expectEqual(@as(usize, 2), try cache.appendTermPage(&atoms, &coefficients, &atom_ends, spec, 0, 2));
    try testing.expectEqual(@as(usize, 10), atoms.items.len);
    try testing.expectEqual(@as(usize, 2), coefficients.items.len);
    try testing.expectEqual(@as(u128, 12), rendering.rationalValue(coefficients.items[0]).denominator);
    for (atoms.items, 0..) |atom, atom_index| {
        switch (atom) {
            .vector_slot_metric => |metric| {
                if (atom_index < 2) {
                    try testing.expectEqual(tensorFormRankBlock(10, 2), metric.left);
                    try testing.expectEqual(tensorFormRankBlock(21, 2), metric.right);
                } else if (atom_index < 5) {
                    try testing.expectEqual(tensorFormRankBlock(11, 3), metric.left);
                    try testing.expectEqual(tensorFormRankBlock(20, 3), metric.right);
                }
            },
            else => return error.ExpectedVectorSlotPrimitive,
        }
    }

    const render_audit = try tensorOnlyStructuralRenderPageAudit(spec, 0, 2);
    try testing.expectEqual(@as(usize, 12), render_audit.term_count);
    try testing.expectEqual(@as(u128, 12), render_audit.term_count_wide);
    try testing.expectEqual(@as(usize, 10), render_audit.vector_metric_count);
}

