    var coefficients: std.ArrayList(rendering.RationalId) = .empty;
    defer coefficients.deinit(testing.allocator);
    var atom_ends: std.ArrayList(usize) = .empty;
    defer atom_ends.deinit(testing.allocator);
    try testing.expectEqual(@as(usize, 1), try cache.appendTermPage(&atoms, &coefficients, &atom_ends, spec, 0, 1));
    try testing.expectEqual(@as(usize, 26), atoms.items.len);
    try testing.expectEqual(@as(usize, 0), cache.tensor_only_entries.items.len);
    try testing.expectEqual(@as(i128, 1), rendering.rationalValue(coefficients.items[0]).numerator);
    try testing.expectEqual(@as(u128, 38_775_788_043_632_640_000), rendering.rationalValue(coefficients.items[0]).denominator);
}

