test "projector constructor budgets full-column scalar pairing pages before factorial overflow" {
    const testing = std.testing;
    const rank: u8 = 21;
    const profile = profileIncrementedRank(0, rank);
    const mask = @as(u64, 1) << @intCast(rank - 1);
    const spec: StructuralProjectorSpec = .{
        .operator_id = 9312,
        .orthogonal_dimension = 64,
        .left = .{
            .index = 1,
            .form_profile = profile,
            .form_mask = mask,
            .form_count = 1,
            .form_rank = rank,
        },
        .right = .{
            .index = 2,
            .form_profile = profile,
            .form_mask = mask,
            .form_count = 1,
            .form_rank = rank,
        },
        .output = .{ .index = 3 },
    };
    const policy = TensorOnlyResourcePolicy{ .output_term_count_limit = max_tensor_raw_diagrams };

    try testing.expectError(error.TensorResourceBudgetExceeded, tensorOnlyStructuralScaleAuditWithTensorOnlyResourcePolicy(spec, policy));
    try testing.expectError(error.TensorResourceBudgetExceeded, tensorOnlyStructuralSolveAuditWithTensorOnlyResourcePolicy(spec, policy));
    const audit = try tensorOnlyStructuralRenderPageAuditWithTensorOnlyResourcePolicy(spec, 0, 1, policy);
    try testing.expectEqual(@as(usize, 1), audit.emitted_count);
    try testing.expectEqual(@as(usize, 21), audit.vector_metric_count);
    try testing.expectEqual(@as(u128, 51_090_942_171_709_440_000), audit.term_count_wide);

    var atoms: std.ArrayList(rendering.SymbolicAtom) = .empty;
    defer atoms.deinit(testing.allocator);
    var coefficients: std.ArrayList(rendering.RationalId) = .empty;
    defer coefficients.deinit(testing.allocator);
    var atom_ends: std.ArrayList(usize) = .empty;
    defer atom_ends.deinit(testing.allocator);
    try testing.expectEqual(@as(usize, 1), try appendStructuralProjectorTermPageWithTensorOnlyResourcePolicy(testing.allocator, &atoms, &coefficients, &atom_ends, spec, 0, 1, policy));
    try testing.expectEqual(@as(usize, 21), atoms.items.len);
    try testing.expectEqual(@as(i128, 1), rendering.rationalValue(coefficients.items[0]).numerator);
    try testing.expectEqual(@as(u128, 51_090_942_171_709_440_000), rendering.rationalValue(coefficients.items[0]).denominator);
}

